/* 平成23年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h23.committeeSessions.push(...[{"id":"h23-20111004-4","meetingId":"h23-c-settlement","date":"2011年10月4日","dateIso":"2011-10-04","committee":"決算特別委員会","time":"午前１０時００分～午後５時２８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を177件整理しています。","topics":[{"id":"topic-01","title":"◯石田（秀）委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２２年度品川区一般会計歳入歳出決算","agenda":"◯石田（秀）委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"今年度も９月１７日から１２月６日という期間で開催されている最中でありますけれども、これは一体どのように決められているのでしょうか。９月１７日から１２月６日ということにパンフレットにはなっていますけれども、６月から来年の１月までの日程が載っていて、どうお考えか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"今回は鳥山玲さんの企画展を開催しまして、それが最終日１２月６日という形になっています。中小企業センターで行います日曜コンサート、そういうものも区民芸術祭の一環として取り上げてやっているものです。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"区民にも認知されやすいのではないかなと思うんですけれども、どのようにお考えなのかなと思ってお伺いしました。そういったものに対しての区民が見に行けるような優待とか、優先に関しては、どうなっているのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"優待等につきましては、特には考えておりませんけれども、もともとすべてが区民料金として設定させていただいています。協力いただいている中でご優待というような形で、アンケートもとりまして、ご優待をさせていただいているところです。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"もう少し値段が安くなるとか、そういう形の区民のために還元する制度がもう少しあってもいいんじゃないかなと思っているんですけれども、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"そして、１回目を行いまして、１回目の反省から、今回、子どもたちの活躍する場も設けました。そんな中で、３回、４回と重ねるわけですけれども、実行委員会とも協議をいたしまして、そのような形で広めていきたいと思っています。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"また、入りが相当少なかったという話でしたが、今年は五反田文化センターは２５０席ほどだったので満杯になっていました。ほかのあいている部分が少なくて、今回のオープニングセレモニーに関しては、区としてはどのようなコンセプトで行ったのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"そして場所については、昨年１０月にオープンした音楽ホールでぜひというようなお話もございまして、音楽ホールを設定させていただきました。会場が２５０席とキャパシティが少ないものですから、親御さんの席も確保したいという中で苦労しまして、そのような形になったところで…","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"次に、１０９ページの庁舎等維持管理費についてお伺いいたします。大体電力の供給時間というのはどれくらいで、また、その燃料についてはどういったものが使われているのか尋ねました。","respondent":"阿部経理課長","answer":"時間ですけれども、総合庁舎につきましては最大２５時間、防災センターにつきましては７２時間です。燃料については、特重油を使っておるものです。","id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"総合庁舎は２５時間、第二庁舎は７２時間ということですけれども、さらに今後延長できるようなことを図っていく考えはあるのか。重油ということですけれども、これは燃料はどのように確保されているのか説明を求めました。","respondent":"阿部経理課長","answer":"実際は７２時間以上、２５時間については倍ぐらいもつだろうという、今のところは大丈夫かなというふうに思っております。重油につきましては、区内の事業者と供給できるような関係をとっております。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"今の重油の供給のことなんですけれども、区内の事業者との関係ということでしたけれども、ガソリンスタンドとか、そういうことなんでしょうか。その辺も確実に供給できる体制というのはあるのか尋ねました。","respondent":"阿部経理課長","answer":"今回は事業者のタンクローリーが手配できないということで、実は大手のところから入れて満タンにしておるという状態です。その区内の事業者につきましては、今後このようなことがないようにということで、私どもから申し入れをしております。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"今回いろいろ非常用の、都市部でも大停電が起きる可能性があるということが言われていますので、ちょっと質問させていただきました。あまり時間がないのでお伺いさせていただきたいんですけれども、次なんですけれども、これは東京電力への支払いということでよろしいか尋ねました。","respondent":"阿部経理課長","answer":"庁舎の場合には東京電力と契約しております。","id":"exchange-008"},{"speaker":"沢田委員","kind":"意見","question":"今、１９９９年規制緩和があってから、電力会社をいろいろ今、大手じゃないところも使っているところがあると思うんですけれども、電力会社をほかの電力会社で特定規模電気事業者というのがあると思うんですけれども、こういったところにも入札参加を促す等のことは考えていますかとの意見を述べまし…","respondent":"阿部経理課長","answer":"確かにほかの電力を売る会社があるというふうには聞いてあります。震災以降、発電量がかなり減っているというふうにも聞いてありますので、それにつきましては今後の研究課題とします。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問・要望","question":"他市でもそういったことを検討されて、１５％以上の節約になったという話も聞いていますので、ぜひとも行政コストの削減につながるので、このような事業者を利用してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"鶴委員","kind":"意見","question":"私のほうからは、１０８ページの人権啓発費、１１３ページの生活安全推進事業についてお尋ねいたします。それから、啓発用経費等は逆に何か重点的に力を入れた部門があったのか、そのあたりの詳細を説明を求めました。","respondent":"中山人権啓発課長","answer":"その中の執行で講師の方の工夫によって金額を落とせたり、そういう積み上げがその相差となったものです。そしてあわせて、しながわ見守りホットラインというのを１０月から設置、運営をしたことによる経費増です。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"平成２０年に実施された人権にかかわる意識調査報告書によると、「知っている」が２７.６％、「知らない」が６９.８％となっております。品川区における人権尊重の根幹とも言うべき宣言を知らない人が７０％近くいるという現状でありますけれども。","respondent":"中山人権啓発課長","answer":"学校におきましては、５年から７年生向けの市民科の教科書のほうにも人権宣言は載せしています。普及啓発に努めているところではありますが、この数字のアップに向けてさらに頑張って啓発していきたいと思っているところです。","id":"exchange-012"},{"speaker":"鶴委員","kind":"提案","question":"さて、人権尊重都市品川宣言タワー設置等の提案に対する区側のご答弁は、検討の結果はどうだったのでしょうか。お知らせくださいとの意見を述べました。","respondent":"中山人権啓発課長","answer":"今はどちらかといいますと、ハードの整備でそういうタワーのようなものをつくっていくというよりは、ソフトな面でいろいろな啓発冊子ですとか、さまざま区民の方の目につく形での啓発ということで考えているところです。","id":"exchange-013"},{"speaker":"鶴委員","kind":"質問・要望","question":"私もそれぞれ現場を確認し、道路公園課、人権啓発課、生活安全担当等に迅速にご対応をしていただきました。５年生から７年生で行っているということでありましたが、それ以外の学年、これに類するような授業というのは行っておりますか尋ねました。","respondent":"中山人権啓発課長","answer":"品川区では、１年生から９年生までの市民科の全課程で人権教育の尊重をしております。その中の５年生から７年生向けの教科書にちょうどその宣言文を掲載するのとあわせまして、よく深くその観点からの人権教育を推進しています。","id":"exchange-014"},{"speaker":"鶴委員","kind":"質問・要望","question":"聞かぬは一生の恥だと思いましたので、改めて確認の意味を含めて教えていただきました。次に、１１３ページの生活安全推進事業についてお尋ねいたします。","respondent":"川崎生活安全担当課長","answer":"近隣セキュリティシステム「まもるっち」のシステムを実施していますが、平成２０年度に端末の２Ｇから３Ｇへの切り替えを予定しておりました。シルバー人材センターによるマナーアップ活動を実施していたところ、これを平成２２年から１０地区の２カ所。","id":"exchange-015"},{"speaker":"鶴委員","kind":"質問","question":"先ほどの質問でも触れましたが、先ほどの差別落書きが発生した際にも、この生活安全パトロール隊の方にご対応をしていただきました。そこでお伺いしますが、今までに何件ぐらい、今回のような差別落書きの事案に対応したことがあるか、わかる範囲で説明を求めました。","respondent":"川崎生活安全担当課長","answer":"私が着任以来、今年でありますが、５月、７月、９月に３件の落書きの事案を扱っております。","id":"exchange-016"},{"speaker":"鶴委員","kind":"質問","question":"ないことがいいんですけれども、今年度だけでなくて、前年度も含めて過去にありますか尋ねました。","respondent":"川崎生活安全担当課長","answer":"過去にはございません。","id":"exchange-017"},{"speaker":"鶴委員","kind":"質問","question":"次に、今回のような事案も含めて、パトロール中に実際に現行犯、そして検挙につなげるというようなことというのはありますでしょうか。そもそも生活安全パトロール隊は、こうした事件や事故に対して任務としてどこまで対応する権限を与えられているのか、そのあたりを説明を求めました。","respondent":"川崎生活安全担当課長","answer":"現行犯に対応するかというお尋ねですが、生活安全サポート隊は、警視庁警察官のＯＢです。したがいまして、刑事訴訟法の規定にのっとりまして、一般人としての活動しかできないという認識でおります。","id":"exchange-018"},{"speaker":"鶴委員","kind":"意見","question":"そうした部分でも、身を守るということが非常に大事なのでありますけれども、より一層そうした強化をまたお願いしたいなと思います。今後もより一層の区民の生活安全をサポートする活動の充実をお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"向委員","kind":"質問","question":"第１に、山梨県の早川町との交流事業についてと、そして続きまして、結婚サポート事業、それからＬＥＤ取付工事についてお尋ねしたいと思います。そしてまた、ここ３年ほどの延べ人数を説明を求めました。","respondent":"武内地域活動課長","answer":"しし鍋、温泉まわりだとか、そんなようなことを実施しております。トータルで行きますと、平成２２年度につきましては、２,３１９人の方がこのような早川町の交流に参加しているという実績です。","id":"exchange-020"},{"speaker":"向委員","kind":"質問","question":"平成２０年度と平成２１年度も比較のためにお伺いしたかったんですが、私も８月に初めて登りましたけれども、整備もいつぐらいからされ始めたのかをちょっと説明を求めました。","respondent":"武内地域活動課長","answer":"平成１９年度にマウントしながわ里山事業ということで、早川町と品川区の協定を結びまして、それで毎年何人かのボランティアにそれぞれ里山の自然に親しむという、そういう事業を行っております。","id":"exchange-021"},{"speaker":"向委員","kind":"意見","question":"どういった建物か拝見してきたんですが、そのときは車で行きましたけれども、少しやはり遠いなという実感を受けたんですね。ちょっと前に品川区から団体１８人前後であれば、そういうふうに利用しやすいプランというのを企画されるようなご予定というのはありますかとの意見を述べました。","respondent":"武内地域活動課長","answer":"現在も早川町のほうに団体で行かれる場合については、早川町のほうからマイクロバスを出していただいて、それで品川区民が利用する、そういうサービス提供を早川町のほうでやっております。","id":"exchange-022"},{"speaker":"向委員","kind":"質問","question":"どういった内容のセミナーとか、相談内容を教えていただける範囲で構いませんので、どういった相談を受けて４３件になったのか。そのほかに利用者の方を支援されているようなサービス等があれば説明を求めました。","respondent":"武内地域活動課長","answer":"例えばしながわ水族館で実施する場合には、水族館を見学して、軽食をいただきながらゲームをしたりだとかということの交流をするです。そこの委託業者のほうの会に入会するということで、それの一般的な費用から２５％の割引という…","id":"exchange-023"},{"speaker":"向委員","kind":"質問","question":"そうしますと、そういう事業者に紹介をするといった支援をされているということなんですが、これは１社だけということなのでしょうか。その会社というのは、選定基準とか、何かあったのかなというのが少し気になるんですが、そのあたりを少し説明を求めました。","respondent":"武内地域活動課長","answer":"この事業は今年で４年目ですけれども、そういうことで、プロポーザル方式で一番適している業者ということで選定をしています。このオーネットという会社の結婚サービスを利用していただく場合については、そういう利用料金の割引があるという制度です。","id":"exchange-024"},{"speaker":"向委員","kind":"質問・要望","question":"１０９ページ、ＬＥＤの取付工事について、最後に少しお尋ねいたします。明るさが１本でもある程度出るとか、明るさを、もっと決められた少ない電力で取り替え工事を行っていくようなお考えというのはありますか尋ねました。","respondent":"阿部経理課長","answer":"当然、求められている照度がありますので、それ以下にならないようには努めておりますので、照度測定をしながら節電をしているです。今、その品質がある程度確保されるような時期、そういう時期になりましたらＬＥＤに変えるというのも１つの方法だというふうには考えてあります。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１０８ページの非核平和都市品川宣言事業についてお聞きしたいと思います。この事業に４３９万円余の決算額が出ていますけれども、どういった事業、具体的に事業内容をお聞かせほしいと求めました。","respondent":"諸岡総務課長","answer":"非核平和のパネル展ということで、庁舎内等にパネルを展示して、これは非核平和都市品川宣言が発せられました３月に行っております。人権との連携も行っておりまして、人権についての講演と映画の集い等の場におきましても、平和人権ということでパネル展示なども行っております。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"この若者たちを広島や長崎に派遣するだとか、また、資料コーナーだとか、図書館だとか、こういったところでのこの事業で若者や区民から、何か感想なり、特徴的なことがあれば説明を求めました。","respondent":"諸岡総務課長","answer":"中学生につきましては、あるいは、社会人の皆さんは会社に帰ってみんなにぜひ伝えたいというような感想を持って帰ってこられております。たくさんの方に見ていただきまして、その場で皆さんがさまざま感想を漏らしてお帰りいただいているという状況もあります。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"こういった平和を考える機会を区民に持ってもらう、与えていくということでは、発信していくというのはとても大事なことだと思います。それで、この品川宣言、とてもすばらしいものだなと思ったんですけれども、これはどういった経緯でなぜつくられたのか説明を求めました。","respondent":"諸岡総務課長","answer":"これは昭和６０年３月２６日に、品川区が非核平和に対するその決意を内外にはっきり示す、このような目的でもって宣言が行われました。以後、この宣言に基づきまして品川区では非核平和事業等をこの宣言の普及啓発ということで実施してきているところです。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"意見","question":"品川区がこういった宣言を持っている中で、日本非核宣言自治体協議会というのを脱退されたと聞いたんですけれども、いつ脱退されて、なぜ脱退したのかを説明を求めました。","respondent":"諸岡総務課長","answer":"理由といたしましては、品川区は非核平和都市品川宣言による独自の事業を進めてきたということがあります。歩調を合わせて運動を進めていくというよりは、事業活動を進めていく、品川区独自の運動を進めてきたです。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"脱退後に、今まで世界で行われている未臨界核実験に抗議をしなくなったということをお聞きしたんですけれども、脱退したことで、こういった未臨界実験も容認していくという立場になったのかどうか説明を求めました。","respondent":"諸岡総務課長","answer":"したがいまして、そのようなときに改めて表明をしていないというだけです。品川区は既にこういったことで区の決意を内外に表明しています。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり世界でも今、独自で進めていくのも大事ですけれども、ぜひ再び連携をとって進めていっていただきたいなと思います。区民の皆さんと一緒にこの事業を応援していく、そういった活動を支援していくという、そういう考えはあるか尋ねました。","respondent":"諸岡総務課長","answer":"区といたしましては、非核平和都市品川宣言に基づく基本的には普及啓発の事業を進めながらも、他と連携できる部分については連携も図っていく、こういう考えです。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いろいろな平和への考えもお持ちですので、アイデアなど取り入れていくとか、そういった声もこれからどんどん聞いていっていただきたいなと思います。こういった品川区の事業で若者たちが得た思いにこたえるためにも、自治体協議会にやっぱり連携して復活していくという考えはございませんか尋ねまし…","respondent":"諸岡総務課長","answer":"長崎市のご協力もいただきながら連携をして行っているですが、個々にこうした他の団体との連携を図ったり、交流をしたりということは行っております。品川区は立派な宣言がありますので…","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"アメリカがオバマ政権になって核兵器廃絶という道にも進んでいくのかなと思う中でも、まだこういった実験が進んでいます。単なる物理実験なんだというふうに見解がある中で、また市長会議などにも入っていくという、そういったところはいかがか尋ねました。","respondent":"諸岡総務課長","answer":"協議会とか、地域の皆さんと草の根運動でこの平和の運動を進めていきたいということで、そういう思いからこれまで進めてきております。今後もそういった方向で平和に関する事業等を進めていきたいです。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"どうやって生きていくのか、この社会をどうしていくのかという、政治にも今注目をしてきているときだと思うんです。こういった実態もあるわけですから、区民と、いかがか尋ねました。","respondent":"諸岡総務課長","answer":"全国統一の運動を進めていくことはなく、こういったものを区民の皆さんと連携を図りながら、非核平和都市品川宣言に基づく事業を進めていくです。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはりこの品川宣言に基づくのであれば、核兵器廃絶へ進めていく、そのための製造をしていくという推進のために行っている未臨界核実験、これについてはどう考えているのか説明を求めました。","respondent":"諸岡総務課長","answer":"品川区の見解につきましては、非核平和都市品川宣言、これで非核平和に関する品川区の決意、これを既に内外に表明しておりますので、そういった１つ１つの事象に対して改めて表明するというようなことではなく、既に非核平和都市品川宣言で品川区の決意は表明をしています。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"未臨界核実験についてをお聞きしたいので、もう一度お願いします。","respondent":"諸岡総務課長","answer":"それぞれ核実験、それぞれの国において行われているというところがありますけれども、品川区といたしましては、既に品川区の見解決意は申し上げているところです。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もう時間もないので、やはり未臨界核実験について、もっと区として具体的に考えをお持ちほしいと求めました。そして、これに恥じない対応を区として行っていただいて、若者にやはり未来と展望を与えるような姿勢で進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"私は、それから１２０ページの災害時応急物資確保費、１２１ページの防災普及教育費についてご質問させてほしいと求めました。これ、１億６,５３４万円と書いてありますが、これは具体的に何なのかご教示をお願いいたします。","respondent":"吉岡保育課長","answer":"品川区内の幼稚園教育につきましては、私立幼稚園が中心になって実施をしています。私立幼稚園の振興あるいは保護者の方の教育に対する援助、そのようなものを目的として、私立幼稚園の保護者の方に交付をする補助金です。","id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それで、ちょっとお聞きしたいんですが、平成２３年度の私立、区立も一緒でも結構なんですけれども、幼稚園の入園希望者と、実際入園した数についてわかりましたら、ご提示をお願いしたいと思います。","respondent":"吉岡保育課長","answer":"すみません、私立幼稚園のほうは、それぞれの園で募集をされていますので、ちょっと今、詳細な数字はつかんでございません。区立幼稚園について、ちょっと今、資料が出ないので、後ほどということでお待ちいただきたい。","id":"exchange-039"},{"speaker":"鈴木（博）委員","kind":"質問","question":"来年また１園なくなる予定で、さらにもう１園なくなりそうだということで、実際幼稚園の数が今かなり減っていますよね。保育園の非常に大幅な増設に比べて幼稚園に関しては、今どういうお考えなのか、一言ご教示をお願いいたします。","respondent":"吉岡保育課長","answer":"もともと保育園というのは就労等で保育に欠ける状態のお子さんを親御さんにかわってお預かりして保育をする。５歳、平成１４年の二葉すこやか園の幼保一体施設の設立以来、区立幼稚園については区内の幼児教育を支える重要な柱というふうに認識しています。","id":"exchange-040"},{"speaker":"鈴木（博）委員","kind":"質問","question":"結局、幼稚園に関しては、幼保一体化で推進するということで理解してよろしいんでしょうか。それで、幼稚園に関しては現状維持というようなことになるのか尋ねました。","respondent":"吉岡保育課長","answer":"私立がやっぱり区内では中心、数的にも現在で１９園対９園ということで、倍以上の数の違いがあります。当面、現在の私立幼稚園の体制、あるいは区立幼稚園の体制をこのまま継続していく形になるのかなというふうに現在は考えてあります。","id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に１２０ページの災害時応急物資確保費、実際アナフィラキシーショックが起きたときに、それに対する対策というのも非常に重要だと思うんです。この物資の中に入るかどうかは微妙なんですが、これは考慮の中に入っているかどうか、ちょっとお聞きしたいんですが。","respondent":"中山防災課長","answer":"アレルギー食品のお尋ねですけれども、そのショックを起こした場合の医薬品の備蓄は、備蓄量がかなりになりますので、ちょっと調べないとわからないという状況ですね。","id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"残念ですが、今の質問はここで終わらせていただきます。１２１ページの防災普及教育費、１６４万円計上されているんですが、これは具体的にはどういうものなんか尋ねました。","respondent":"高山防災計画担当課長","answer":"こちらのほうの訓練用のＡＥＤですが、下のほうに載っております地域防災スクール事業のほうで活用するために買った備品でございまして、防災課をはじめ地域センター、それから地域防災スクールのモデル校となった２校に訓練用として配置するものです。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"物はあるんだけど使えないとか、これをメンテナンスしたり、ＡＥＤに関しては常にその辺を考慮して検討いただけたらいいと思います。これは要望ということでご返答は要りません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"阿久津委員","kind":"質問","question":"予算ですと相談業務委託が１２回という想定で、今回決算で個別相談が４３件あったんですが、これは同じ方が相談されている延べ回数なんでしょうか。この予想を上回る結果だった分析を教えていただけますか尋ねました。","respondent":"武内地域活動課長","answer":"１２回というのは、毎月１回日にちを設定して相談を面会式でやっておりまして、１日７人を総枠という形で受け付けしております。一般的には本人だとか、ご家族の方だとかという形の中で、そうリピーターの方はいないというふうにこちらは認識しております。","id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問","question":"お伺いしたいのは、３年で１４４件以上の結婚相談のご経験を経まして、品川区特有の結婚に関する課題のようなものは何か見えてきたのでしょうか。それに対して品川区は今後どのような施策を講ずるのか尋ねました。","respondent":"武内地域活動課長","answer":"リピーター的には参加できないというところが非常に結婚につなげられないということが参加者の個々の声からよく聞かれます。区民が会うようなそういうイベントだとかというものを計画して、何回か参加できるような形態に持っていきたいなと今検討しています。","id":"exchange-046"},{"speaker":"阿久津委員","kind":"質問・要望","question":"このセミナーと交流会の参加者同士の結婚が現在までに８名４組、また、一定の効果があって評価すべきだというふうに考えております。１つお伺いしたいのが、１０％近く大きく品川区の未婚率が上回っているということで、この品川区の分析というのをお聞かせほしいと求めました。","respondent":"武内地域活動課長","answer":"地域に対する希薄性とかということも言われる中、現在の都会と地方の若者の結婚に対する認識というのもかなり違うというように考えております。品川区の場合で行きますと、中小企業ということで、なかなか男女の出会える機会がないというのも要因かなというふうに考えております。","id":"exchange-047"},{"speaker":"阿久津委員","kind":"質問","question":"区内でひとり暮らしをしている私の友達も、やはり結婚を考えたり、所帯を持ってしまうと品川区を出てしまうという形が非常に多いです。ちょっとこれ、若者世代の定住に向けた施策に力を入れていると思うんですが、この結婚サポート以外に力を入れている事業があったら説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"全体的な若者等の定住の施策ですけれども、今、委員からご指摘のありました、例えば親元近居支援事業とか、あとは二世帯住宅の改修助成とか、そういったものを広く総合的に展開をしています。","id":"exchange-048"},{"speaker":"阿久津委員","kind":"提案","question":"先日の一般質問で、本区独自の花火大会というのを提案させていただきました。最後に１つ提案なんですけれども、例えば一定の所得以下の若者世帯への家賃補助等について検討を考えたらどうかと思いますが、いかがか尋ねました。","respondent":"榎本企画財政課長","answer":"若者世代は流動性が高いものですから、補助がある間だけ住んでいて、補助がなくなれば出ていくというような傾向にあったようなことを聞いております。そういった意味では、なかなかそういう形だけでは難しくて…","id":"exchange-049"},{"speaker":"阿久津委員","kind":"提案","question":"１つの提案とさせていただきましたが、また複合的、重層的な子育て支援策も含めてしっかりとした定住策をまたお願いさせてほしいと求めました。お伺いしたいのが、リニューアルからちょうど１年が経過しまして、簡単で結構ですので例を挙げてご説明ほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"そのあと３割程度が朗読の発表会だとか舞踊、会議等があります。その次にクラシックコンサート、あとピアノコンサート、吹奏楽の演奏会等です。","id":"exchange-050"},{"speaker":"阿久津委員","kind":"確認","question":"１つ、これは今年の３月に案内板を追加したということを伺っていますが、これはしっかりと設置をされているのでしょうか。これを建て替えるというわけにはいかないんですが、これ、どういうコンセプトでそういうふうになったのかということを１点お伺いします。","respondent":"安藤文化スポーツ振興課長","answer":"２点目の２５０席の席の一列のことですが、これに関しましては、建設する前に品川区の音楽の団体の方々にお話をさせていただきました。それから緞帳につきましては、委員ご指摘のとおり、音楽ホールということで緞帳はございません。","id":"exchange-051"},{"speaker":"阿久津委員","kind":"質問","question":"真ん中に席をつくらなかったという、音楽団体のご意見を伺ったというふうに聞こえたんですが、ちょっとそこだけもう一度ご答弁をお願いします。","respondent":"安藤文化スポーツ振興課長","answer":"真ん中の席ですけれども、音の響きをいたすためのことです。","id":"exchange-052"},{"speaker":"阿久津委員","kind":"質問","question":"１２０ページ、防災対策費、災害時要援護者支援経費、１点だけお聞きします。品川区の災害時要援護者の安全確保に関する要綱の(3)に、これはどのような形で希望すればいいのか、その方法を説明を求めました。","respondent":"中山防災課長","answer":"この「特に希望する者」というのは、実際に該当していなくても、同居されている６５歳以上のお年寄り、この方については同様に登録が可能だです。〔時間切れにより答弁なし〕","id":"exchange-053"},{"speaker":"渡辺委員","kind":"確認","question":"決算額との開きがかなりあることと、当然、事業名称の変更があったのか、私の読み違いかどうか、ちょっと確認を含めて伺いたいです。それと、この携帯電話用のホームページというものの位置づけと目的をどのように考えておられるか伺いたいと思います。","respondent":"武内地域活動課長、荒井広報広聴課長","answer":"コミュニティ活動支援の３９０万円という部分ですけれども、この内容は、各連合町会のほうに３０万円ずつの補助という対象になっております。ですから、パンフレットだとかという部分の予算はこちらのほうに計上されているものです。 それから、携帯でも気軽にホームページを見ていただけるという意味合いでの位置づけです。詳しいことにつきましては、携帯電話からパソコンで見てくださいというようなご案内もさせていただいているところです。","id":"exchange-054"},{"speaker":"渡辺委員","kind":"提案","question":"そういう中での提案的なものにはなりますが、来外者、どんなお店があるだろうという中でマイスター店の紹介も１つあるのかなという思いがあります。広く考えれば、本当に入り口の段階で携帯電話用ホームページというのは活用の仕方があるのかなと思ったので…","respondent":"武内地域活動課長、荒井広報広聴課長","answer":"コミュニティ活動支援という部分については、町会のホームページの作成支援、町会塾の実施等。事故が起こるというような状況の中で、ふれあい保険という部分で区のほうで助成しているという、そういう内容です。 現在でも携帯電話からメールマガジンの登録をすることは可能になっております。現在、約３,５００人弱の方たちに登録をしていただいておりますので、今後さらにＰＲを進めていきたいというふうに考えているところです。","id":"exchange-055"},{"speaker":"渡辺委員","kind":"質問","question":"その中でいろいろな課題の点の見直しもあるでしょうが、これは大きく分けてどのような見直しなのか、まず１点伺いたいと思います。これも事務事業評価で拡充すべきと、対象となる国はどのように集約をしていっているのか、その辺の経緯を説明を求めました。","respondent":"今井協働・国際担当課長","answer":"見直しのあり方は２点考えておりまして、これ以上に私どもと連携をする中で、区の交流事業の実施主体としての役割を明確にしていくことが１つ。今ご指摘のとおり、昭和５９年のポートランド市から３都市交流してまいりまして…","id":"exchange-056"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その流れの中で、長期基本計画の中で、最初の友好都市交流事業の点で伺うと、産業振興分野での都市間交流がまず１つある。特に産業振興分野では、あるいはタイの場合だと区内の大使館という先ほどの根拠の１つにもなると思いますので、その点を説明を求めました。","respondent":"今井協働・国際担当課長","answer":"現在、平成２１年度に調査を開始しまして、自治体と区とどういうふうな連携があるかというのをアジア地域の大都市ということで調査してまいりました。今後そういうふうな動向も踏まえながら検討を進めていく必要があるというふうに考えております。","id":"exchange-057"},{"speaker":"渡辺委員","kind":"質問","question":"今ご説明あったように、区民にどのようなメリットというか、かかわりが見込めるかどうかがポイントになると思うんですね。向こうから得るもの、そしてこちらから発信するもの、これはどのような検討のポイントや条件になってくるのか説明を求めました。","respondent":"今井協働・国際担当課長","answer":"委員ご指摘のとおり、国際交流というのは、国際協力、そして外国人支援などといろいろな動きの中で今進んでおります。やはり今、委員ご指摘のとおり、成果目標をはっきりさせた交流が今求められている交流の姿だというふうに考えております。","id":"exchange-058"},{"speaker":"吉田委員","kind":"確認","question":"前年度の平成２１年度が２億７,０５８万２,１７２円である、確認の意味も込めまして理由をお聞かせください。普通に使っていて耐久性はどのくらいか尋ねました。","respondent":"川崎生活安全担当課長","answer":"これは平成２０年度に２Ｇから３Ｇへの変更を予定していたところ、製造委託費の７,８７５万円が、平成２１年度の支出となったためです。最後に４点目の耐久性という問題ですが、ある程度の耐久性はあると認識しております。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"しっかりしていただきたいという、６年使って、また１年生に行くということですよね。そうですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問","question":"オプションである携帯電話の機能についてお伺いしたいんですけれど、そして保護者の負担の金額ですが、基本料はお幾らでしょうか。保護者以外にどのような方がいらっしゃるのか、人数の内訳と、またそれの研修会等がございましたら説明を求めました。","respondent":"川崎生活安全担当課長","answer":"続きまして、協力者の数ですが、協力者については、総数で１万３,０５７名おります。保護者が１万５６７名、これは主に町会長や青少年対策地区委員等々を含みますが１,５７４名、会社の経営の方など８８９名の方が加入されております。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"夜８時以降も４３２人の件数があります。その働きかけと、先ほどちょっと研修会等がございましたらというお話を伺いしたいんですけれども、お願いします。","respondent":"川崎生活安全担当課長","answer":"来月１１月１７日と２２日の２回に分けて、区役所の講堂で協力者の方々を集めて研修会を行う予定です。３回目として、来年２月に荏原文化センターのほうで実施する予定です。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問","question":"ここで最後に、協力者に配られる緑の帽子なんですけれど、今でも配っていらっしゃるかどうかをお聞きしたいです。","respondent":"川崎生活安全担当課長","answer":"協力者の方にお配りする帽子のお尋ねです。これにつきましては、協力者になるときに帽子を配るのですが、現在も配っております。","id":"exchange-063"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、広報の印刷なんですけれども、個を例にしますが、ミニ区勢概要と区勢概要は、部数は１１倍なのに、コストは３倍になっています。こういういわゆる印刷物のコストなんですけれども、どこが所管して、どこがチェックを入れているか答弁ください。","respondent":"久保田行財政改革担当課長、梶戸籍住民課長、榎本企画財政課長","answer":"１点目の図書館についてお答えいたします。教育委員会のほうにそのまま残させていただいて、ただ、連携は両者で推進していこうということの組織改正を行っ… ただいま組織改正とあわせまして、武蔵小山サービスコーナーのご質問がございましたので、ちょっと説明をします。… 基本的には予算編成の中で、予算査定の中である程度見積もりをとって、部数と金額とを確認していくというのが第一段階です。規模によりますけれども…","id":"exchange-064"},{"speaker":"藤原委員","kind":"質問","question":"結婚サポートについて改めてお伺いするんですけれども、内容はもう４年間やっていますから十分わかっております。行政改革という意味でお伺いしたいんですけれども、行革の観点から、この事業についてどういうふうに考えるか答弁ください。","respondent":"梶戸籍住民課長、阿部経理課長、久保田行財政改革担当課長","answer":"大井町に比べると３分の１程度の住民票の発行件数になってありますけれども、それなりに需要はあるのかなと考えております。… 先ほど企画財政課長からも話がありましたけれども、その中で最低の価格で入れたもの、こういう経済面のチェックをしているです。 ２点目の結婚サポート事業についてですけれども、こちらにつきましては、民間事業者でも実際にこういった事業を行っているところはあります。…","id":"exchange-065"},{"speaker":"藤原委員","kind":"質問","question":"昨日、厳しい財政状況になるという中においても、こういう民でできる仕事は民でということじゃなくてやっていくおつもりがあるのでしょうか。本当の行革というのは、民がやれるものは民なんじゃないか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"平成２４年度、私どもとしてももう一度実施いたしまして、見極めは必要かとは思っております。","id":"exchange-066"},{"speaker":"金野委員","kind":"質問・要望","question":"１１１ページの公金取扱事務費、それから１２１ページの過誤納金返還金、時間があれば１０９ページの庁舎等維持管理費をお伺いしたいと思います。１１１ページの公金取扱事務費ですけれども、この実務内容をまず確認させてほしいと求めました。","respondent":"福田会計管理者","answer":"こちらにつきましては１０円を支払っております。ゆうちょ銀行に対しましてお支払いをする、ゆうちょ銀行から区に入ってくる場合でありますけれども、こちらにつきましては３０円です。","id":"exchange-067"},{"speaker":"金野委員","kind":"質問・要望","question":"公金取扱手数料が、前年平成２１年度は９６４万７,５５８円でした。去年平成２１年度の決算額、かなり予算額よりも平成２２年度は減っているというところで、現状を教えてほしいと求めました。","respondent":"福田会計管理者","answer":"減った要因として１つ考えられるのは、これとは別にコンビニ収納というのが数年前から始まっておりまして、その件数が漸増傾向にあります。これが大きな要因ではないかというふうに考えております。","id":"exchange-068"},{"speaker":"金野委員","kind":"質問","question":"もう１つ、この手数料には、いわゆる今度は支出の部分です。ＡＴＭで現金で支払うという場合もあるでしょうし、いろいろな方法がありますけれども、どのような方法をとられていますか尋ねました。","respondent":"福田会計管理者","answer":"もう１つは、指定金融機関以外の金融機関が持っている口座に振り込む。ここが一番大きな相違点でございまして、前者は無料、後者は有料、このような違いがあります。","id":"exchange-069"},{"speaker":"金野委員","kind":"質問","question":"いわゆる指定金融ですから、例えば電信ですから銀行の窓口を通ってする電信のもの、そういったお考えでの振り込み方とするお考えはありますか尋ねました。","respondent":"福田会計管理者","answer":"これは品川区だけではなくて、ほとんど全部そうです。ただ、これはできるだけ私どもがフロッピーディスク化をいたしましたり、そのような形で対応しているのが現状です。","id":"exchange-070"},{"speaker":"金野委員","kind":"意見","question":"カードは使わない、こうした取り決めだということですので、わかりました。そこで、今、ネットバンキングみたいなこともありますので、将来的にはそういったこともお考えなのか、参考までにお聞かせ願いたいと思いますとの意見を述べました。","respondent":"福田会計管理者","answer":"いろいろ技術革新は急速に進んでおりますが、今のところ、私どもは特に考えておりません。それらの大きな全国的なシステムの中で考えざるを得ないような問題だろうというふうに思っておりますので、なかなか具体的には今考えてはおりません。","id":"exchange-071"},{"speaker":"大倉委員","kind":"質問・要望","question":"１１２ページの地域活動費と、１１４ページの文化スポーツ振興費、そして時間があれば１０９ページの庁舎等維持管理費についてお伺いいたします。１１２ページの地域活動費についてお伺いさせてほしいと求めました。","respondent":"武内地域活動課長","answer":"こちらの町会支援ということで、ホームページの立ち上げの支援をしているわけですけれども、平成２０年度が開始でございまして。","id":"exchange-072"},{"speaker":"大倉委員","kind":"意見","question":"年々減少傾向にあるのがわかりますが、今後これからまた品川区総合実施計画の第二次でもこれからまた続いていくということなんですが、今後この事業を増やしていきたいのか、それともこのまま町会が手を挙げなければこのまま維持をしていくだけになってしまうのか説明を求めました。","respondent":"武内地域活動課長","answer":"いわゆる地域とのおつき合いの希薄性という部分がある中で、また、インターネットを使った情報収集ということが非常に区民の方も利用されている。そういった意味では、このような事業を進めていくことは、今後もさらに進めていかなければいけないというふうに考えてあります。","id":"exchange-073"},{"speaker":"大倉委員","kind":"意見","question":"利用が多少あるということなんですが、例えばホームページを開いてもアクセス件数等は載っていないということなんですが、こういった中でどのように件数が増えているとか、そういった部分をおっしゃっているのか、もしわかれば説明を求めました。","respondent":"武内地域活動課長","answer":"それぞれ３０町会のアクセス件数等のそういう表示はありませんけれども、こういう時代ですので、インターネットを使った情報収集というのはかなり区民の方に行われているというふうに考えております。","id":"exchange-074"},{"speaker":"大倉委員","kind":"質問・要望","question":"続きまして、１１４ページ、文化スポーツ振興についてお伺いいたしたいと思います。この地域スポーツ推進の４事業についてご説明をお願いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"教室とかそういうものを行いまして、区民の方に参加していただく、その４つの事業です。３つ目には合同事業と、あと４つ目には、新しいスポーツということでニュースポーツの普及という４つの事業です。","id":"exchange-075"},{"speaker":"大倉委員","kind":"質問","question":"スポレクというのがあるということですが、今、その下に地域スポーツクラブ事業というのもありますが、これはスポレクとは違うのでしょうか。ご説明ください。","respondent":"安藤文化スポーツ振興課長","answer":"平成１９年度から３年間、設立準備をしてまいりまして、平成２２年３月２８日に設立したところです。これが地域スポーツクラブ事業のことです。","id":"exchange-076"},{"speaker":"大倉委員","kind":"質問","question":"スポレクとスポクラがあるということなんですが、この違いは一体どこになるのか。地域スポーツクラブが品川・大崎地区だけ４地区の中でやっているということなんですが、なぜその地区になったのか、実績がわかれば説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"品川区にはもう昭和５７年から、スポレク育成事業ということで、品川区内のスポレクをつくってまいりました。そんな中で大きく４つのブロックに分けてございましたけれども、東京都のほうからぜひ地域スポーツクラブを育成してほしいというお話がまいりました。","id":"exchange-077"},{"speaker":"大倉委員","kind":"意見","question":"今後、地域にこのスポーツクラブが、今１カ所でありますが、あとのほかの残りの３つのところにもそのスポクラをしていこうという思いなのか、それともまずここで少しの間実施をしてみて今後につなげていくのか説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"ほかの地区へもスポーツクラブをしていくかとうかですけれども、やはりほかの３地区もご相談申し上げまして、ぜひ同じような形で地域スポーツクラブを設立してまいりたいと考えています。","id":"exchange-078"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ地域に合ったニーズ等もあると思いますので、やり方を慎重に考えていただきながら、今後もぜひ区民の皆様の声を聞いて導入していくということであればお願いしたいなと、地域の声をぜひ反映させていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"山内委員","kind":"質問・要望","question":"それをまず教えていただきたいということと、それを教えてほしいということと、件数が表示されています。これは加算金ならびに還付金、金額で表示できないものなのか、そのあたりをお願いします。","respondent":"高森税務課長","answer":"還付未済というのが例えば平成２２年度、請求が行われなかった場合につきまして翌年度６月１日以降に過誤納還付金として返還をするものです。その関係の中で、源泉徴収されておりますけれども、確定申告によりまして大きな形での返還金が生じるというふうなものが入ってあります。","id":"exchange-080"},{"speaker":"山内委員","kind":"質問","question":"加算金の考え方をちょっとお伺いしたいんですが、加算される利率が考えられると思うんですけれども、その利率といったものは何％ぐらいなのか。そのあたりというのはどのようなお考えなのか説明を求めました。","respondent":"高森税務課長","answer":"先ほど、還付金と還付加算金の件数が出ているけれども金額ということで、まずそこからご説明いたします。過誤納金に付される利子としての性質を持っているものでございまして、ある意味、延滞金に対応するものです。","id":"exchange-081"},{"speaker":"山内委員","kind":"質問","question":"難しくてわからないんですけれども、４.３％というのが１つの基準なわけですよね。期間が例えば長引くと、それに対するいわゆる利息といったものが加算されるということはないという解釈じゃなくていいわけか尋ねました。","respondent":"高森税務課長","answer":"ですから、この過誤納還付金につきましても、年４.３％という形で還付加算金がプラスされます。ただ、支払う日までではなく、区のほうで支払いを決定した日、すなわち還付の通知を出した日までが還付加算金の適用期間という形になります。","id":"exchange-082"},{"speaker":"山内委員","kind":"質問","question":"後日改めて伺います。ちゃんと説明をし、そこが僕はサービスの１つではないのかなと思うんですが、そういった部分はどのようにされているのか説明を求めました。","respondent":"高森税務課長","answer":"二、三週間後ぐらいに郵送でご案内を差し上げるというふうな形で、混乱のないようなサービスをしています。","id":"exchange-083"},{"speaker":"山内委員","kind":"質問・要望","question":"これは貸付金額といったものがどれぐらいになるのか、これは公立、私立で違ってくるのでしょうけれども、その金額を教えていただきたい。そこを説明を求めました。","respondent":"小林青少年育成課長","answer":"毎月の授業料相当分等にあがなう部分が、公立が月額１万３,０００円、私立が２万８,０００円。あわせまして、新たに入学する場合の入学準備金に相当する部分に対しましては、公立は７万円、私立は２０万円となっております。","id":"exchange-084"},{"speaker":"山内委員","kind":"意見","question":"これも先ほどの過誤納金のところと同じような感じなんですけれども、貸付の金額がたしか予算書では大体幾らというのが出ているんです。それが１つになってしまっていて、それを決算書で分離することはできないのかなと思うんですけれども、これは率直な疑問なんですとの意見を述べました。","respondent":"小林青少年育成課長","answer":"歳出の部分につきましては、貸付金ですので、これを公立、私立の人数ごとに分ける、具体的に言えば、１０９ページの在学資金１６６人が、公立が何人で私立が何人かという表示は可能ですので、その表記については検討してまいりたいと思います。","id":"exchange-085"},{"speaker":"山内委員","kind":"質問・要望","question":"これは要は貸付ということですから、１９７万円余で決算されていますけれども、いろいろな部分で滞納といったことが１つ問題視されています。学校生活はどうですかとか、例えばその本人も、自分は奨学金で学校へ行っているんだよという意識の向上になると思うんです。","respondent":"小林青少年育成課長","answer":"平成２０年度が３,３７１万９,０００円、平成２１年度が３,８２８万７,０００円、平成２２年度が４,３８４万７,０００円となっております。毎年、返還の状況等も参考資料として併記するような形が可能ではないかというようなことを検討しておりますし…","id":"exchange-086"},{"speaker":"飯沼委員","kind":"確認","question":"それをお伺いしたいのと、それをトータルすると、常勤者の総数が出るのかどうか。もう１点なんですが、各款の職員給与数の書かれているトータルなのかどうか、そこを確認させてください。","respondent":"堀越人事課長、榎本企画財政課長","answer":"人材派遣ですが、人事課のほうでは欠員の代替ということで、平成２２年度は７名人材派遣を派遣をしてもらっているというものであります。そのほかの数字につきましては、各所管のほうで把握しているというものです。 最後の決算状況一覧のほうの人数ですけれども、これにつきましては、定員管理調査という調査に基づく数字を上げるということで、それを入れているものです。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問","question":"最初のほうなんですけれども、人材派遣とか、各職場で把握ということでは、人事のところでは把握をしていないということなんでしょうか。その欠員７名分はどこの場所なのか、もう１回説明を求めました。","respondent":"堀越人事課長","answer":"人材派遣の平成２２年度の部分につきましては、産休代替の配置ですとか、それから欠員の補充というような形で配置しております。配置の職場ですが、保育課、戸籍住民課、荏原第一地域センター、広報広聴課で計７名です。","id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺を教えていただきたいのと、主な委託の内容を紹介していただきたいのと、総体でどのくらいあるのか説明を求めました。","respondent":"堀越人事課長、久保田行財政改革担当課長","answer":"委託の細かい箇所数については、今、私どもの資料ございません。経費の削減と、それからサービス向上、こういった効果を図っているというものです。 その委託した事業を民間事業者なりにやってもらうですので、それの細かい人数については、私どものほうでは把握はしてございません。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"今回決算ですけれども、評価をする上でやはり明らかになっていなければいけないことだと思うんですが、その点はいかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"私どものほうは、外部委託という形で効率的な区政運営を進めていくといった中で、民でできるものは民の力を借りて、それぞれの区民サービスの向上に向けて展開を進めていくというものですので、効率的な区政運営を進めていく中で、外部委託いうものは、今、推進しています。","id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問","question":"改めまして、今、民ができることはという話、委託を進めている理由を改めてお伺いしたいと思います。区のその辺の基準があるのかどうか、その辺も聞かせてください。","respondent":"久保田行財政改革担当課長","answer":"委託を今進めていますけれども、民間委託なり、指定管理制度を使いまして進めていきたいです。より効率的な事業執行または経費的にも抑制ができる、削減ができるといったものについて、それぞれ個々の事業に応じて委託を進めているところです。","id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問","question":"実際の仕事の量をとらえていく中で、質の確保を進めていくことで、どこまで進めていくのか。どこまで線が引かれているのか、全くそれがないのかどうか、そこをお伺いします。","respondent":"久保田行財政改革担当課長","answer":"私どもは、効率的な事業執行とか、経費の抑制といった意味で委託を進めています。そうした中で私どもは質の確保を図りながら、効率的な区政運営というところを考えながら委託を進めていっているところです。","id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つ１つ見ていくのはわかるんですけれども、ゴールがどこに行くのかというあたりのイメージはどうなっているのか、とても心配なんです。今、品川区の定数がどうなっているのかということを聞かせていただきたいのと、ちょっとその辺の定数の考えも聞かせてください。","respondent":"久保田行財政改革担当課長、堀越人事課長","answer":"そのゴールを目標に持って委託は進めているところではなくて、それぞれの事業の特性に応じて委託を進めまして、そういった行政目的を達成していきたいというふうに考えているところです。 職員条例定数ですが、平成２３年４月１日で２,５２３名です。","id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問","question":"官製ワーキングプアのことについてお伺いしたいと思います。私はこの点を問いたいと思いますが、ぜひ正規雇用を増やすべきであると思いますが、いかがか尋ねました。","respondent":"堀越人事課長","answer":"私ども品川区の職員定数、職員の人員管理の考え方ですけれども、執行体制の見直し、それから、事務作業の効率化という形でやっているところです。今ご質問ありました若者雇用という観点では、またそれはいろいろ法令にのっとって対応していくということで考えているところです。","id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問・要望","question":"８時間２０日間で年間１９２万円、８時間で２０日間で年間２１６万円、結婚もできないんですね。自治体はみずから本当に景気回復、こういった委託を進めていく、低コストの労働者を増やしていくという体質は本当に改めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"渡部委員","kind":"質問・要望","question":"どのような感じなのか、区から逆に相当数入られたのかというところを１つ伺いたいのと、今回から回収しなくてよくなりました。平成２４年当初からこの平成２２年度の国勢調査、国全体で用いていくのか、その数字の扱い方の辺を含めてまず教えていただけますか尋ねました。","respondent":"武内地域活動課長","answer":"全国的には非公開というような対応をとらせていただいているんですけれども、品川区では１１％という割合で、郵送の回収率が５７％です。平成２３年１０月末には人口の確定をさせていただきまして、平成２５年３月には最終的な今回の国勢調査のまとめができる予定になっておりま…","id":"exchange-096"},{"speaker":"渡部委員","kind":"質問・要望","question":"これは要望なんですけれども、これからどういうふうにしていったらいい、関係機関にこれは訴えていってほしいと求めました。このいわゆるふれあい掲示板の掲示物についてちょっと伺いたいんですが、月２回、これを掲出してくださいという形で来ます。","respondent":"武内地域活動課長","answer":"周辺地域の方にそういう催し物だとか、注意を喚起する、そこに公益性があるかどうかということがポイントになるのかなと思います。ですから、個人的なものだとか、営利を目的としているようなものについてはお断りするということになります。","id":"exchange-097"},{"speaker":"渡部委員","kind":"質問・要望","question":"結構荏原のほうにいったりしますと、品川地区で行われている大きな祭りの掲示物とかもなかなか見かけなかったりします。地域の方々にお伝えするべきお知らせは町会にお願いをして、あれこそまさにふれあい掲示板に張るべき、その辺のお考えを聞かせてください。","respondent":"武内地域活動課長","answer":"委員言われるとおりでありまして、今回の３・１１の地震の際も、ふれあい掲示板を効果的に使いまして、地域センターの職員が、緊急性がある場合については張りに行くだとかという対応をさせていただいているところです。","id":"exchange-098"},{"speaker":"浅野委員","kind":"質問","question":"１１０ページから１１１ページにかけて、１２０ページ、防災テルてると防災伝言板についてお伺いします。３・１１、東日本大震災発生後、増えたのか減ったのか、特徴的なことがあれば説明を求めました。","respondent":"荒井広報広聴課長、久保田行財政改革担当課長","answer":"それから、３・１１以降、変わったかどうかというお問い合わせですが、アクセス件数はやや増えていると、４月は特に増えているところです。おそらく緊急情報を充実したことが主な理由ではないかというふうに考えているところです。 区有施設、関連施設を含めまして、ケーブルテレビが視聴できないのは、今委員ご指摘の品川総合福祉センターがあります。今回、区有施設のほうにケーブルテレビを敷設して進めてきたところですけれども…","id":"exchange-099"},{"speaker":"浅野委員","kind":"提案","question":"サーバーダウンということも伺っておりましたので、そしてその後の増ということで、やはり防災情報ということが増えた１つの要因かと思います。このツイッターを情報提供の１つの手段として提案したのは、そういうような観点から、どのように品川区としては分析をされているのか説明を求めました。","respondent":"荒井広報広聴課長","answer":"品川区においても検討を進めてきたところですが、このたびアカウントを取得した段階です。ツイッターにつきましては、大変多くの方に知られている、今後進めていきたいというふうに考えております。","id":"exchange-100"},{"speaker":"浅野委員","kind":"質問","question":"すぐに飽きられてしまいますので、ぜひともそういうような継続的な利用ができるようにしてもらいたいと思います。平成２１年度は１２８本配信をしていますけれども、平成２２年度から、アクセス件数を含めて説明を求めました。","respondent":"荒井広報広聴課長","answer":"ＷＥＢ写真館、ホームページの番組制作、映像館の本数ですが、１５３本です。アクセス件数ですが、今調べてありますので、後ほどお答えいたします。","id":"exchange-101"},{"speaker":"浅野委員","kind":"提案","question":"どうせやるならＹｏｕＴｕｂｅに公式サイトを設置してはどうかと今回提案させてほしいと求めました。実際この平成２２年の２３５台というのは、返却をされた数がどのような形で含まれているのかちょっとお伺いできればと思いますとの意見を述べました。","respondent":"中山防災課長","answer":"実際には防災テルてるとしてうちのほうから貸与しているものが９０、携帯をお使いになっている方が１４５名、個人でお使いになっている方のものも防災テルてるというふうなカウントをしておりますので２３５台ということになります。","id":"exchange-102"},{"speaker":"浅野委員","kind":"質問","question":"こちらのほう、災害が発生した後の質疑の中では、今後見直していかなければならない、つながらなかったということもあります。そちらのほうも危ぶまれるんですが、今後の方向性、簡単に説明を求めました。","respondent":"中山防災課長","answer":"ＰＨＳは、速度は遅くなりますけれども、アンテナの数が無数に立っているということで、確実に通話ができるという保証があります。この辺を検討してまいります。","id":"exchange-103"},{"speaker":"本多委員","kind":"意見","question":"初めに、１０７ページの退職手当なんですが、１５１人、３１億円余、予算計上では１０８人ということなんですけれども、その概要をお知らせください。事務事業評価の１８ページで、一部の給与事務の委託の可能性について検証と書かれているんですけれども…","respondent":"堀越人事課長","answer":"平成２２年度、１５１名ということで、予算の段階では定年退職の数字を挙げているという形で数に差が出てきているという形になってあります。そういった部分の様子を見ながら、どこまでが可能かについては、引き続き検討していきたいというふうに考えているところです。","id":"exchange-104"},{"speaker":"本多委員","kind":"質問","question":"それと、人件費比率なんですが、平成１４年度以降マイナスであった自主財源、平成２２年度はプラスになっております。平成２２年度だけプラスとなってしまっているんですが、実際には算定日が１０月１日だからプラスであって、その解釈の仕方を説明を求めました。","respondent":"堀越人事課長","answer":"これは平成２２年度のところで、平成２３年度見込みといたしましては、財調の部分については下回るというふうな形です。企画財政課長よりご説明申し上げましたけれども、国勢調査等がありましたので、そういった部分によって若干増になったという部分です。","id":"exchange-105"},{"speaker":"本多委員","kind":"質問・要望","question":"ですから、その点について教えていただきたいのと、エレベータは停電でも中からあくんですよね。その研修を区民に伝えられるような、そういった発展があればいいと思うんですが、その辺の見方について説明を求めました。","respondent":"堀越人事課長","answer":"新しくは平成２３年度から大学オープンカレッジということで、大学のほうで実施をする講座のほうに職員の派遣をするという事業を始めております。その他、そういったことも視野に入れながら、委員ご指摘の部分もあわせて検討を進めていきたいというふうに考えております。","id":"exchange-106"},{"speaker":"本多委員","kind":"質問","question":"こういったものはやはり区民のサービス向上や職員のスキルアップにつながるものであれば、やはりそういうものは展開を広めていったほうがいいと思うんですが、その点について考え方を説明を求めました。","respondent":"堀越人事課長","answer":"それから建築士、一級建築士、二級建築士のそういった資格取得をするための学校に通う費用等を助成しているという事業を進めております。例えば仕事を進める上での段取力の向上ですとか、そういった面をあわせて全体的に職員の能力向上を図っていきたいというふうに考えておりま…","id":"exchange-107"},{"speaker":"本多委員","kind":"質問","question":"１１０ページの特別区自治体総合賠償責任保険料、この内容について教えてください。例えば、この庁舎も大震災でガラスがかなり割れたり、いろいろと平成２２年度の保険の使い方、対象がどうだったのか説明を求めました。","respondent":"諸岡総務課長、阿部経理課長","answer":"例えば、区の施設において施設の瑕疵によって利用者の方がけがをされてしまったような場合、その賠償金を補てんする、そういうような保険です。したがいまして… １１２ページの上のほう、庁舎を含めて区有施設の建物等の火災保険料を払っているというものでございまして、これはあくまでも火災保険です。平成２２年度につきましては、実際のところ、区営住宅で火事がございましたので…","id":"exchange-108"},{"speaker":"本多委員","kind":"質問","question":"１件ということでわかりました。１分ありますので、平成２２年度はやはり地震の関係などで事業がとまってしまったりしたものがあったと思うんですが、その状況をお知らせください。","respondent":"阿部経理課長","answer":"平成２２年度予算につきまして、３月の末に主に工事関係ですけれども、３月末に工期を迎えるものが数件ございました。震災の関係で資材等が入らないということで、事故繰越しをいたしまして、平成２３年４月になって竣工して支払っているというものがあります。","id":"exchange-109"},{"speaker":"高橋委員","kind":"質問","question":"１１０ページの結婚サポート事業と、もう１つは、人事全般という感じで。結婚サポート事業なんですが、平成２３年１月２５日ということなんですが、これぐらいそういう支払いに時間がかかってしまうものなのか尋ねました。","respondent":"武内地域活動課長","answer":"年間を通して交流セミナーを３回やっているのと、結婚の相談というものを会社のほうで面会をやっておりますので、そのような手続の完了した時点でのお支払いということですので、そのような期間がかかるというふうに考えています。","id":"exchange-110"},{"speaker":"高橋委員","kind":"質問","question":"今回の議会に提出された監査委員からの報告というのでしょうか、適正な執行を努められたいという、そういう内容があったのでお尋ねしたんです。支払い全般のお話を伺いたいんですが、今だと４カ月ですけれども、どういうようなものか尋ねました。","respondent":"福田会計管理者","answer":"それが終わりますと、支出命令というのが私どもの会計部門に回ってまいります。２日か３日でありますけれども、四日、このくらいは必要だろうというふうに思っております。","id":"exchange-111"},{"speaker":"高橋委員","kind":"質問・要望","question":"それで、私、昨年の一般質問で、年末に区内の中小の業者に対する支払いを短縮して、ぜひ年内にいろいろとお支払いいただきたいというお話をいたしまして、そのときは善処していただけるという答弁をいただいたんですが、昨年末のそういった状況はどういう状況だったか尋ねました。","respondent":"福田会計管理者","answer":"できるだけ仕事納めが終わるまでに着金するように、相手方の口座に振り込まれるように、そういう進行管理をお願いいたしました。分母が非常に膨大な分母ですので、それが数値になってこれこれだというところはあらわれることはなかなか難しいだろうというふうに思っています。","id":"exchange-112"},{"speaker":"高橋委員","kind":"質問・要望","question":"主任主事昇任選考というんでしょうか、試験というのでしょうか、その倍率というのでしょうか。そして、あるいはそういった受験意欲が沸くような職場環境というのでしょうか、そういったこととも関連してご説明ほしいと求めました。","respondent":"堀越人事課長","answer":"主任主事選考ですが、つい１０月２日、主任選考、今年度の分を実施しております。ライフステージの考え方ですが、非常に前向きにといいますか、試験のほうについては受けているというふうに認識しております。","id":"exchange-113"},{"speaker":"高橋委員","kind":"質問","question":"意欲の面で若い方が前向きになってきたということですが、あと、制度の点でも受験者がこのように増えたという理由があると思うんですが、受験年限や、あと、経験者の方が新しく入庁された、そういったこととの関連はいかがか尋ねました。","respondent":"堀越人事課長","answer":"少し前までは２級職、６年以上というものが、今は２級職、４年以上という形になっています。委員ご指摘のように、制度的な面も含めて、このような形で意欲ある形で挑戦をしていただいているというふうに考えております。","id":"exchange-114"},{"speaker":"高橋委員","kind":"質問","question":"三に人」とおっしゃったそうですので、ぜひ人材育成、働きがいのある職場をつくってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"南委員","kind":"質問・要望","question":"１０８ページの人権啓発費について伺いたいと思います。区の認識としてちょっと伺いたいのと、実態についてどういうふうな状況にあるのか、簡単に教えてほしいと求めました。","respondent":"中山人権啓発課長","answer":"むしろ啓発をしてまいりましたので、家庭内の問題ではなく、一方では周知をしてきた結果でもあるのかなというふうに考えているところです。そこにつきましては、ＤＶの実質的な相談ということでお見えになっている方が多くなっております。","id":"exchange-116"},{"speaker":"南委員","kind":"質問・要望","question":"品川区４キロ四方なんですけれども、そういう方向でぜひ取り組んでいただきたいということが１つと、その点について伺いたいと思います。そういうところについての入居については、どんなケースがあったのかをちょっと教えていただきたいのと、そのあたりの見解を伺いたいと思います。","respondent":"中山人権啓発課長","answer":"必要に応じて通訳が必要な場合もあるかと思いますが、そういったものについても、区民相談室と相談しながら対応してまいりたいと考えています。配偶者暴力相談支援センターと連携をとりながら、その方の支援ということで、区の目が行き届くような形で対応しているところです。","id":"exchange-117"},{"speaker":"南委員","kind":"質問・要望","question":"例えばどういうところかというか、そういう部分の運営費の支援だとか、そういうことも含めて品川区の見解を伺いたいと思います。そういう点についての見解も伺いたいと思います。","respondent":"中山人権啓発課長","answer":"それから、加害者支援なんですが、なかなかこういう更正プログラムをつくったとしても乗っては来てくれないと思うんです。被害者の方が迷わずに区に相談ができる、そういう体制の整備というところで私どもは考えているところです。","id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、ぜひ検討を、早急に体制をとっていただけるようにお願いしておきたいと思います。これは大きなものだというふうに思いますので、そういう点でしっかりと取り組んでいただきたいということをお願いして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-119"},{"speaker":"山元委員","kind":"質問・要望","question":"わかりやすくどんな研修をしているのか教えていただきたいというのと、どういう人たちが実際研修を受けているのか、その辺も教えていただきたい。それからもう１つ、これは年間通して５４３回なさっているのか、この辺も教えてほしいと求めました。","respondent":"堀越人事課長","answer":"例えば会議の進め方ですとか、クレーム対応ですとか、そういった研修も入っております。今ご説明いたしました中身、新人から中堅職員、係長、管理職というような形で各職員が受けているというものです。","id":"exchange-120"},{"speaker":"山元委員","kind":"質問・要望","question":"後ほどちょっとその辺も聞きたいと思いますけれども、研修を受けるからにはどなたか講師がいらっしゃるのではないかなと思います。同じような研修をするのか、今年はこういうものをやろうとか、そのような何かテーマ決めをしていらっしゃるのかどうか教えてほしいと求めました。","respondent":"堀越人事課長","answer":"コミュニケーションの関係等については、民間の研修機関を利用できるものにつきましては、そういったところを利用しているというものです。新しく主任主事２年目、係長２年目というような研修を追加しまして…","id":"exchange-121"},{"speaker":"山元委員","kind":"質問・要望","question":"１年かけて研修を受けて、状況はどうなのか、何かそんないいお話が聞ければ教えてほしいと求めました。","respondent":"堀越人事課長","answer":"１年たっていろいろ話を聞いてみると、そういうことを相手に応じて対応できるですとか、職員から直接聞いたこともあります。それから能力、仕事力の部分ですけれども、それをあわせて向上を図っていきたいというふうに考えているところです。","id":"exchange-122"},{"speaker":"山元委員","kind":"質問・要望","question":"１１２ページの地域活動基盤整備補助についてお伺いいたします。実際的には半分ということで３,２００万円になったのかなと思いますけれども、具体的に７件というのは、その辺も教えてほしいと求めました。","respondent":"武内地域活動課長","answer":"平成２２年度につきましては、５件が修繕ということでございまして、２件が新しく建てたです。","id":"exchange-123"},{"speaker":"山元委員","kind":"質問・要望","question":"去年は１３０基で３６０万円ということで、たった１３基しか違わないのに約１３０万円違うというのは、何かあるのでしょうか。その辺を教えてほしいと求めました。","respondent":"武内地域活動課長","answer":"こちらの部分は、新規に立てる部分と修繕というのもありまして、その辺のお金のかかり方が違いますので、このような数字になっているです。","id":"exchange-124"},{"speaker":"石田（慎）委員","kind":"質問","question":"それと１２１ページ、それと１１２ページ、全庁共通プロジェクト推進経費についてお伺いします。にもかかわらず、当初予算より決算額が大幅に下回っているのはなぜか、あわせてお答えください。","respondent":"荒井広報広聴課長","answer":"まちのサイン設置工事の部分ですが、観光のほうで対応いたしまして、そういった原因です。流用につきましては、まちのサインの台帳を作成した関係で事業間の流用をしたものです。","id":"exchange-125"},{"speaker":"石田（慎）委員","kind":"意見","question":"決算額が５６０万円、どうしてもおかしいのではないかと言わざるを得ないんですが、もしあればお知らせくださいとの意見を述べました。","respondent":"荒井広報広聴課長","answer":"予算を途中で流用いたしましたのは、まちのサイン計画を進めていく上で台帳をつくるのが優先すべき事業だろうということで一部流用したものです。その後、結果的に流用しなくてもいいような形になったという、こういう時間の経過のずれです。","id":"exchange-126"},{"speaker":"石田（慎）委員","kind":"質問","question":"次に、１２１ページ、事業所の地域協力経費についてお伺いします。それと、なぜこれほどまでの差が出ているのか、２点お知らせください。","respondent":"高山防災計画担当課長","answer":"まずはこちらのほうの予定している事業なんですが、１つは帰宅困難者徒歩訓練ということで、そちらのほうの事業が１点。そしてもう１点が防災資機材セットということで、こちらのほうを配布する予定だったんですが、予算のほうが未執行となったといった状況です。","id":"exchange-127"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"例えば企業に対して備蓄をしていただきたいとかいう、そういった議論があったり、そういったものもその会議の中で議論がなされているのか。それから、これからの展開をどのように考えているのか、現段階で構いませんのでお知らせください。","respondent":"中山防災課長","answer":"それと、今おっしゃったような備蓄だとか何だとかというお話もしています。２地区しかございませんので、事業所もかなりできておりますので、もう一度話し合いに乗っていただくよう努力してまいりたいと思ってあります。","id":"exchange-128"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"それから、今、２地区しかないということです。危機管理、ぜひこういったときにさらなる働きかけをしてほしいと求めましたが、その辺の考えをお知らせください。","respondent":"中山防災課長","answer":"委員ご指摘のように、三者が合意しないとできないということがあります。ただ、現在あります大崎第一と品川第二は、防災協議会そのものに事業所の方が役員として名を連ねているような状況にあります。","id":"exchange-129"},{"speaker":"石田（慎）委員","kind":"意見","question":"これが今回の決算書にはその欄が見当たらないのですが、なぜなのか。それと、何を実際に想定されていて、この予算時に区有施設の跡地活用等検討経費が計上されていたのか、２点あわせてお答えくださいとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"平成２２年度予算のときには、区有施設跡地活用等検討経費ということで９００万円予算を計上しています。実際に出したのは、その経費が約６０万円ということで小額ですので、事務事業評価報告書印刷等の中に含めて計上して書かせていただいているものです。","id":"exchange-130"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"今回、予算書に載っていて決算書に載っていないと、その事業はなかったのかなというような判断材料になってしまうのかなと思います。そんな中で６０万円、ぜひその部分を決算書にそういった形で載せていただきたいと思うんですが、その辺どのようにお考えか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"表記の仕方として、今回、等の中でくくってしまったんですけれども、今ご指摘いただいたことについては検討させていただきたいと思います。","id":"exchange-131"},{"speaker":"西本委員","kind":"質問・要望","question":"３点目、この策定に至った経緯をまずお聞きしたいのと、優先順位はどのように考えられているのかということを聞きたいと思います。この中でちょっとわからないところがあったので教えていただきたいんですが、デートＤＶをされたときの相談状況の中で、男性もあるんですね。","respondent":"久保田行財政改革担当課長、武内地域活動課長、中山人権啓発課長","answer":"費用対効果の観点から、一定の利用者が見込まれる事務を対象とするということです。この基本的な考え方とはちょっと異にするものですので、現在… 国勢調査の回収率ですけれども、前回の平成１７年の分については７５％という数字が出ておりますので、平成２２年度は若干下がっているです。 携帯電話のメールで常に行動を報告、返信するように求める、こういったものは５分の１の女性がされたことがある。男性のほうは…","id":"exchange-132"},{"speaker":"西本委員","kind":"質問","question":"何か手立てをしなければいけないのかなというふうに思いますが、次回に向けての回収率向上についての方法をお伺いいたします。それを今後どういうふうに対応していくのか、取り組みについてお聞きします。","respondent":"久保田行財政改革担当課長、武内地域活動課長、中山人権啓発課長","answer":"しかしながら区民サービスの向上に向けて取り組んできたところですので、今、日曜開庁でやっていくことはできないというふうに考えているところです。ただ… 区としては、この調査の必要性というものを区民にもうちょっとしっかり周知していくということで回収率を上げていきたいと考えております。 そして施策を推進する課ということで載っておりますので、それぞれの課で推進をしていくということになろうかと思います。ただ、内部の組織としまして…","id":"exchange-133"},{"speaker":"伊藤委員","kind":"確認","question":"それから１０９ページ、自衛隊募集事務費に関連して質問します。それから、それから津波の対策についてどうなっているのでしょうかということを確認したいと思いますので、答弁をお願いいたします。","respondent":"秋山情報システム課長","answer":"３・１１の対応ですけれども、データセンターにつきましては、震度７程度までは対応できるというふうに聞いておりまして。津波に関しましても、海岸よりかなり離れた距離にあるということで、津波に対する影響もないというふうに聞いてあります。","id":"exchange-134"},{"speaker":"伊藤委員","kind":"確認","question":"それが当然だと思うんですね、そのためにやっているわけですから。大切なことは、データ復旧の訓練といったらいいんですか、そういう訓練はなされているのでしょうかということの確認をまたお願いします。","respondent":"秋山情報システム課長","answer":"毎日当然リアルタイムにデータセンターのほうでバックアップをとった上で、日時でテープにとって別の場所に保管するということやっております。その手でやるということになりますけれども、今現在、データの復旧を実際にやったという訓練はしてございません。","id":"exchange-135"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これはできれば東京都に要望して、そのことについての答弁が１つと、当然品川区内にあるわけです。これは品川区にお願いしたいんだけれども、帰宅困難者の支援を考えてみてはいかがでしょうかという質問をしますので、答弁をお願いいたします。","respondent":"高山防災計画担当課長","answer":"この辺につきましては、現在設置されております国と都の協議会の場などを活用しまして、都に設置について今後も働きかけてまいりたいと思います。今後、区民の方々に広く知っていただけるような、そういった形での周知を考えていきたいと考えております。","id":"exchange-136"},{"speaker":"伊藤委員","kind":"意見","question":"もちろんホームページに載っていることはわかるんだけれども、せっかく３・１１を経験して、あれだけの困難が起きた。多くの方々に渡る仕組みができれば、相当帰宅困難者の支援にプラスになると思うんですが、そこでもう少しの答弁をお願いいたしますとの意見を述べました。","respondent":"高山防災計画担当課長","answer":"情報はとる側の責任もありますが、帰宅困難者支援の１つの大きな柱として、情報提供といったものがあります。私のほうもコンビニに張ってあります支援ステーションのマークとか、そんなような実態もありますので、引き続き検討してまいりたいと思います。","id":"exchange-137"},{"speaker":"伊藤委員","kind":"質問","question":"防災行政無線の出口の問題、そこのところをこういう民間のインフラ、それからまもるっち等々に変えていく考え方はいかがでしょうか。答弁をお願いいたします。","respondent":"高山防災計画担当課長","answer":"１つにはケーブルテレビとの連携でありますとか、やはり即日性、そういった技術的な部分については引き続き研究してまいりたいと思います。さまざま商店街のスピーカーの活用などにつきましても、引き続き技術的な部分から検討を進めてまいりたいと考えています。","id":"exchange-138"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、誤解しないでいただきたいのは、そういう今ある品川区の持っているシステムを活用する。安価で比較的効果の高い情報提供システムを検討するべきだと思うんですが、もう一回答弁をお願いいたします。","respondent":"高山防災計画担当課長","answer":"今ある資源を活用せよというお話、ごもっともです。新たな投資をするよりも、引き続き前向きに検討してまいりたいと考えております。","id":"exchange-139"},{"speaker":"武内委員","kind":"質問・要望","question":"この要綱の中に、それについてはどのような形で対応していただけるんですかというご質問だと思うので、ちょっとその辺をもう１回教えてください。５名だけ残念ながら亡くなったと、お話を伺ったんですけれども、このことについてもし何か感想等があったらちょっと教えてほしいと求めました。","respondent":"高山防災計画担当課長","answer":"個人支援プランということで、現在、まずはそこを足がかりにその対象地区を広げてまいりたいというふうに考えております。４点目の相互支援協定につきましては、もろもろございまして、現段階ではここの根底について特に拡大するという方向では考えてございません。","id":"exchange-140"},{"speaker":"武内委員","kind":"質問・要望","question":"９月１０日付でしたか、この辺のところをもう少し教えていただきたいのと、やはり要望の中でほとんどの団体から出たのが。津波の話ですから、さらにその一歩先を、このエッセンスをぜひ取り入れていただきたいというふうに思います。","respondent":"中山防災課長","answer":"６０名の募集の中で１２０名の方が見えたですので、これからその方の活躍によって個人支援プランの策定が進むであろうと期待しています。それから、災害時のまさに高齢者の相談業務等々につきましては、福祉部局と連携してなるべく前向きに行ってまいりたいと思ってあります。","id":"exchange-141"},{"speaker":"須貝委員","kind":"確認","question":"２番目に、家族の安全確保と安否確認。３番目に、近隣住民の救助、またほかの人の救助を行ったらいいというような意識を持っているんですが、ちょっとどうでしょう。","respondent":"諸岡危機管理室長","answer":"ただいまの危機管理関係にかかわるご質問ですけれども、災害発生当時、即時の行動ということで、やはり自分の身の回りから徐々に外に広がっていくという、そういった考え方で対応していくというのが基本です。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"対応もできるかと思いますが、早朝、夜間や休日などの勤務時間外に災害が発生した場合の職員動員についてお聞きしたいと思います。東京都２３区内は、品川区内に居住先がある、その辺についてどのように思われますか。","respondent":"諸岡危機管理室長","answer":"危機管理的事象が発生した場合の緊急対応ですが。それまでの間、初動体制におくれをとることのないように、そういった参集した職員の指揮をとるということで宿直が対応するです。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"３分の１ぐらいは招集できるという話ですが、実際まず身の安全、本庁にたどり着くのはそれからじゃないですか。その辺についてどのようにお考えなんか尋ねました。","respondent":"諸岡危機管理室長","answer":"そういった場合の対応、やはりそれはみずからの身の安全を図るということが大切です。そういうために極力そういったときにも速やかな対応が図れるように。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"ひょっとしたら１年以内に起きるかもしれないということが出ているんですから、やっぱりそういう気持ちがなければいけないんじゃないかと思うんです。そのときにその人たちはだれに頼ればいいんか尋ねました。","respondent":"中山防災課長","answer":"震度５強の地震になりますと、これは全員参集体制になっております。町会の皆さんとか、そういう方がやはり地元の方が中心になって私たちが駆けつけるまで努力していていただきたいということになろうかと思います。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、今、課長のお言葉でしたが、やはり我々は皆さん品川区民の生命、財産、そして健康を守るということがやはり最優先であると思うんです。私は、今度、防災計画を建て直すのだと思うんですが、ぜひその辺についてもしっかり考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-146"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１２０ページの防災対策費、その中の医療救護体制整備についてお聞かせほしいと求めました。そして、ちょっとお聞きしたいんですが、品川区として取り組んでいることがありましたらお聞かせほしいと求めました。","respondent":"高山防災計画担当課長","answer":"こちらのほうは防災計画上は品川区内の１３カ所に拠点的に救護所を設けまして、薬剤師会等々の連携のもと、拠点の部分で医療体制を整備しています。そして、震災を受けての教訓ですが、現在のところは、医師会等との会合を持つべく準備を進めているところです。","id":"exchange-147"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区でもそういう震災が起こったときには、このような医療救護対策会議ということがつくられることになるのでしょうか。それともう１つは、品川区としてつくられているのかどうか、このことについても説明を求めました。","respondent":"高山防災計画担当課長","answer":"１点目のご質問ですが、まずは主体的に災害時の対応について災害対策本部にかかわっていただける、そういった体制です。２点目の要援護者につきましては、現在までのところは医療関係のマニュアルといったものの整備には至っておりません。","id":"exchange-148"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"課長のほうから、救護所というのは１３カ所つくられるということなんですが、８人で１チームを１３チームつくるということで考えていいのでしょうか。そしてもう１つ、救護所に医療品などの備蓄というのはどうなっているのかということについてもお聞かせほしいと求めました。","respondent":"高山防災計画担当課長","answer":"しかしながら、こういったもので体制が十分に組めないということであれば、都の医療救護班に支援を要請するといった、そういった考えです。３点目が、ランニングストックということで…","id":"exchange-149"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと先ほどの災害時の医療救護活動計画、それもぜひつくっていただきたいと思うんですけれども、そこの答弁もお願いしたいと思います。発災直後ということなので、これを実際に具体化させるというのはかなり困難になると思うんですけれども、そこのところはいかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"１点目のマニュアルの件につきましては、歯科医師会等と連携をとってマニュアルについてはつくってまいりたいと考えております。２点目については、よりよいものをつくっていくと、そういった考えでおります。","id":"exchange-150"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところを事前に対策をとったことによって救われるものであれば、ぜひ救えるようなことで取り組みをよろしくお願いしたいと思います。公共性がとても高いというふうにいえると思うんですけれども、医療機関の公共性ということについては、区の見解としてはいかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"医療機関の公共性ですが、確かに他のものと比べて公共性は高いと、そのように認識しております。","id":"exchange-151"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"診療所で３１％、歯科で３５％が被災したという、この助成が今どうなっているかについてお聞かせほしいと求めました。","respondent":"工藤生活衛生課長","answer":"医療機関に関しましては、大病院であれば耐震化というのはなされておるところです。","id":"exchange-152"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"耐震診断とか、耐震補強工事への助成制度をぜひともつくっていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"基本的には、委員おっしゃられるように、医療機関については公益性が高いという状況です。その中で、それぞれの事業者が平成２７年を目標に耐震化を進めなければいけないという役割の義務がありますので、このように考えてあります。","id":"exchange-153"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それは本当に社会的な問題になっていますので、そういう中で耐震診断、耐震補強工事というのは、なかなか厳しいものがあると思うんですね。そういう点では、どこまで耐震診断、補強工事が進んでいるかというのは区として把握されているところはありますか尋ねました。","respondent":"品川防災整備担当課長","answer":"病院関係につきましては、特定建築物の部分に当たりますので、この部分につきましては、以前より耐震診断のチェックはやっております。今後、ここの部分に関しても、耐震診断、どれだけやっているかというところも少し検討していきたいというふうに考えております。","id":"exchange-154"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ病院だけでなくて診療所も含めて耐震診断、補強工事がどこまで進んでいるのか、それをぜひとも調査をしてほしいと求めました。それで、公共性が高い医療機関に対しての耐震診断、補強工事への助成の検討をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-155"},{"speaker":"井上委員","kind":"質問・要望","question":"１点、１２２ページの午前中に議論がありました行政サービスコーナーについて、ここで区民の方たちも再三要望が出ている。やっぱり品川区の上大崎地域の本気度というのが問われるかと思うんですけれども、そのことについてご意見を伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"そうした中で行政サービスコーナーの設置とか、今、努力しています。","id":"exchange-156"},{"speaker":"井上委員","kind":"質問・要望","question":"再開発もそんなにすぐにできるものではないので、そういった対応もぜひお願いしたいと思います。群馬県とか、受け入れをしたときに、この日光林間学園周辺の放射能測定というのは行われているのか尋ねました。","respondent":"高山防災計画担当課長","answer":"日光周辺の放射能の濃度ということですが、こちらのほうの数値的なものはこちらでは把握しておりません。","id":"exchange-157"},{"speaker":"井上委員","kind":"質問","question":"もう違うところに行かれたんですけれども、そういった対応は６月から学校を測定して園庭とか、日光のこちらのほうは今はどういう状況なのでしょうか。それとあと、保護者への対応をどうされたのか伺います。","respondent":"和氣学務課長","answer":"日光光林荘につきましては、日光市のほうで日光全体の計測をしていて、日光自体が安全宣言をしていますので、私どもは安全だということで利用しています。","id":"exchange-158"},{"speaker":"井上委員","kind":"質問","question":"日光のほうで安全宣言をされているということで、データはきちんとこちらで把握をされているのか尋ねました。","respondent":"和氣学務課長","answer":"日光市のほうに確認をしてございまして、その段階で数は押さえましたが、今手元には持ってございません。ただし、日光市が安全宣言をしたですので、私どもはそれを信用するしかないということです。","id":"exchange-159"},{"speaker":"井上委員","kind":"質問","question":"次は、区民活動サイトについてお伺いいたします。区民活動サイトの開設は、開設後１年が経過いたしまして、このサイトに対する区の評価と区民の評価をお伺いいたします。","respondent":"今井協働・国際担当課長","answer":"４７０団体ぐらいの団体が登録されていまして、検索をできるというところで、目的に沿った使い方がされているというふうに認識しております。区民の方からは、なかなか入力方法が難しいということで、操作研修会などを運営委員会に委託して実施しています。","id":"exchange-160"},{"speaker":"井上委員","kind":"質問","question":"イベント情報が区のイベントの再掲も多いということで、区の第二ホームページみたいになっているんじゃないかなという感覚があるんです。そういったものを、３回行かないと町会ホームページに行かないとか、そういう整理をというようなところでの問題意識はありますか尋ねました。","respondent":"今井協働・国際担当課長","answer":"そして、町会のホームページへの３回のクリックですが、町会のホームページでは、区のホームページの地域のほうからも情報が検索することができます。１０ぐらいのカテゴリーで選んだものなので、今のご意見を参考にしながら…","id":"exchange-161"},{"speaker":"井上委員","kind":"提案","question":"２００５年に再三審議会等の一覧を掲載して、会議日程の順次掲載をしていただきたいというふうに提案をしてきたものなんですけれども、今現在。そして、その中で開催情報を公開しているのは幾つあるのかお伺いいたしますとの意見を述べました。","respondent":"諸岡総務課長","answer":"区にあります審議会、付属機関に準ずるもの等も含めまして、２６ということで把握していますが、その中で公開しておりますのは１０件です。","id":"exchange-162"},{"speaker":"井上委員","kind":"確認","question":"２６ある中で原則公開と位置づけられているのが１０件ということなのか、そこのところの確認と、今現在、ホームページで開催日を情報公開している審議会が幾つあるのか、もう１回整理してお願いします。","respondent":"諸岡総務課長、荒井広報広聴課長","answer":"今のお話のとおり、２６把握しております。その中で公開しておりますのが１０件です。 最後にお尋ねの現在何件がホームページで公開しているかということについてですが、現在は４件、ホームページでアップされてあります。","id":"exchange-163"},{"speaker":"井上委員","kind":"質問","question":"正確な情報開示だというふうに思っていますので、公開と言いながら開催日を公開していないものは決して公開ではないというふうに認識しています。２０１０年一般質問で私が取り上げた際に、どのような検討をされて、どういった結果になっているのか伺います。","respondent":"荒井広報広聴課長","answer":"３カ月ごとにまとめて審議会の日程を公開しています。ただし、途中で３カ月を切った段階で新たに公開する審議会等が追加される場合につきましては、個別に対応させていただいているところです。","id":"exchange-164"},{"speaker":"井上委員","kind":"質問","question":"３カ月ごとではなくて、大変それに関心を持っている人たちには有効なツールになると思うんですけれども、そういうことは再三お伝えしています。あるいはこれは大変失礼な言い方かもしれませんけれども、企画部や総務部にそのリーダーシップがないのか、理由をお伺いいたします。","respondent":"荒井広報広聴課長","answer":"今申し上げましたホームページの公開方法につきましては、委員ご指摘のようなことも含めまして、今後検討を進めていきたいと思います。審議会等の日程の公開につきましては、委員がご提案いただきました方法も含めて検討を進めてまいりたいと思います。","id":"exchange-165"},{"speaker":"井上委員","kind":"質問","question":"次は、シルバー大学のことについてお伺いいたします。２０１０年の事業費は幾らになるのか説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"事務事業評価につきましては、人件費が入っているです。","id":"exchange-166"},{"speaker":"井上委員","kind":"質問","question":"事業費、事務事業評価で２００９年度は３,９８０万円という表記になっています。私が知りたいのは、人件費を含めた事業費で比較をしていきたいので、２０１０年の事業費は幾らになりますかという質問をいたしました。","respondent":"安藤文化スポーツ振興課長","answer":"人件費を含めての計算ですので、ほぼ横ばいで同じと思います。","id":"exchange-167"},{"speaker":"井上委員","kind":"質問","question":"シルバー大学と合わせると約２億円弱というようなことになるかと思うんですけれども、そういった施策が必要だというふうに思うんです。いきがいというのは生涯を通じたものだし、そういう意味で大きく構築をし直すということも必要だというふうに思うんですが、見解を伺います。","respondent":"久保田行財政改革担当課長","answer":"さらに、各所管課にまたがるものについても整理をされたほうがいいのではないかというような意見もいただいております。こうした意見をもとに、平成２４年度の予算編成に向けて参考にしながら進めていきたいというふうに考えてありますので。","id":"exchange-168"},{"speaker":"井上委員","kind":"質問・要望","question":"高齢者も文化的なことも健康的なこともつながっている生涯を通じているというような発想も必要かと思いますので、検討ほしいと求めました。平成２２年度に事務事業評価報告書を出されて、あと、行政評価委員会のようなことを来年度どのように考えているのかお伺いいたします。","respondent":"久保田行財政改革担当課長","answer":"平成２２年度は全事務事業を対象とした評価を行ったところです。平成２３年度は区民参加による事務事業評価を行ったですので、そこの辺のサイクルについては現在検討しています。","id":"exchange-169"},{"speaker":"若林委員","kind":"質問・要望","question":"１２０ページの防災行政無線管理になるのでしょうか、１１１ページの契約事務関係、それから時間があったら１２４ページの監査委員です。契約事務関係では、当該委託契約の見直しが行われていない事例が見受けられると、これについて具体的な内容をお示ししてほしいと求めました。","respondent":"高山防災計画担当課長、久保田行財政改革担当課長、武藤都市整備下水道課長","answer":"１点目のお尋ね、情報収集について私のほうからお答えします。こちらのほうの決算書のほうにも載ってあります情報収集用高所カメラなども利用しまして… ３回継続的に会える場や、実施方法として、やはり継続的に出会いの場を提供していただくということは。ただ… 監査のほうでは、その工事が変更に伴って、その補助の委託のほうも見直すべきではないかということでご指摘を受けました。その件につきまして検討したとこ…","id":"exchange-170"},{"speaker":"若林委員","kind":"質問・要望","question":"それからもう１つ、この大きな２つのお仕事を同時にというんですか、情報が先だという観点もあるかと思います。やはり近隣との人とのきずなが大変に求められているということが１つありますし、やはり３・１１以後、いわゆる年齢差１０歳はもう普通ですね。","respondent":"鷹倉監査委員事務局長","answer":"工事監査は、毎年建築関係が１件、土木関係が１件で、後期の区長報告の中に入ってあります。ただいま申し上げたとおり、後期の区長報告の中に意見として書かせていただいていますし、それについての区長報告で、また結果報告をいただくです。","id":"exchange-171"},{"speaker":"須藤委員","kind":"質問・要望","question":"１１４ページの歩行喫煙防止推進経費、同じく１１４ページの文化スポーツ振興費、１１６ページ、区民施設費についてお尋ねいたします。次年度はどういうふうに、どういうふうに考えていくのかということをお知らせいただきたいのと同時に、いかがか尋ねました。","respondent":"川崎生活安全担当課長","answer":"来年度もこの予算がつく見込みでありますので、それの決定を受けてではありますが、この事業を継続したいというふうに考えております。２点目の喫煙者に対する場所の配慮ですが、今、区内で１０カ所の区による灰皿の設置を行っております。","id":"exchange-172"},{"speaker":"須藤委員","kind":"提案","question":"１１４ページの文化スポーツ振興費についてなんですけれども、文化芸術・スポーツ振興によるまちづくりというような条例提案をさせてもらいました。そのあたりについても文化振興事業団としっかり連携をとって、今言ったまちづくりの観点から配慮してもらいたいと思うんですが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"スポーツについても、地域スポーツをスポーツクラブ型で地域でやっております。そんな中で、スポーツ、芸術を通してまちづくりをしていくというものを第一に考えて、芸術、スポーツも行っておるところです。","id":"exchange-173"},{"speaker":"須藤委員","kind":"意見","question":"ともすれば、文化なり、芸術なり、そっちのほうに何かやらなければという話ばかりになってきてしまうので、基本的にはまちづくりでコミュニティをしっかりつくっていこうというような思いがあるんですが、もう一度よろしくどうぞお願いしますとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"失礼いたしました。公益法人になりました文化振興事業団、そことも連携をいたしまして、今、盛んに芸術活動を通してまちづくりをやっております。","id":"exchange-174"},{"speaker":"須藤委員","kind":"質問・要望","question":"あそこはちょうど２６号線で広い通りもあるし、あの建物自体が昭和４１年ぐらいに建ったと思うので、なかなか難しいと思う。そうした場合に、ほかに活用できる方法というものをしっかり行政として考えなければいけないだろうというふうに思うんですが、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"区有施設の有効活用からこういった点をいろいろ考えてみますと、平塚橋会館については、幾つかの課題があるというふうに認識しています。これらの点を総合的に考えまして、今後…","id":"exchange-175"},{"speaker":"須藤委員","kind":"提案","question":"今、品川区の高齢化の中で、特別養護老人ホームというのが非常に我々のところでも必要だよというようなことを自民党としても提案しています。２,７４０平方メートルの広さがあって、あのあたりしっかりと使うような仕組みをつくってきたら、そのあたりについてはいかがお考えか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"敷地面積が有効に使われていないということもありますし、また、周辺全体を考えていく必要があるかなというふうに思っております。今、平塚橋会館について、今ご提案のありました特別養護老人ホームの整備も含めて前向きに検討する必要があるというふうに考えているところです。","id":"exchange-176"},{"speaker":"須藤委員","kind":"質問・要望","question":"どういう方向性をしっかりつくるかということも必要だろうと思うし、荏原第二地域センターは、やはり稼働率がそんなによくない。我々が区民に対しての福祉というものをしっかり考えていただきたい、そう思っているんですが、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"これからの区財政を取り巻く環境が厳しくなるということを考えますと、本当に大事な課題である、重要な課題であると認識しております。平成２３年度の緊急課題の１つでもありますので、引き続き、あり方全体について検討をしていきたいというふうに考えております。","id":"exchange-177"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/794205?Template=document&Id=1342#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":109639,"voices":415}},{"id":"h23-20111005-4","meetingId":"h23-c-settlement","date":"2011年10月5日","dateIso":"2011-10-05","committee":"決算特別委員会","time":"午前１０時００分～午後５時３９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を161件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山内委員","kind":"質問","question":"最初に成果報告書の１３４ページのひとり親家庭支援事業のパソコン教室事業についてを伺います。それから平成２３年度はお話によりますと、やはりどうしてもこれが、そのあたりの考えをちょっとお聞かせをください。","respondent":"安井子育て支援課長","answer":"こちらについては、その必要性を勘案しながら、前向きに検討していきたいなというふうに考えております。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"次に１２９ページ、高齢福祉費の中の介護予防事業費についてお伺いをします。６５歳以上の方々が何名おられて何％なのか、それからあと７５歳以上の後期高齢者の要介護の方、そこの数字のあたりを説明を求めました。","respondent":"原高齢者福祉課長","answer":"同じくこの時期に６５歳以上の方で認定を受けている方は１万９５６人ということで、割合でいきますと１５.４％です。その中で認定の割合ですけれども、前期の方が４％、それから後期の方が２８％という割合になっているところです。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問・要望","question":"６５歳以上の方、要は前期が４％という考え方でいいんですかね。この垣根はもちろんいろいろな理学療法士とか運動指導員ですか、そのあたりはどのようにされているのか、説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"マシンを使った場合についてはどうしても、卒後については健康センターですとかスポーツジムに行かないとできないというようなこともあります。このような現状です。","id":"exchange-003"},{"speaker":"山内委員","kind":"提案","question":"ちょっとこれは提案というか、委員長にお願いしたいのですが、よろしいですか。そういったことを、その辺を介護予防事業の一環として統合できるものなのかどうなのかといったことを答弁をお願いいたしますとの意見を述べました。","respondent":"間部高齢者いきがい課長","answer":"私ども、それぞれ当然事業目的を定めまして実施をしていますが、言ってみればリスクを回避するというような考えで行っているものです。よりよくなるということで、リスク回避と、現状より上を向いて頑張っていくという違いがあるものだと認識をしております。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問・要望","question":"努力をしているといったことも伺いましたので、そういったことをあえて私は求めているので、今後につなげていただければなと思います。それから、これは平成２２年度決算が４５２万円と若干少なくなっている、その内容を教えてほしいと求めました。","respondent":"間部高齢者いきがい課長","answer":"この参加者の伸びも含めまして、大変素晴らしい事業じゃないかと認識をしています。今後につきましても、やはり適地があれば、さらに地域的な面もありますけれども、拡大も検討の視野に入れているです。","id":"exchange-005"},{"speaker":"若林委員","kind":"質問・要望","question":"１３７ページの特別保育事業になるのでしょうか、もう一つは、２２５ページのいきいき脳の健康教室ということで、２点お伺いいたします。もう一点、この私立幼稚園でのこの事業の概要についても、合わせて教えてほしいと求めました。","respondent":"吉岡保育課長","answer":"入っている場所は、１３７ページの基本保育事業の中に、ちょっと項目としては出していない形になってあります。集団保育の部分と、それから一人ひとりのお子さんに対するきめの細かい保育の支援の部分を合わせて行っているという事業です。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"審査をして認定をするわけですけれども、平成２２年度において５０名ほど認定されていない、そういうお子様たちがいらっしゃいます。この実態を教えていただきたいのと、これについてもお聞かせ願いたいと思います。","respondent":"吉岡保育課長","answer":"こちらにつきましては、いずれにしても特別な支援を要するお子さんが保育園、幼稚園で増加の傾向にあるのではないかという認識は持ってあります。それぞれの園の設置者ともよく話をしまして、それぞれどういう対応をとっていけるのか…","id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"ここら辺、現在のこういった全庁的な特別な支援のネットワークについて、取り組みは現状どのようになっているのかをお聞きしたいと思います。山中いきいき広場とか行ってまいりましたけれども、大変評価をした事業ですので、拡大をしていただきたいという思いで評価をお聞きしたいと思います。","respondent":"永尾障害者福祉課長、間部高齢者いきがい課長","answer":"公立の保育園についての巡回相談についてご説明いたしましたが、心理士が保育園、幼稚園のほうに出向いて助言をしているです。今も療育支援ネットワークというものを庁内で開催しておりまして… こちらについては平成１６年から開始して、一定の成果を上げてきた認知症予防の事業だと認識をしております。ただ、最近では欠員が見られる、またはリピーターが多くなっているということがありまして…","id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひ今度は施設のほうへの拡大についても、その中でご検討をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"向委員","kind":"質問","question":"そして同じく成果報告書１３４ページ、４番目に、時間があれば成年後見人制度利用支援事業の障害者への支援決算額についてお尋ねしたいと思います。女性福祉基金の貸し付けについてなんですが、これは区独自のものだと思うんですけれども、保証人は必要なのか尋ねました。","respondent":"安井子育て支援課長","answer":"事業開始資金から就学支度資金まで１０種類ほどありますけれども、それぞれによって償還期間というのは異なってあります。なるべく都内近県の方という、お住まいの方の兄弟、姉妹の方であるとか親戚等の方をお願いしています。","id":"exchange-010"},{"speaker":"向委員","kind":"質問","question":"１回就職したけれども、どうしてももうちょっと収入を上げたいとかステップアップしたいとか、お考えはいかがでしょうか。ありますか尋ねました。","respondent":"安井子育て支援課長","answer":"ハローワーク等の関係で、そちらのほうの給付金であるとか、そういったものを利用されるという方が多いのが現状です。そういう意味では、なかなかそこら辺のところよりも、そういった就職のほうが重視されていると考えています。","id":"exchange-011"},{"speaker":"向委員","kind":"質問・要望","question":"予算額９０２万円ほどが、今年の決算額６７０万円ほどということなんですけれども、このあたりの差というのは一体どういう理由があるんでしょうか。決算だと２６７万円ほどになっていて、専門相談員の人数とか、どのような内訳になっているのか尋ねました。","respondent":"安井子育て支援課長","answer":"平成２３年度から別の方が採用されているんですけれども、そこら辺で日数が減りましたので執行額が減ったというようなところがあります。はシステムの運用経費や何かが、つくっていく中で減ったりした、そういうところで減額になっているというところもあります。","id":"exchange-012"},{"speaker":"向委員","kind":"質問","question":"もう一つ、決算額がこちらで１３４ページを見ますと５５万円ほどになっているんですね。本当に協議会の運営の充実が図られているのかなとか少し不安に思ったりするのですが、そのあたりの理由はいかがか尋ねました。","respondent":"安井子育て支援課長","answer":"あんしんねっと協議会の委員に対する報酬というのは基本的にありませんので、事務的に何かやらなかったとか、そういうことではございません。","id":"exchange-013"},{"speaker":"向委員","kind":"質問・要望","question":"全国的に里親の専門職員を７００施設ですか、本当に一生懸命、今後も品川区としてもこの協議会の運営充実を図ってほしいと求めました。続きまして１３４ページ、これは、この中にどのくらいの決算額ということで入っていますか尋ねました。","respondent":"安井子育て支援課長","answer":"こちらのほうはひとり親家庭支援事業の相談事業の中に入っております。件数的に申しますと２件ほどの派遣ということで、すごくわずかな金額しか出ていないという形です。","id":"exchange-014"},{"speaker":"向委員","kind":"質問","question":"こちらもちょっと事務事業概要を拝見しまして、昨年度、平成２１年度は１１件、今年は今２件ということで伺ったんですけれども、１１件から２件ということでガクッと減っているのではないかなという印象も受けたんですが、そのあたりはどうお考えか尋ねました。","respondent":"安井子育て支援課長","answer":"そこら辺のところで派遣ができるかというようなところも検討させていただいた上で、あくまで緊急性の問題で判断しておりますので、それが平成２２年度については実態だったのかなというふうに把握しております。","id":"exchange-015"},{"speaker":"向委員","kind":"意見","question":"では最後になりますが、成果報告書１２５ページ、成年後見制度利用支援事業のところで、障害者に対する決算額３万８,９００円ということで、私、平成２２年度の予算を見ますと６０万円ほどになっているのですが…","respondent":"永尾障害者福祉課長","answer":"障害者の成年後見制度ですけれども、件数が当初予定されたよりも伸び悩んでいるという状況です。ただし法律の改正が来年４月を見込んでおりまして、今後は増えるのではないかと予想しております。","id":"exchange-016"},{"speaker":"向委員","kind":"意見","question":"品川成年後見センターの活動実績に任意後見コース契約が２０件とあるのですが、そういったニーズが今後出てくると思います。区のほうからもぜひともどんどん啓発と周知をしていっていただければなと思いますので、どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"先日、品川区視覚障害者福祉協会と懇談がありまして、要望を伺いました。どれもとても切実で、ぜひ品川区に要望を受けとめ、反映してほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"品川区の障害者の雇用人数ですが、平成２２年度、平成２３年度ともに４８名になっております。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"人数は同じ４８名ということですけれども、その中身についてお話を伺いました。品川区はこの視覚障害者にとっての図書館の役割、位置づけについてどのようにお考えなのか、伺いたいと思います。","respondent":"堀越人事課長、中元品川図書館長","answer":"障害者の雇用に関するお尋ねですが、障害者の方の自立とそれから社会参加を進める上で、この充実というのは重要な課題であると認識しています。そういう考え方のもとから品川区としても採用を行っているものでございまして、平成２２年… 品川区として図書館での障害者のバリアフリーについてどう考えているかということなんですけれども、利用者の方がご不便を感じないようにさまざまな工夫と努力でサービスレベルを維持していくことが図書館の使命であると考えております。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"この点からも図書館での視覚障害者の採用、雇用をしっかりと進めていただきたいと思うんですけれども、いかがでしょうか。これらが途絶えることがないよう継続し、充実するよう力を尽くすべきだと思うんですけれども、この点についてもいかがか尋ねました。","respondent":"中元品川図書館長","answer":"図書館で視覚障害者の方を雇用したほうがきめ細かい対応ができるというご趣旨かと思います。きちんとその辺のノウハウについては引き継がせていただいて、今後もそれを維持継続していきたいと思ってあります。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"引き続き生活支援について伺いたいんですけれども、こういう要望を伺いました。印がついておりますけれども、同じような工夫をすることで視覚障害者にもわかるようにしていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"永尾障害者福祉課長","answer":"そういう方法は考えられるのですが、今、点字を読める方が非常に少なくなっておりまして数％という状態です。障害者福祉課のほうでお送りする場合につきましては、何か対策がないかということをまず考えていきたいというふうに思ってあります。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"エスコートゾーンが大事だと思うんですけれども、伺いたいのは、なぜこれが必要なのか。品川区はこの点字や音響信号、エスコートゾーンの整備について、どういう方針をお持ちなのか、併せて伺いたいと思います。","respondent":"永尾障害者福祉課長、山崎マスタープラン担当課長","answer":"封筒の件につきましては、まず障害者福祉課で出す封筒についての工夫をして、それをモデルに将来的に考えていきたいというふうに思っております。 エスコートゾーンにつきましてですけれども、この設置の権限につきましては、交通管理者の、例えば警視庁になります。視覚障害者の道路横断を支援する有効な一つの手法だということで認識しておりまして…","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"エスコートゾーンなどを要望に沿って進めていきたいとのお話ですけれども、この視覚障害がある方と一緒に大井町駅前を一緒に歩いて説明を受けました。横断歩道、これらもまずは整備をしっかりと進めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"警察のほうでは、いろいろと警察にも要望がございまして、設置の優先度等々を検討しているです。それから社会福祉協議会等々の福祉施設、こうした対応に向け、警視庁のほうで前向きに検討しているというふうに伺っております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ要望を受けとめて早く設置できるようお願いしたいと思います。要望も挙げられていると思いますので、ぜひ当事者の意見を伺って、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"ただいまの点字ブロックの件につきましては、既にご意見をいただいておりまして、関係機関と調整の上、設置する方向で進めております。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は、成果報告書の１３４ページから児童福祉費、これについて何点かお伺いしたいと思います。改めてこの児童相談事業というのはどういうもので、その専門相談員という方はどういう方なのか、ご説明をお願いしたいと思います。","respondent":"安井子育て支援課長","answer":"専門相談員は１名ということで、区の職員のほうとしても虐待対応等について特に力を入れるということで、一緒に仕事をさせていただいているです。ただ、やはり今、虐待の問題は特に対応が急務ということで、こちらのほうを特に力を入れているというところで進めているところです。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"次の１３５ページですが、これで約１,０９４万円の予算執行についてここに挙げられているわけですが、実績というのはあるんでしょうか。これについてちょっとご説明ほしいと求めました。","respondent":"吉岡保育課長","answer":"時間でのお預かり、それからあと、いろいろな相談事業等々を実施をしています。それから時間でお預かりする一時保育については、延べ時間数で平成２２年度が７,６８５時間という実績です。","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"これが１３回で約３０万円、それとあと保育園での子育て相談事業が２２３件で１３０万円、さらに地域子育てセンターでも子育て相談が４９件。これはすべてばらばらに行われているのか、それに基づいて一定程度の標準化というのは図っているのか、ちょっとそれについてお聞きしたいと思います。","respondent":"安井子育て支援課長","answer":"こちらのほうでは、次世代育成支援対策推進行動計画というのを品川区のほうで定めております。見直しを進めたりしながら、実際にどのように子育てのスキルを上げていくかということで、さまざまなアプローチを展開しながら事業を進めているです。","id":"exchange-027"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは平成４年に厚生労働省の子育て支援の次世代育成支援事業の一つとして定義されています。品川区のほうでも検討をしていただけたらいいのではないかというようなことを考えているんですが、それに関してのご見解を伺いたいと思います。","respondent":"矢野品川保健センター所長","answer":"品川区では、子育ての育児不安を除いたり、あとは病気などの障害を予防して早期に発見するように連携して事業を行っております。妊娠届出時にお母さんのアンケートなどを実施しておりまして、お困りのこととか、必要であれば医療機関にもつないでいるという状況です。","id":"exchange-028"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"２カ所しかないので、あとは東芝病院も含めて３カ所でお産が集約されているわけですけれども、ぜひ前向きにご検討してほしいと求めました。これは要望ということにします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"鶴委員","kind":"質問","question":"初めに１２６ページの地域福祉計画改定経費についてお尋ねいたします。改正障害者基本法が去る８月５日に公布され、既に着手されているのでしょうか、説明を求めました。","respondent":"原高齢者福祉課長","answer":"地域福祉計画のお尋ねです。昨年平成２２年に検討をしまして、その改定ということで、平成２３年から平成３２年に向けた１０年計画ということで策定したところです。","id":"exchange-030"},{"speaker":"鶴委員","kind":"質問","question":"ということは、未着手ということでよろしいか尋ねました。","respondent":"永尾障害者福祉課長","answer":"地域福祉計画等につきましては今回改正をしたところでございまして、その基本法に応じて改正ということは現在は考えておりません。ただ、基本法の理念というのはきちんと守って施策の運営をしていきたいというふうに考えております。","id":"exchange-031"},{"speaker":"鶴委員","kind":"質問","question":"次に福祉人材確保・定着事業についてお尋ねいたします。それぞれ１年、２年、３年間と各事業によって実施年数は違いますが、改めてそれぞれの現在までの成果を説明を求めました。","respondent":"原高齢者福祉課長","answer":"そういった意味では看護職が基本的には対応するところですけれども、そういったところに向けての取り組みもこの中で実施をしたところです。こちらも同様に看護職が対応する間の部分ということで、新規の雇用ということで４９名の新規採用をしたところです。","id":"exchange-032"},{"speaker":"鶴委員","kind":"質問","question":"詳細に成果を報告いただきましてありがとうあります。これまで品川区独自でも行ってきた福祉の人材確保事業、こうしたものを補完するに足る大きな成果があった、こういう理解でよろしいか尋ねました。","respondent":"原高齢者福祉課長","answer":"今までもさまざまな形で、福祉カレッジ等を通じて、こういったスキルアップワークとしても社会福祉協議会を応援して実施をしてきたところです。これを追加する形で、さらに効果があったというふうに理解しています。","id":"exchange-033"},{"speaker":"鶴委員","kind":"確認","question":"この事業は先ほどもご説明いただきました国の緊急雇用創出臨時特例交付金ということで、平成２１年度から平成２３年度という形でのことになりますけれども、確認ですが、これは平成２３年度までの交付金という理解でよろしいか尋ねました。","respondent":"原高齢者福祉課長","answer":"今のところ平成２３年度ということで、重点的なもので継続ができるものはというところも情報としては入ってありますけれども、これがそれに該当するかどうかというところは、現段階では未定となっています。","id":"exchange-034"},{"speaker":"鶴委員","kind":"意見","question":"そうすると全般としては、平成２４年度以降は今までと同じような形ではなくなるという形になるかと思います。もしくはまだ不足している施設等があるのか、把握をしていれば、その詳細を説明を求めました。","respondent":"原高齢者福祉課長","answer":"そういった意味では、当然従前からその基準はすべてクリアをしているという状況です。さらにそこを補完するというところが今回の事業でございましたので、今どちらかが不足しているというところではございません。","id":"exchange-035"},{"speaker":"鶴委員","kind":"質問","question":"やはりこうした事業というのはますますニーズも高まるというふうに考えます。引き続き、それに限ってでも区独自でこうした事業を継続ないし創設するなどの何らかの対応策が必要だと考えますが、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"こういった形で人材確保、それからスキルアップというところは非常に重要だというふうに認識をしております。そういった意味では、現在のスキームの中で、我々ができる範囲の中で十分努力をしてまいりたいというふうに考えているところです。","id":"exchange-036"},{"speaker":"鶴委員","kind":"質問","question":"もしなければ、そのような活用も視野に入れてみてはと思いますが、いかがでしょうか。おおむね５５歳からが対象となっているサポしながわで、福祉施設や福祉事業の求職および就職決定者はどのぐらいあるか、わかる範囲で説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"平成２３年度につきましては５３件の求人です。そのうち大体半数ぐらいが、ほかの統計を見ましても就職が決定していますので、今の求人の半数ぐらいが就職したのではないかと推測しています。","id":"exchange-037"},{"speaker":"鶴委員","kind":"提案","question":"その上で、これまでの品川区の人材確保事業を横断的に活用するなど、品川区独自の仮称福祉人材確保制度を創設してみてはいかがでしょうか。ご所見をお伺いしますとの意見を述べました。","respondent":"福島ものづくり・経営支援課長","answer":"このように社会を支える側に立っていこうというのがシルバー人材センターですし、またサポしながわもそういった観点から無料職業紹介をしています。ほかの人材確保、総合的な労働行政をどうしていくのか、そういったことも含めまして今後検討していきたいとは思ってあります。","id":"exchange-038"},{"speaker":"沢田委員","kind":"質問","question":"それから１３７、８ページの認定こども園事業、幼保一体施設運営費についてお伺いいたします。初めに１２６ページの福祉団体に対する助成金についてなんですが、先日、多くの障害者団体の皆様方からお話をお伺いいたしました。","respondent":"永尾障害者福祉課長","answer":"その後、団体生活ができないという方について二次避難所のほうに振り分けるというような形のことが今、計画の中では定められております。３月１１日の大震災を受けまして、その辺のお話、この二次避難所の整備について検討していきたいというふうに考えております。","id":"exchange-039"},{"speaker":"沢田委員","kind":"質問・要望","question":"その３月１１日の大震災の後、それ以外のやはり障害がある、ぜひともそういった施策も今後とも進めていってほしいと求めました。認可保育所も６園ということで、計９園が開設されるという、これは区による誘致活動の成果だと考えてよろしいのか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"平成２２年度より待機児童対策を緊急課題として取り組んでおりまして、その中で、インセンティブになるような補助制度もつくってきております。そういった効果によるものと考えております。","id":"exchange-040"},{"speaker":"沢田委員","kind":"質問・要望","question":"昨年度は２歳児が減少したということでしたけれども、わからないことかと思うんですけれども、今後の待機児童の推移というのは区としてはどのように見られているのかということをお伺いさせてほしいと求めました。","respondent":"伊崎待機児童対策担当課長","answer":"もちろん待機児童を一人でも減らすということを命題といたしまして、今取り組みを進めているところです。当然、認可保育園を基本といたしました対応をとってきておりますので、今後もそれを継続してまいります。","id":"exchange-041"},{"speaker":"沢田委員","kind":"質問・要望","question":"今後そういった施設のこども園との関係とか、こういった施設が増えていくのかとか、そういった区の今後の考えをお伺いさせてほしいと求めました。そういういろいろな施設が混在していくという形になっていくような感じがするんですけれども、区として今後どのように考えられているか尋ねました。","respondent":"吉岡保育課長","answer":"区としては従来から実施をしてまいりました幼保一体施設について、品川区の幼児教育、保育の中核として今後もしっかり運営をしていきたい。国の動向については法案の内容、成立の状況等を見きわめながら、しっかり対応してまいりたいというふうに考えてあります。","id":"exchange-042"},{"speaker":"沢田委員","kind":"提案","question":"こども園のほうは国として提案されているということですけれども、そのうちの５園が幼保一体施設の中の一部の幼稚園ということになっているです。今後、見通しというか、区立の幼稚園がどういうふうになっていくのかということもお話をお聞かせほしいと求めました。","respondent":"吉岡保育課長","answer":"区立幼稚園を希望される方の動向ですとか、そういうものをしっかり見きわめながら検討していくことになろうかと思います。協力し合いながら、品川区内の幼児教育をしっかりと実施していく、そういうことであるというふうに考えております。","id":"exchange-043"},{"speaker":"沢田委員","kind":"質問","question":"私立のこども園ということで品川区に１園あるということですけれども、そういったときに、区としてはどういうふうに対応される予定か尋ねました。","respondent":"吉岡保育課長","answer":"現在、私立のほうは、学研こども園という平成２０年１２月にオープンした認定こども園が１園あります。今後につきましては、事業運営者のいろいろな事業運営に対する考え方もありますので、十分検討しながら進めてまいりたいというふうに思ってあります。","id":"exchange-044"},{"speaker":"藤原委員","kind":"質問・要望","question":"それとお金のことを伺いますが、運営費助成が１,１００万円とついておりますが、社会福祉協議会に委託というか実施してもらっていますよね。そのうち区が実際に出している金額も教えていただきたいのと、あと、それは人件費を含めてどうなのかということをお伺いします。","respondent":"原高齢者福祉課長","answer":"この経過としますと、平成７年から社会福祉協議会のほうは財産保全サービスを区と協力して実施をしてきてあります。区との関係では、そういった中で協力関係を持ちながら実施をしています。","id":"exchange-045"},{"speaker":"藤原委員","kind":"質問","question":"人間がやっていることですから。プラス、あってはならないことですけれども、品川区において今までそういうトラブルがあったのか、説明を求めました。","respondent":"原高齢者福祉課長","answer":"倫理観だけでは到底できない部分も当然ありますので、仕組みとして、そこをきちんと担保しておくということが大変重要かというふうに思います。お金の出し入れをするときには、二人で同行をしてきちんと実施をする等ということで、ダブルチェックをかけてやっております。","id":"exchange-046"},{"speaker":"藤原委員","kind":"質問・要望","question":"昨日の質問の中で、その併設として保育園もつくっていただきたいという思いを込めて、次に保育待機児についてお伺いします。乳幼児数の動向と申込者数の動向について、改めてお伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"私から今後の５年ほどの乳幼児数と申込者数の見込みというお尋ねについてお答えをいたします。保育園に今何人在園をしていらっしゃるかということとも関係してまいりますので、現状を保った申込者数で推移するのではないかと考えております。","id":"exchange-047"},{"speaker":"藤原委員","kind":"質問","question":"今まで保育課がやっていたわけですから。という思いがあるんですけれども、どういうお考えがあるか、説明を求めました。","respondent":"伊崎待機児童対策担当課長","answer":"乳幼児人口の動向につきましては、先ほど申し上げましたように非常に難しいものです。例えばなんですけれども、国立人口問題研究所というところがありますが、そちらの統計もなかなか合っていないです。","id":"exchange-048"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは１３７ページ、児童福祉施設費、そして１４０ページ、生活保護費についてお伺いをさせてほしいと求めました。その中で、区としてはどうしていくというようなお考えがあるのか、お答えください。","respondent":"平澤生活福祉課長","answer":"私どものほうでも就労支援員という者を置きまして、実は昨年は３人だったんですが、今年は４人に増やしていただいたところです。そういったところで、そういったところに力を今後も入れていきたいというふうに考えているところです。","id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば今、現在品川区では一人当たりどのくらいの人数を担当されているのか、何人担当されているのか教えてほしいと求めました。人によって１００人だったり８０人だったり違いがあるのか、最大でどのくらい一人で担当しているのか、わかれば説明を求めました。","respondent":"平澤生活福祉課長","answer":"こういった方につきましては、昨年度から高齢者専門のケースワーカーというものを置きまして、一人１２０人の方を見てもらっています。現在の状況でいきますと、それと一般のケースワーカーが４２人ということで、一般のほうが一人あたり大体９０人ほどを担当しているです。","id":"exchange-050"},{"speaker":"大倉委員","kind":"質問","question":"もう少しきめ細やかなサービスをしていくというのであれば、もう少し一人当たりの担当人数というのを減らしていくことが必要なのではないかなと思うのですが、その辺はどうか尋ねました。","respondent":"平澤生活福祉課長","answer":"それからまた先ほどの就労支援の専門員、それを専門に指導していくという職員、これが４人おります。現状の体制で、これからもきちんとした支援を行っていきたいというふうに考えているところです。","id":"exchange-051"},{"speaker":"大倉委員","kind":"意見","question":"前年度の職員の数が５２人から今、５５人に増えて、増えていったりというのはやはりないのかなというのをもう一度ちょっとお聞かせほしいと求めました。","respondent":"平澤生活福祉課長","answer":"実を申しますと、リーマンショック以来ということなんですけれども、生活保護受給者につきましては急激に上昇したというところがあります。そういったところに対応するために、またそのときの状況を見まして判断していきたいというふうに考えているところです。","id":"exchange-052"},{"speaker":"大倉委員","kind":"質問・要望","question":"続きまして、１３７ページの一日保育士体験事業経費についてお伺いをさせてほしいと求めました。この事業のご説明をお願いいたしたいと思います。","respondent":"安井子育て支援課長","answer":"こちらは品川区の公立保育園全園で実施しているものでございまして、保護者の方に一日、保育園のほうで保育士として実際の保育に当たっていただく。さまざまな子育てに関して勉強をしていただくというような機会を提供するということで、親育ちの支援をしていくという事業です。","id":"exchange-053"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうした中で、どういう生活をしているのかというのを見るのは、育てていく親としても大変安心していける事業なのではないかなと考えています。その中で、この２５万５,０００円ですが、この額はどういったものなのか教えてほしいと求めました。","respondent":"安井子育て支援課長","answer":"その分を区のほうで負担する。これについての各園での周知活動であるとか、そういったものの事務費に充てております。","id":"exchange-054"},{"speaker":"大倉委員","kind":"質問","question":"今後、例えば負担を本人にしていただくという考えなのか、このまま区で負担していくという考えなのかを教えてほしいと求めました。","respondent":"安井子育て支援課長","answer":"自分のお子さんだけではなくて、ほかのお子さんを見ていただいている、そういう意味ではボランティアで参加していただいているわけですので、給食費については当方のほうで負担するのが適当であろうというふうに考えております。","id":"exchange-055"},{"speaker":"大倉委員","kind":"意見","question":"ボランティアということで、出すということであるということなんですが、もう少し時代に合わせてこれからも考えてほしいと求めました。ちょっと時間が余ってしまいましたが、以上で終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"阿久津委員","kind":"質問","question":"平成２２年度予算では想定が４,６３５人となっていたのですが、１２８ページですけれども４,２５１人ということで３８４人の減となっております。この数字の差について説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"長寿お祝い事業における数字の差なんですが、実際は予算立てをするとき、ちょうど今頃ですね。１０月から１１月にかけて予算立てをしていくのですが、それから配付が翌年の９月ということで、その間の人口の流動が原因であるです。","id":"exchange-057"},{"speaker":"阿久津委員","kind":"確認","question":"全国で戸籍上１００歳以上となる高齢者が実は死亡していたという事件が発覚しまして、年金の受給詐欺というものも問題になりました。決算に記載のある４,２５１人、直接お祝いをされて、ご健在を確認されたということでよろしいのか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"１件につきましては生存が確認され、残りの５件のうち、外国人の方については手続きをせずに帰国されていたということで３名おりました。２名については更地になっていたということで、住民票の所管部署のほうに引き継いだということで、全件について確認が終了しているです。","id":"exchange-058"},{"speaker":"阿久津委員","kind":"確認","question":"高齢者の方に感謝と敬意を表するこの事業、そして健在を確認をする事業ですので、今後ともぜひよろしくお願いいたします。利用率もシルバーセンターの中で非常に高いと伺っておりますが、利用状況について簡単にお願いします。","respondent":"間部高齢者いきがい課長","answer":"８月以降の利用の状況ですが、かなり多くの方のご利用をいただいておりまして、前年度の比で見ましても２.３倍ぐらいになってあります。利用者の方と館内において世代間交流が図れるということもございまして、非常にこの点については成果が上がっているものと認識しています。","id":"exchange-059"},{"speaker":"阿久津委員","kind":"質問・要望","question":"ご要望としてお伝えさせていただきたいのですが、これは何度か、何人かからお伺いをしております。できれば緩やかなスロープにしていただきたいと思うんですが、この点についてご見解を伺いたいと思います。","respondent":"間部高齢者いきがい課長","answer":"当然そういうお声をいただきまして、私どもでも調査を進めたのですが、ここがちょうど私道ということでありました。私道の整備工事については建築課の細街路担当のほうでも行ってありますので、先方と協議をしながら対応してまいりたいと思います。","id":"exchange-060"},{"speaker":"阿久津委員","kind":"質問・要望","question":"続きまして１３１ページ、精神障害者地域生活サポート２４、また障害者交流スペース「憩いの場」運営委託ということについてお伺いをします。人員とか予算の観点からも強力に進める必要があるというふうに考えておりますが、品川区の今後の方針についてお伺いをします。","respondent":"永尾障害者福祉課長","answer":"地域生活安定化支援事業につきましては、今年度は医師を１人採用いたしまして、その医師の服薬管理と医学的な部分の支援を始めました。これからはもう少し研究をしながら、その医師の訪問を広げていかれたらというふうに考えております。","id":"exchange-061"},{"speaker":"阿久津委員","kind":"質問","question":"１７１人、３,３２９万６,３８２円、これは一律同じ形式の葬儀なんでしょうか。お一人どの程度の葬儀費用がかかるものなのか尋ねました。","respondent":"平澤生活福祉課長","answer":"２０万１,０００円になってあります。ですから２０万１,０００円プラスアルファぐらいです。","id":"exchange-062"},{"speaker":"阿久津委員","kind":"質問","question":"その２０万１,０００円という金額なんですが、葬祭費１件当たり７万円が支給されるということですが、これはその場で現金でいただけるのでしょうか。それとも振り込みで日数がかかるのか尋ねました。","respondent":"本城国保医療年金課長","answer":"今の国民健康保険の葬祭費に関するご質問ですが、被保険者が亡くなった場合に葬祭を行った方に対して支給するということで、葬祭を行ったことを何らかの形で証明していただいて、それに対して振り込ませていただくです。","id":"exchange-063"},{"speaker":"阿久津委員","kind":"質問","question":"しかし葬儀を出すことができない。ちょっと悲しい状況だったのですけれども、これに対して何か本区として何らかの措置ができないのか、そこについてお伺いしたいと思います。","respondent":"平澤生活福祉課長","answer":"こちらの福祉資金の中に葬祭費というのがございまして、５０万円を限度にお貸しするということになってあります。保証人がある場合には無利子、保証人がない場合には１.５％の利子ということで、こういったことにつきましてご案内させていただいている次第です。","id":"exchange-064"},{"speaker":"阿久津委員","kind":"意見","question":"貸し付けということで、貸し付けにも多分時間がかかるのではないかというふうに思います。スムーズで柔軟な対応をまた今後ともお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"原委員","kind":"質問・要望","question":"私は、成果報告書１２５ページの社会福祉総務費全般について、細部から広くお伺いをしていければと思います。これだけ四つ、すみません、できましたら３０秒から１分ぐらいで、都合があるものですから。","respondent":"平澤生活福祉課長、安井子育て支援課長、原高齢者福祉課長、間部高齢者いきがい課長","answer":"生活安定応援事業についてご説明をいたします。大きな柱といたしまして、低所得者の児童向けの受験料ならびに塾料の助成… 平成２１年度のほうのＤＶ被害者等の生活支援給付金ですけれども、定額給付金の終了をもって、こちらについても終了という形になってあります。 法人貸付住宅の関係です。例えば戸越台特養ホーム等に介護スタッフが泊まって緊急時に対応できるような体制のために貸し付けているものです。 １３２ページ上段のマッサージサービスにつきましては、視覚障害者の団体にお願いをしているもので…","id":"exchange-066"},{"speaker":"原委員","kind":"質問・要望","question":"そうすると、それ自体はどうなってくるかというと、その後で、逆に家の中で事故が発生をして、それで保険で対象になっているのではないのかなと。監視していただきたいのですけれども、その辺については、ちょっとご意見をほしいと求めました。","respondent":"間部高齢者いきがい課長","answer":"シルバーセンターにおきますマッサージは、先ほどご説明したとおり視覚障害者協会にお願いをして実施しているもので、一人当たり３０分程度の施術ということで、あくまでもこれは憩いを目的に、ですので、そういう不正等はないという認識を持ってあります。","id":"exchange-067"},{"speaker":"原委員","kind":"意見","question":"ところが先ほど来出ている費用を考えますと、ここの民生費というのが一般会計予算でもう４割を超えてきている。まつり実行委員会とか、ちょっと非常に細かい点なんですけれども、その辺だけ簡単にお答えできればお願いしたいと思いますとの意見を述べました。","respondent":"永尾障害者福祉課長","answer":"障害者まつりは、１２６ページのところにあります知的障害者育成会から一番下の精神障害者家族会の七つの団体、障害者まつりを開催しております。障害者まつりにつきましては、その趣旨に合う内容ですので、区といたしましても助成金を交付しているというようになっております。","id":"exchange-068"},{"speaker":"原委員","kind":"質問","question":"細部ですから大したことではないのかなと思うんですが、ちょっと気になりましたので申し上げました。お願いいたします。","respondent":"原高齢者福祉課長","answer":"区と各法人が区民サービスの向上のために連携をとりながら実施する、こういった目的の中で助成をさせていただいているものです。その使い道あるいはこういったものが継続したときに、こういったいろいろな観点で考え、こういうような形でやっているものです。","id":"exchange-069"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、教育の品川、福祉も品川、こういう形に持ってきていただきたいんですね。品川区としてどういうふうにお考えになっているのかを、残り２分半ぐらいありますので、思いを語ってほしいと求めました。","respondent":"木下健康福祉事業部長","answer":"社会福祉法人に対する支援も、同じような支援を漫然と続けていくことではなく、パートナーシップとして見守りながら必要な支援をする。見直すべきものは見直していくというような姿勢を基本に据えて進めていきたいというふうに思ってあります。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問","question":"２２４ページの居宅介護について、続いて１３６ページの待機児対策、続いて１３７ページの育児休業等代替人材派遣委託について順に伺います。この問題についてちょっと驚いたんですけれども、いつの時期に撤退をしたのか、また撤退の理由を説明を求めました。","respondent":"原高齢者福祉課長","answer":"その人に合った対応をきめ細かにしていくという趣旨で併設をしてきたところです。あるいは変更時に混乱がないようにということで、区もかかわりながら安定した形で次の事業者に引き継いだ、こういうような経過です。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問","question":"撤退をする。私は本当に無責任であり、ひどいな、企業の姿は許せないなと思うんですけれども、区の考えはいかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"地元の企業も入っていただきながら実施しています。そういう中でも、利用者に迷惑がかからないようにということを、我々区としては、保険者としては十分配慮した形で対応してきているところです。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問","question":"お二人の方の質問で、３９０人増やすと言っていますけれども、改めて一つ伺います。この問題なんですけれども、この点、伺いたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"今年の４月に新設をした園と来年の新設予定の園のうちの株式会社の数ですが、とうかいどう保育園、グローバルキッズ荏原町保育園を開設いたしました。来年度の予定につきましては６園開設を予定しておりまして、それからアスク南大井保育園ですが…","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区はこの間、区がみずから区立の保育園をつくるように求めてきましたけれども、本当にみずからが待機児解消を進めていくべきであると思っています。ここからが質問なんですが、企業へのさらなる税金投入が税金の正しい使い方になるのかどうか、この点と、どこまで税金を投入していくのか。","respondent":"伊崎待機児童対策担当課長","answer":"それから開設にあたりまして、賃貸の場合は１０年間は賃貸借契約を結ぶことという最低要件があります。特に株式会社立につきましては、非常に細かい会計上の規制がありますので、それをもって安全な事業者の参入を図っているところです。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"確認","question":"幾つかの歯どめをお伺いしましたけれども、２０００年に児童福祉法が変わった段階から歯どめがどんどん外れているんですね。この点を特に強調したいと思いますけれども、いかがか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"ただ保育の実施責任ということイコール、公設公営で施設を運営することではないと考えております。これは今、ご指摘がありました平成１２年３月の保育所の設置主体の制限の撤廃ということが国のほうでされておりますので。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ区立の保育園をつくっていただくように方向転換をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"渡部委員","kind":"確認","question":"いわゆる短時間契約というものと一時保育というものの分け方についてまず確認したいのと、それとあといわゆるオアシスルームがあります。どのような方が何名体制で日ごろ対応されているのか、同じ時間に最高何名まで預かることができるのか、その辺をまず説明を求めました。","respondent":"吉岡保育課長","answer":"区内、区外の考え方ですけれども、基本的に区が助成金を出してやっている事業ですので、区民の方を対象にというふうに考えているのが基本です。それからマックスですけれども、施設的な広さの制約がありますので、一度にお預かりできるお子さんは１４人ということで伺っておりま…","id":"exchange-077"},{"speaker":"渡部委員","kind":"質問","question":"１件やっているわけですけれども、可能性として、品川の中にはほかにも空き店舗を抱えている商店街があろうかと思います。品川区民もしくは品川に来訪いただいた方を対象として一時保育、今後の展開等もどのようなお考えがあるのかを含めてお教え願えますか尋ねました。","respondent":"吉岡保育課長","answer":"あるいは日曜日、人出のあるところでお預かりをするような仕組みとか、いろいろ可能性としては考えられるかなと思っています。今後も区民とのつながり、協働の中で、地域の子育てを進めていくという方向性はしっかり持っていきたいと思ってあります。","id":"exchange-078"},{"speaker":"渡部委員","kind":"質問・要望","question":"１２億６,４１１万８,０００円、ちょっと一つお伺いしたいのが、さまざま多岐にわたっている。派遣というんでしょうかね、どれぐらいの割合があるのかを教えていただきたいのと、教えていただけますか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"ただ近年、地域コンビニ事業をはじめとしまして、家庭でのさまざまなお困り事について支援をしていこうという事業を進めて、拡大を図っております。特に高齢化社会がこれからますます進むであろうということで、そういった形での仕事の拡大を図っていくというふうに聞いてありま…","id":"exchange-079"},{"speaker":"渡部委員","kind":"質問・要望","question":"その高齢の方々、働く意欲のある方に対して仕事をたくさんやってほしいと求めました。どのような形かでフィードバック、業者を紹介するとか何か、そういうことはされているんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"初めの段階でコーディネーターのほうでその仕事が適切かどうか、回せるかどうか判断しまして、それから会員のほうへ回すという形をとってあります。","id":"exchange-080"},{"speaker":"吉田委員","kind":"質問","question":"成果報告書の１３９ページと１４０ページの児童センター事業と、１２９ページのひとり暮らし高齢者等福祉費についてお尋ねしていきたいと思います。平成２１年度が１億４９８万３,９００円ですが、平成２２年度が２億５,１７１万６,０６０円に増えているわけを説明を求めました。","respondent":"安井子育て支援課長","answer":"平成２１年度のときは、いわゆるキッズ館と呼ばれている保育園と連携の事業という扱いになっていたものを、児童センターのほうに全部一括して計上させていただいている関係で、こちらの指導員謝礼の金額のほうが大きくなっているです。","id":"exchange-081"},{"speaker":"吉田委員","kind":"意見","question":"平成２２年度から始められたシルバーセンターとの交流事業、これは場所もお願いしたいんですけれども、そしてあともう一つ、しながわ子育てメッセ２０１０についてもお教えくださいとの意見を述べました。","respondent":"安井子育て支援課長","answer":"そういったことが地域の中での子育て、そちらについてもプラスになっていくというふうに考えておりますので、こちらを進めているところです。しながわ子育てメッセのほうは子育て世帯に対する情報提供の支援ということで、私どものほうで計上させていただいて…","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後に広報等でというお話を聞いたので、それはいいことなので、ぜひたくさんＰＲしてほしいと求めました。トラブル等もございましたら、何かありましたら、今わかる範囲等でお教えください。","respondent":"安井子育て支援課長","answer":"しながわ子育てメッセ２０１０、ＮＰＯとか、より身近で実際に子育てを支援する団体のほうに積極的に逆に入っていただくような形にしていったと聞いております。","id":"exchange-083"},{"speaker":"吉田委員","kind":"意見","question":"子どもたちのためにもさっきのシルバーセンターとの交流なども、現場の先生の声も反映していっていただけたらと思います。１２９ページの上に２４時間対応訪問介護サービスモデル事業と２４時間定期巡回・随時訪問サービスモデル事業のご説明をお願いいたしますとの意見を述べました。","respondent":"原高齢者福祉課長","answer":"夜間型の訪問介護を使っている方々を対象に２つの事業を実施しまして、随時に何か困ったときに連絡を受けて、駆けつけた上で介護をする。こういったのが上の２４時間対応訪問介護サービスモデル事業です。","id":"exchange-084"},{"speaker":"吉田委員","kind":"意見","question":"２０分というのがとても短いような、２０分と区切っていいのかなというのがすごく疑問なんですけれども、お時間もないことで、まだまだ改善するところがたくさんあると思うんですけれども、最後に今後どうなさっていくのかを、一言だけお願いしますとの意見を述べました。","respondent":"原高齢者福祉課長","answer":"今後の展開ですけれども、来期、平成２４年度からの３年間の中で、この事業については国のほうでも新サービスということで位置づけられております。あわせて平成２３年度もこれの継続版ということで、少し形を変えて実施をしています。","id":"exchange-085"},{"speaker":"吉田委員","kind":"質問・要望","question":"年々増えるおひとり暮らしの高齢者の方々に、いつまでも自宅に住み続けていただきたいという気持ちもありますので、こういう事業を進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"金野委員","kind":"確認","question":"私のほうからは１２８ページの高齢者世帯の安否確認事業、そしてもう一つが１３４ページのひとり親家庭支援事業、こちらを伺いたいと思います。高齢者の方の安否確認ですけれども、どういうふうに整理をしたらいいんでしょうか、お願いします。","respondent":"原高齢者福祉課長","answer":"現在実施しているのは、夜間対応型ということで、２２時から朝の７時までの深夜帯の訪問介護という形になってあります。以前は２４時間の対応型ということも実施してございましたけれども、そういった意味では、夜間対応型から、まず一つは２４時間型に変わっていく。","id":"exchange-087"},{"speaker":"金野委員","kind":"質問","question":"対象者は健康状態に不安があり、常時注意を要する状態にある方となっておりますけれども、具体的に健康状態が不安、常時注意を要すると。どの程度の方なんか尋ねました。","respondent":"原高齢者福祉課長","answer":"こういった場合は緊急に状態が悪くなって、自分で救急車を呼んで救急車に乗っていくというところが非常に困難である、そういうような状況です。こういうような状況がありますので、そういった方々のためにコールボタンを押して、救急車の対応という状況になっているところです。","id":"exchange-088"},{"speaker":"金野委員","kind":"質問","question":"「どう、見守っていてはくださるんですが、でもやっぱり限度があるんですね。やはり夜間などは心配だというところもあるので、どうなんでしょう、これを要件をさらに拡大をするというお考えはありますか尋ねました。","respondent":"原高齢者福祉課長","answer":"そういった中で、現在の対象が少し厳しいのではないかです。私ども個々のご利用者様の状況をケアマネジメントする中で、必要な方については考えていくというような体制でいきたいと思っているところです。","id":"exchange-089"},{"speaker":"金野委員","kind":"質問","question":"確かにそうだろうと思います。ですが、ひとり暮らしの高齢者の方のしおりみたいなのが一覧としてあったりするといいのかなという、こういう考え方はどうなんか尋ねました。","respondent":"原高齢者福祉課長","answer":"委員ご指摘のところも一つのアイデアというか、わかりやすさの一つだというふうに認識をしております。一方でそういう部分的な情報ではなく、全体を見れる形というようなご意見もありますし、それも含めて検討していきたいと思っているところです。","id":"exchange-090"},{"speaker":"金野委員","kind":"提案","question":"民生委員のお仕事もたくさんあるので、そうしたところのお仕事の緩和というか、負担軽減にもなるかなという思いで提案させていただきました。もう一つ、ひとり親家庭のところですが、時間もありませんので、またの機会にしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"対象を広げてほしいということでのご発言だったと思うんですが、そこら辺のところは、これと同じような形で対象を広げてほしいというのが１点です。お金がないためにそのサービスが受けられないということがないように、ぜひ無料化をお願いしたいと思うんですが、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"そういったものを含めて、トータルの中で検討していくというふうに考えているところです。そういうテスト的なものを含めて、そういったところの通信費になってありますので、ご理解をいただきたいと考えています。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、この緊急通報システムは所得の少ないところは無料でやっているというところが他区を見ても多いんです。そういう点では、無料化についてぜひご検討いただきたいと思うんですけれども、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"３,０００円近くの契約料を払って、その中で所得に応じてということで１,８００円、それから５００円ということでしています。そういった意味ではご理解をいただきたいと思っているところです。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは民間型であっても１９９台ということで、７万人の高齢者に対してこういう状況ですから、ぜひ拡大ということでお願いしたいと思います。支え合いをつくるという点でも、また改めて復活させていただきたいと思うんですが、このことについても説明を求めました。","respondent":"原高齢者福祉課長","answer":"そういった中で何かあればボランティアさんが鍵をあけて中に入るといったような状況です。そういったところは負担であるということと、なかなか鍵を預かっていただける方が新たに出てこないといったような事情です。","id":"exchange-094"},{"speaker":"本多委員","kind":"質問","question":"その平成２２年度の決算を踏まえまして、区の独自の補うという点についてどうお考えか、教えてください。この平成２２年度と現在とを比べますと、民間企業からの仕事量も減ってきている傾向ですし、そういった部分の把握をされているのかお知らせください。","respondent":"福島ものづくり・経営支援課長","answer":"約６,６００万円の事業を行ってもらったりですとか、そういうことを行いながら、シルバー人材センターの考えです。それに対する支援も行っていきたいというふうには考えてあります。","id":"exchange-095"},{"speaker":"本多委員","kind":"質問・要望","question":"区でできる範囲のことを支援していただきたいと思うんですけれども、これに関連しまして、国の補助金のカットというところでは、民生費全般におきまして、ほかにもたくさん補助金カットになっていると思うんですけれども、その部分に対して補うという考え方、現状で考え方をお知らせください。","respondent":"榎本企画財政課長","answer":"私の知る限りでは大きく補助金がカットされたというのは、このシルバー人材センターのほうという形と認識しています。","id":"exchange-096"},{"speaker":"本多委員","kind":"質問・要望","question":"１４０ページの生活保護費なんですけれども、先ほども出ておりますけれども、まずこの間の本会議で財源のことは要望させていただきました。国の中でも都内が一番保護率が高くて、都内の中でも２３区が一番保護率が高くて、ぜひ財源については引き続きのご努力をお願いしたいと思います。","respondent":"平澤生活福祉課長","answer":"ただ就労開始につきましては今年のほうが多くて２３５世帯、去年が２２８世帯というふうになってあります。ハローワークにこういうふうに通っているとか、そういった中で足りない部分がある場合は、改めて別の見地からご指導しているというのが実情です。","id":"exchange-097"},{"speaker":"本多委員","kind":"質問・要望","question":"住宅は５種類の施設での保護施設はあるものの、原則、その施設の利用状況をどのように把握されているのか。代理納付ですとか、かなり改善されてきていると思いますので、その点についてお知らせください。","respondent":"平澤生活福祉課長","answer":"もう１点の、国のほうでも居所の確保、家賃を滞納することがないようにということで進めているところです。ただ３,７３５世帯の中には、昨年が３７２世帯であったところなんですが、少しずつ増やすことができているという委細です。","id":"exchange-098"},{"speaker":"本多委員","kind":"質問・要望","question":"広報になると昨日の総務費になってしまうんですけれども、その広報に載せてある金額の載せ方が、担当部署としてはどう思うかを聞かせていただきます。この辺は広報のほうには要望いたしますが、担当部署からその辺をどう思うか、お答えをほしいと求めました。","respondent":"平澤生活福祉課長","answer":"ただ生活保護につきましては、自治体間で相当な格差があるというのは、委員からもご指摘があったとおりです。そういった意味からも、なかなかこの取り扱いをどうしていくかというのは、これから少し考えていくべき課題だというふうに考えております。","id":"exchange-099"},{"speaker":"本多委員","kind":"確認","question":"本人の確認なしに切りかえられてしまったという事例があったかと思うんですが、これは町会長の推薦がないとできないという答弁だったんですね。その改選期の現職の民生委員が、本人は意欲があるのに、その人選についての考え方に変わりがないのかどうかだけ説明を求めました。","respondent":"原高齢者福祉課長","answer":"民生委員の推薦については町会にお願いしていますので、そういった中で推薦されてくるというふうに理解しています。","id":"exchange-100","title":"町会・自治会支援"},{"speaker":"高橋委員","kind":"質問","question":"予算が約２,０００万円、決算が約９１５万円、執行率が約４５％でしょうか。それから１３９ページのほうの児童センターについては、一言で言うと、児童センターって一体何なんか尋ねました。","respondent":"永尾障害者福祉課長、吉岡保育課長、安井子育て支援課長","answer":"それと支援者養成研修につきましては、年２回で６０万円、その辺の経費ということで６０万７,０００円余ということになっております。… あるいは出産をする場合、それから病気の方や障害の方の介護とか、就労以外の要件も認めているところです。しかしながら保育ママのほうは… ０歳から１８歳までのお子さんを対象に、だんだん在宅の子育て支援であるとか、そういったものもやるようになってきている。児童福祉関係については…","id":"exchange-101"},{"speaker":"高橋委員","kind":"確認","question":"今後その要件を変えていくかということはどうなんでしょうかということを確認して、次、それは何が当初の予定より少なくなったんでしょうか。この結論を受けて、勇気を持って見直しをというコメントもあったんですが、その点についてはいかがか尋ねました。","respondent":"吉岡保育課長、永尾障害者福祉課長、安井子育て支援課長","answer":"昨年の１０月から七、八年ぶりに再開をした事業でございまして、まだ箇所数もそんなに多くございません。今現在のところでは… こちらの成果報告書のほうに延べ８１名と記載してしまってあるんですけれども、実人数が８１名ということですので、申しわけございませんでした。… あるいは要請に応じて、さまざまに変わっていくという必要性があるということで変えてまいりますので、いろいろ検討してまいりたいと考えています。","id":"exchange-102"},{"speaker":"高橋委員","kind":"意見","question":"最後になりますが、新児童福祉法が来年の４月から施行されますが、それに伴って障害児に関連する事業が児童福祉法のほうに入ることになるんですが、子ども未来事業部のほうに事業を移す、あるいはそういうことについては今後の検討かと思いますが…","respondent":"永尾障害者福祉課長","answer":"障害者の関係で障害者自立支援法が改正になりまして、来年の４月１日に施行になります。児童の関係が大幅に変更になっておりまして、これについては、部をまたがりますけれども、今後も検討していきたいと考えております。","id":"exchange-103"},{"speaker":"南委員","kind":"質問・要望","question":"法制化ということと社会生活を営む上での障壁を除去し、品川区はこういうことについてどういうふうに考えておられるのか、見解を伺いたいと思います。そのあたりの考え方も含めて、どういうふうに整備をしてきたかも含めて、教えてほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"基本法でさらにそれを確認したというふうに認識しております。社会福祉法人、うちのほうでもできるだけ広げられたら広げたいと考えていますので、条件を加味しながら支援していきたいと考えております。","id":"exchange-104"},{"speaker":"南委員","kind":"質問","question":"１０施設、入所されている方々は何人いらっしゃるのか、その数を改めて伺いたいと思うんです。それから、そのあたりの区の認識というか、それも説明を求めました。","respondent":"永尾障害者福祉課長","answer":"現在の利用者数ですけれども、１０１名となっております。こちらについては、やっぱり親御さん、区のほうのケースワーカーもその辺をじっくり話していっているようなところです。","id":"exchange-105"},{"speaker":"南委員","kind":"質問","question":"ですから、さまざまな手だてを講じるという点では、それはそれでまた大変な負担になる。やっぱりなれていただく、そういう準備が必要なのではないかなと思うので、その辺についての認識も伺いたいと思います。","respondent":"永尾障害者福祉課長","answer":"グループホームとなると、近隣との関係や担い手の関係がございまして、一概に目標数というのを掲げるのは難しい部分はあります。試行で入るということになって一つの部屋を空けておくと、やはり稼働率の問題があったりということで、なかなかそこは難しいと考えています。","id":"exchange-106"},{"speaker":"南委員","kind":"質問","question":"なかなかその辺についてどういうふうに見ておられるのかというのを改めて伺いたいと思っているんですけれども、また親なき後も生活が自立して送れる。それからもう一つ、１２７ページのさくら会について伺いたいと思うんですけれども、このサービスの内容はどういうものなのかを改めて説明を求めまし…","respondent":"永尾障害者福祉課長、原高齢者福祉課長","answer":"その方法については、現状の施設の運営等もありますので、そういうものも加味した上での体験の仕方というのを考えていきたいと考えています。 こちらのほうは老人保健施設ということで、リハビリを中心としたケアを実施しています。これについては、市町村特別給付ということで実施をしているものです。","id":"exchange-107"},{"speaker":"南委員","kind":"質問・要望","question":"それから水中リハビリについては、どのくらいの状況で実施しているのかということを伺いたかったんですね。１週間に何回ぐらい、エリアがどういうふうになっているのか、あるいは送迎についてはどうなのかということを説明を求めました。","respondent":"原高齢者福祉課長","answer":"利用の状況ですけれども、週１回、１回に対して９０分ということで、１年間コースで実施をしています。それからエリアですけれども、送迎等々の関係もありますし、そういった意味では近隣の方を中心にということで実施をしているものです。","id":"exchange-108"},{"speaker":"南委員","kind":"質問","question":"年間延べ人数だから１２で割っていくという考え方でいいんですか。あるのかないのか、近隣中心にということなのでないのかなというふうにも想像するんですけれども、ちょっとその辺を説明を求めました。","respondent":"原高齢者福祉課長","answer":"延べの利用回数は１,１７３回という状況です。利用者の方によっては中延地域からも行かれるということで、近隣といいながらも、少しそれより広い部分も若干カバーしているです。","id":"exchange-109"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういうスペースというか、体制をしっかり整えていただきたいというご要望があるんです。施設の中の方にちょっと声をかけていただいてつれていただけるとか、そういうことも含めて検討していただきたいということをお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-110"},{"speaker":"山元委員","kind":"質問・要望","question":"もう１点が１３２ページのシルバーセンター運営費の中のマッサージサービス経費についてお伺いさせてほしいと求めました。判断能力が不十分な方を支援する制度でありますけれども、改めてこの制度の目的、また重要性について教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"ご自身等が持っている財産をきちっと管理する、そういったためにこういった成年後見制度が必要だということで認識をしています。そういった意味では、今後を踏まえて、さらにこういった補助をしていかなくてはいけないというふうに認識しています。","id":"exchange-111"},{"speaker":"山元委員","kind":"質問","question":"こちらのほうに高齢者また障害者等の金額というんでしょうか、具体的にどのくらいの方が利用なさっているのか、金額に対して何人なのかを教えていただけますか尋ねました。","respondent":"原高齢者福祉課長","answer":"そういった中で件数ですけれども、平成２２年度をとってみますと、高齢者のほうが３２件です。障害者のほうは１件です。","id":"exchange-112"},{"speaker":"山元委員","kind":"質問・要望","question":"２７ページのこちらの品川成年後見センターですかね。もし同じであれば教えていただきたいことがあるんですが。","respondent":"原高齢者福祉課長","answer":"２７ページのほうは、成年後見センター全体で扱っている件数ということと、それから冒頭のご質問のところは区長申し立てにかかる部分ということで、数字がそういう意味では違っているということでご理解いただければというふうに思います。","id":"exchange-113"},{"speaker":"山元委員","kind":"質問・要望","question":"１,０００件以上の方から問い合わせがあり、どのようなご相談が多いのか、教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"区長申し立てに持っていって、そこの財産の保全等に早期につなげていく、こういう形でやってあります。１,０００件以上の問い合わせがありますけれども、まず制度の中身であったり、そういうような今後のことを見込んでの相談等々があるです。","id":"exchange-114"},{"speaker":"山元委員","kind":"質問・要望","question":"もう一つ聞きたかったんですが、具体的に面接といいますか、相談員ということになるんでしょうか。相談員の人数的なことがわかれば教えていただきたいということと、何かそういう情報、何かおわかりになれば教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"援助スタッフがまずそこを認識するとともに、ホームページでありますとか、成年後見センターのほうでチラシをつくっていろいろな機会でご案内する。それから山田副区長のほうで、２０１０年成年後見法世界会議で発言もしていますので…","id":"exchange-115"},{"speaker":"山元委員","kind":"質問・要望","question":"その場合にお兄さんの施設でのさまざまなお願い事ができなくなってしまったときに、どうしようと。今、周知の方法をいろいろおっしゃっていただきましたが、今後、また周知の方法で何かお考えがあれば、教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"いろいろな形で媒体を使い、また人のネットワークの中でそういったある形を伝えていければと考えています。さらに今までのＰＲの方法に加えて、今後どんなことが必要かというところを検討していきたいと思っているところです。","id":"exchange-116"},{"speaker":"山元委員","kind":"質問・要望","question":"１３２ページのシルバーセンター運営費の中のマッサージのサービス経費についてお伺いします。初めに、シルバーセンター１６カ所でこのマッサージサービスというのが行われているのか、この辺を教えてほしいと求めました。","respondent":"間部高齢者いきがい課長","answer":"シルバーセンターにおけますマッサージですが、東品川のシルバーセンターにおきましては毎週火曜日、その他のシルバーセンターにつきましては月に１回、８月と１月を除いて全１０回行われているです。","id":"exchange-117"},{"speaker":"山元委員","kind":"質問","question":"聞くところによると、このマッサージはもう１０年こういう制度があると聞いておりますけれども、実際、そのときのマッサージをしてくださっている方たちの報酬というのはどのくらいからスタートし、実際今はどのくらいなのか教えていただけますか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"このマッサージにつきましては、視覚障害者協会の方にお願いしているんですが、一人当たり１万１,０００万円の報酬ということで、１０年以上値上げをしていないという状況です。","id":"exchange-118"},{"speaker":"木村委員","kind":"質問","question":"１２６ページの下から７行目までの各障害者団体についての質問です。どうしてこのようにして各団体に金額の違いがあるのかと、何かわけがあるんでしょうか、説明を求めました。","respondent":"永尾障害者福祉課長","answer":"障害者７団体につきましては、地域の障害者の生活の向上のためにいろいろ活動されているということで、その助成金を出しているものです。その部分の支援も行っているということで、平成２２年度は５０周年でございましたので、その分の経費を支出しております。","id":"exchange-119"},{"speaker":"木村委員","kind":"質問・要望","question":"それ以外のことでありましたら、また教えてほしいと求めました。各協会単独での特別な活動というか事業、これが先ほどのふれんどりー事業ということですけれども、それ以外に何かありました説明を求めました。","respondent":"永尾障害者福祉課長","answer":"１２月に障害者週間記念のつどいというのを毎年やっております。それにつきましても、７団体で実行委員会をつくり、協力して行事を行っているところです。","id":"exchange-120"},{"speaker":"木村委員","kind":"質問","question":"この中で８１人ということで、これは延べではないということを先ほどお聞きいたしました。大体１１万円強になるということで、この人数でこの金額は妥当な金額なんでしょうか、お願いします。","respondent":"永尾障害者福祉課長","answer":"移動支援の運営だけではなく、直接的に運営にあたっている経費につきましては、７９４万７,０００円ということになってあります。１時間１,２００円の単価で契約をしているということですので、それほど高い金額ではないというふうに認識しております。","id":"exchange-121"},{"speaker":"木村委員","kind":"質問","question":"その支援員ですか。今現在、何人ぐらいいて、そして今後増やすようなことを聞いたことはありますか。","respondent":"永尾障害者福祉課長","answer":"支援員は現在３７名です。やはり支援される方が多いほうが、合わない方がやはりいらっしゃいますので、区のほうといたしましても増やしていきたいと考えています。","id":"exchange-122"},{"speaker":"木村委員","kind":"質問","question":"ふれんどりー事業の支援の方々から、親御さんやご家族の方々の自分の時間が確保できるということは、大変いいことだと思っています。将来的に知的障害者育成会以外の各団体、また各協会の皆さんも、育成会と同じような計画があるかどうか、説明を求めました。","respondent":"永尾障害者福祉課長","answer":"現在そういうお話はまだ聞いてはおりません。そういうお話があれば、区のほうとしてもいろいろなご相談に乗って、支援していきたいと考えております。","id":"exchange-123"},{"speaker":"木村委員","kind":"質問・要望","question":"もし課長に何らかの障害のあるお子さんがいた場合に、どのようなことを行政側にお願いや要望をするでしょうか。お願いします。","respondent":"永尾障害者福祉課長","answer":"母親の気持ちになりますけれども、どのような障害を持っているとしても、その子のどこかに光る部分があるのではないかと考えています。初めてのことなので、相談の支援というのも必要だと思いますので、情報提供と相談支援というのが一番重要だと考えております。","id":"exchange-124"},{"speaker":"木村委員","kind":"質問","question":"ですから、私たちと何ら変わるところはないと思っています。行政としてこれは絶対にやらなければならないこと、それがありましたら説明を求めました。","respondent":"永尾障害者福祉課長","answer":"障害者の方が生活していく上で、どんなに努力しても乗り越えられないようなハンディがあるとすれば、その部分については行政が補っていかなくてはいけないと考えています。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"しかしながらこの協働事業という趣旨を考えると、いつまで助成していくんですか。もうそろそろ自立してもいいのではないかなと私は思いますが、その考え方をお聞きします。","respondent":"永尾障害者福祉課長、原高齢者福祉課長、吉岡保育課長、安井子育て支援課長","answer":"一概に何％とかということはお答えができないんですけれども、高齢化が進んでいる中、若い人がなかなか入らないという現状があります。… 在宅介護の考え方を変えたのかですけれども、全く今まで変わってございません。特養、あるいはそういったような施設ということの中で実施をしたもの… 障害者団体と幼稚園、個別の対応でいろいろ保護者の方とお話をするというのが基本ですので、特に団体との関連でのということは特にはございません。…","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"ここのところどうも特養、特養というのがあるものですから、やっぱり一番在宅介護というのが基本だと思います。なので、そこは自立しているのであれば、もうそろそろ自立してやっていただければいいのではないかなと思いますが、いかがか尋ねました。","respondent":"安井子育て支援課長","answer":"そういった形で、若い職員も入ってきておりますので、そこら辺で教育体制をしっかりしていくということで進めてまいりたいと考えています。それから子育てメッセですけれども、毎年新たなお子さんが生まれてきていますので、引き続きやってまいりたいと考えています。","id":"exchange-127"},{"speaker":"松澤委員","kind":"質問・要望","question":"８万２,６１１円、これは延べ２万５６人も利用して８万２,６１１円、この内容を教えてほしいと求めました。それと３点目、今もちょっと出ましたけれども、品川児童学園運営費、品川児童学園はどういうことを行っているのかについてお聞きしたいと思います。","respondent":"間部高齢者いきがい課長、原高齢者福祉課長、永尾障害者福祉課長","answer":"私からはいきいきカラオケ広場についてご説明します。かなり人気があるということで、１グループ５人以上ということですけれども、そのような状況だです。 そういった意味では統一した形の記述が本来であろうと認識しています。行政と一緒になりながら高齢者を見守る、そういった仕組みづくりをつくるということ… 品川児童学園ですけれども、児童学園は児童福祉法の第４３条に基づく知的障害児の通園施設で、日常生活の指導や訓練を行っております。…","id":"exchange-128"},{"speaker":"松澤委員","kind":"意見","question":"タクシーだったら２台ですよね。そういうところでも使えないかなという思いがすごくあるんですけれども、その辺を利用者の利便性を考えてどう考えていますかとの意見を述べました。","respondent":"間部高齢者いきがい課長","answer":"ですから、大井町近辺でも探しているんですが、この値段と同じようになかなかできないというお話も伺ってあります。条件が合えばどこでも協力したいという会社とは手を結んでいきたいと考えておりますので、ご紹介いただければと思います。","id":"exchange-129"},{"speaker":"松澤委員","kind":"意見","question":"それはそれで、町場では、週に１回とか、そういうような形で指導していけば可能だと思うんですね。そういうふうに考えていったらいいなと思うんですけれども、課長、いかがでしょうとの意見を述べました。","respondent":"間部高齢者いきがい課長","answer":"当然地域においてこういう場所がたくさんあることが介護予防にもつながりますし、高齢者のいきがいづくりにもつながることだと思っています。私どもも一生懸命新規開拓を目指して、社会貢献という言葉もありますので、そういう観点から協力店を引き続き探してまいりたいと思いま…","id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"これが平成２０年から始まった行事で、最初は２団体、平成２１年１１団体、平成２２年１０団体、今年はもう１３団体ですかね。どうしてやめちゃったのかなということをお聞きしたいのと、平成２２年、今年で終わりなんですね。","respondent":"原高齢者福祉課長","answer":"町会が１つのやり方ではなく、その町会に合わせた取り組み、これが長く継続的に実施されることということで、私どもも思っております。なかなかいい事業であっても継続ができないというお話も多々聞いてありますので、ここについては検討していきたいと思っているところです。","id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"１人か２人どうしても入りたいといっても、定員いっぱいだからといった場合に今、どうしているんですか。その辺、どういうふうにしているかについてお聞きしたいと思います。","respondent":"永尾障害者福祉課長","answer":"知的の障害者が対象ということで、それなりの職員配置が必要になるということなので、保育園のような弾力化というものは難しいかと考えています。試行的に児童デイサービスを受けたり、そのお子さんの状態を見ながら、どちらに移してみていったらいいのかを考えているところです。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"もうそろそろ建て替えの時期に来ていると思うんですが、建て替えのときには、元なぎさ通り、補助１６２号線というんですかね。増やしたりということが可能だと思うんですが、その辺、長期的にいかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"区有施設の有効活用という観点や、さまざまな跡地活用といったところもいろいろ検討しています。今、委員からお話のあった点につきましては、中長期的な視点でもって今後検討していかなければならない課題であると認識しております。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問","question":"複合化、そういう答が出るのは当然わかっていますし、先々のことですから、しっかりと先を見据えてお願いします。できないことないですから、来年の予算をしっかり見ていますので、よろしく区長もお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-134"},{"speaker":"浅野委員","kind":"質問","question":"１２５ページの民生委員経費にも絡みますが、１２８ページの高齢福祉費全般について、難聴についてお伺いしたいと思います。時間があれば１９７ページの特定健康診査など事業費についてお伺いします。","respondent":"原高齢者福祉課長","answer":"区のほうでもこういったところが今後の高齢者人口の増加を踏まえる中で必要ということで判断して、こういった経過で実施してきたものです。それから運営経費の関係ですけれども、こちらのほうは当然介護報酬の支出ですので、介護保険の中で賄うという形になっているところです。","id":"exchange-135"},{"speaker":"浅野委員","kind":"質問","question":"２年前の決算特別委員会で、区外どうですかねというお話を質問させていただいたんですけれども、少しずつ検討しなければならないのかなと。こちらのほうを特別養護老人ホームに検討しているというニュースというんでしょうか、特養は１,０００床ぐらいあったんですかね。","respondent":"原高齢者福祉課長","answer":"施設のほうで対応するという形です。そういったところの中で考えていかなくてはいけないと思っているところです。","id":"exchange-136"},{"speaker":"浅野委員","kind":"質問","question":"特養の件はこれで終わります。高齢者の方を訪問しながら、認知症の傾向を把握するという事業というものはほかにどのようなものがあるのか、教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"認知症のシンポジウム、あるいはそういったさまざまな検証の中に民生委員にも参加をいただくというところで実施しています。この間も荏原文化センターのほうで４００名の参加をいただく中で、その中でつなげていただく、こういったような仕組みの中でお願いをしたところです。","id":"exchange-137"},{"speaker":"浅野委員","kind":"確認","question":"以前にも議会での質問でも取り上げられていますけれども、特に老人性難聴については、高齢者の健診に入れていないと伺っております。どう聞こえているのかという聞こえ方の確認、そういうような形で確認をするとか、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"それから要介護状態になってくるというのは、区としてもそういったところは避けていかなくてはいけないと思っているところです。そういった意味では、委員ご指摘のところは少し研究ということで考えていきたいと思っているところです。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"このような数字を聞きますと、品川区は大丈夫なんですかということを私は痛切に思います。品川区の負担額も増え続けると思いますが、健康福祉事業部にお伺いしたいんですが、この状態をどのようにとらえているのか。","respondent":"木下健康福祉事業部長","answer":"今、社会保障というのを今後とも、今の水準を維持していくのは難しい状況になるだろうと考えています。それがまさに適正な執行ということだと思いますので、そのことに十分留意しながら進めていきたいと考えています。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"ここでちょっと企画のほうにお聞きしたいんですが、企画は全体の予算組みをするわけですね。１５年後を見据えて、今の事態で対応とかそういうことも考えつつあるのかどうか、その辺についてご見解を説明を求めました。","respondent":"榎本企画財政課長","answer":"ほかの区のほうが既に４割を超えてきて、一昨年から４割を超えてきているという状況です。それを日本の経済の状況を見ながら修正をして、その先行き困らないような形で運営していかなければいけないことが一番大事だと感じております。","id":"exchange-140"},{"speaker":"須貝委員","kind":"意見","question":"民生費もこのように膨大な金額、先ほどもほかの委員からありましたが、一般会計の４割を占めてくる。負担が増えてしまうのではないかなという気もするんですが、その辺についてご見解がありましたら、説明を求めました。","respondent":"木下健康福祉事業部長","answer":"ご心配をいただきましたんですけれども、大変スパンが広いのは事実ですけれども、この体制で当分は続けていきたいと考えています。","id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"昨日の答弁のところを確認したいんですけれども、昨日は平塚橋会館のところ、ここを特養ホームへの転用等を検討しているというお話でした。平塚橋はさまざまな角度という検討の一つなのかどうなのかということを確認したいということと、このくらいの土地ですと、聞きたいと思います。","respondent":"久保田行財政改革担当課長","answer":"例えば平塚小学校跡の施設ができるといったこともありますし、地域全体の中であり方検討というところを含めて、検討を進めてきたところです。いつごろ工事かというのは、今後の検討によるものですので、現時点ではそういったことにお答えはできないです。","id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほどの質問の中で、要望では身近なところに要望している声が非常に多いという答弁でありました。具体的にどういうところを今、何カ所くらい当たっているのか、わかったら伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"こういったところを区立として、また八潮については改築創設型ということで、工夫の中で実施してきたところです。基本的にはこちらついては一般財源という形になってありますので、そういう中でトータルで判断していくという形になろうかと思います。","id":"exchange-143"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、これは平塚橋の前、平塚橋はもっと先のほうになりそうですけれども、その前にもつくっていただきたいということを要望したいと思います。２０３０年がピークになる、高原状態になると部長もおっしゃっていたわけですから、聞かせてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"この辺は運営とかいろいろな関係を考えませんと、せっかく入所いただいても、それが安定的に継続的に運営されなければ意味を持ちませんので。２４時間の随時巡回型のホームヘルプの新サービスであるとか…","id":"exchange-144"},{"speaker":"宮崎委員","kind":"確認","question":"小規模については採算がとれるかどうか、運営できるかどうか、そこのところを一つ確認しておきたいと思います。もう一点伺いたいのは、荏原四中について、具体的にいつごろから検討を始めるのかということを聞きたいと思います。","respondent":"原高齢者福祉課長、久保田行財政改革担当課長","answer":"安定的な運営というところを考えませんと、さまざまな角度の中で検討していかなくてはいけないというふうに思っているところです。それから２０３０年のところは確実に高齢者人口… 荏原四中の件についてはしかるべき時期に検討を進めていきたいと考えています。","id":"exchange-145"},{"speaker":"井上委員","kind":"質問・要望","question":"１２９ページの２４時間定期巡回・随時訪問サービス、２２５ページの介護保険特別会計の介護予防事業と１３７ページ、保育園運営費について伺います。その点をお伺いしたいことと、１０１世帯と減少し、この要因を伺います。","respondent":"原高齢者福祉課長","answer":"そういった中で分類をさせていただいているです。介護保険の申請を上手に相談の中でつなげていく中で、介護保険をご利用いただくということも一つの要因かというふうに考えているところです。","id":"exchange-146"},{"speaker":"井上委員","kind":"質問","question":"生活支援というのは欠かせないサービスで、品川区の介護保険の冊子では、日常生活に不安があると感じたときはまず相談くださいとなっています。申請や申し出、相談ができずにサービスから漏れてしまいかねない人たちへ、区はどういう支援体制をとっているんか尋ねました。","respondent":"原高齢者福祉課長","answer":"実施してきております品川第二地域センターの支え愛・ほっとステーションといったところも、さらに身近なところで何か困り事があれば相談ください。これは介護保険も含め、介護保険以外のサービスも含め、そういった形の連携をしていくという仕組みで来ているところです。","id":"exchange-147"},{"speaker":"井上委員","kind":"質問","question":"私は高齢者世帯の方とかひとり暮らしの方とか、とてもこの１０１世帯とか、そういったことはあり得ないのではないかと感覚的に思うんですね。地域包括センターの本来の業務が当初の予定どおりできていると思っているのか、課題があると思われているのか、その辺をお伺いいたします。","respondent":"原高齢者福祉課長","answer":"私ども２０カ所の在宅介護支援センターもこの間、そういったところに上手につなげられる仕組み、先ほどの町会のネットワークもそうです。地域包括支援センターのみがそこになっていくということではなくて、地域全体でそういったところにつなげていくというところを目指していま…","id":"exchange-148"},{"speaker":"井上委員","kind":"質問・要望","question":"大変アイデアとしてはよいことだと思うんですが、これは何かの対案として出てきたものなのかということを１点お伺いしたいと思います。そこで３点伺います。","respondent":"原高齢者福祉課長","answer":"顔の見える対応というところも、郵便局はこのごろは実施してございまして、そういった中でのアイデアで区と共同でそういったことを始めたところです。場合によっては中で倒れているかもしれないということを想像しながら…","id":"exchange-149"},{"speaker":"井上委員","kind":"確認","question":"そうしたら、直接そこに訪問をして確認をするということであるというふうに理解をしたんですが、それでよろしいのかどうかということ。人気があるのかもしれないというふうに考えると、ある程度そういったことも考えるべきではないかなと思うんですが、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"戻ってきたものですけれども、こちらのほうは品川第二にあります支え愛・ほっとステーションのほうに戻ってきて、そこが対応するという形です。ここの部分がどういう声かけの中で１０名なのかというところも踏まえながら…","id":"exchange-150"},{"speaker":"井上委員","kind":"質問・要望","question":"始めたばかりですので、いろいろな検討を加えてよいものにしてほしいと求めました。任意事業費の中で、ニーズに合ったものに再構築してほしいという要望をいたしまして、どのようになられたのかお伺いいたします。","respondent":"原高齢者福祉課長","answer":"参加者につきましては、昨年の中でアンケートを実施し、回答いただいたところです。今年１１月にまた実施をする予定でございまして、その中で要介護１から５の方々に、４,５００件の方にご案内をしています。","id":"exchange-151"},{"speaker":"井上委員","kind":"質問・要望","question":"その意見を反映させて、長く同じような事業をしているんですけれども、ぜひニーズに合ったものに変えていただければというふうに要望しておきます。その中で区はこれを来年度、また他の自治体でこの制度を導入されるところがどのくらいあるというふうに把握をされているのか説明を求めました。","respondent":"原高齢者福祉課長","answer":"そういった意味で、来年の４月以降の対応を前提に、運用体制等々を踏まえて、平成２３年度も検討して事業の展開を始めているところです。他の自治体の状況ですけれども、サービスを全部の自治体が来年の４月に実施できるかというところもいろいろな意見をいただいて。","id":"exchange-152"},{"speaker":"井上委員","kind":"質問・要望","question":"事務事業概要で今年の結果を見ますと、入園と待機児のカウントから漏れた方が３４５人になるんですが、その方たちの年齢別の人数を教えてください。それから、待機児対策として大きく施策を打っていただいたんですけれども、来年に向けて拡大される年齢別定員数を説明を求めました。","respondent":"伊崎待機児童対策担当課長","answer":"来年度４月、６園開園を予定しております。そういったところで、乳児が１８１名、幼児が１９７名、合わせまして３７８名の予定です。","id":"exchange-153"},{"speaker":"井上委員","kind":"確認","question":"そこが対策に盛り込まれているのかどうなのかという確認を一つ、４割ぐらいの保育環境を整えていくという目標値、やっぱり目標値も要るかと思います。私はそういうふうに思うんですが、区としては目標値をお持ちなのか、伺います。","respondent":"伊崎待機児童対策担当課長","answer":"３４５名の意味合いなんですけれども、この方たちはそれぞれ事由があって待機児童に入らなかった方の数です。もちろん入園の申し込みの傾向をあらわしておりますので、特に乳児の対策は必要だと考えております。","id":"exchange-154"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、１２９ページの家具転倒防止対策助成と２２６ページの在宅介護者激励研修事業についてお伺いします。こういうのもぜひ検討してもらいたいということで質問させていただいて、今回、この内容について説明を求めました。","respondent":"間部高齢者いきがい課長、原高齢者福祉課長","answer":"実際１０５件で１６２万円ということで、１件当たりの助成額が１万五、この落差が出たものと認識しております。既に９月末現在で１２０件の申請があるということでございまして… 参加できない方がどうして参加できないのかという参加できない理由をお聞きする中で、またどんなような事業をということも記載させていただきました。そういったところの情報を集めて…","id":"exchange-155"},{"speaker":"武内委員","kind":"提案","question":"平成２２年度の家具転倒防止対策助成のほうは１０１件と書いてあるんですけれども、１０５件なんですか。そうした中で、前にも質問・提案させていただいたんですが、そうした介護の激励の研修会にも来ることができないとの意見を述べました。","respondent":"間部高齢者いきがい課長、原高齢者福祉課長","answer":"私どもも先ほど申し上げましたように、平成２０年度から高齢者と障害者、またその同居世帯ということで対応しています。さらに対応するべきではないかというお声については十分認識をしていますので… それから少し中長期的なところで考えるもの、家族のレスパイトといったところを十分に意識する中で対応していきたいと考えております。そういった意味では、第五期というところに乗せる部分…","id":"exchange-156","title":"議員研修会の内容と所要時間"},{"speaker":"須藤委員","kind":"質問","question":"介護保険、これがここ３年ぐらいでどういう形で推移しているのかということをお聞かせ願いたいのと、２３区が共同で仕組みをつくっていると思います。この繰出金という基準はどういう形でつくって、介護保険、高い安いで見ていった場合にどういう状況になっているのかお知らせください。","respondent":"本城国保医療年金課長、榎本高齢者医療担当課長、原高齢者福祉課長","answer":"委員のご指摘ございましたように、国民健康保険につきましては、２３区統一で保険料についても統一保険料というルールの中でやっております。… 私のほうからは後期高齢者医療特別会計繰出金についてご説明いたします。平成２０年度の関係についてははっきりしておりません。 ２３区平均でいきますと４,１０５円というところでございまして、そういったところが他の自治体の状況です。２３区の中で順番でいきますと…","id":"exchange-157"},{"speaker":"須藤委員","kind":"質問","question":"２３区の中、お話伺ったように、２３区は低い数字に抑えられている。どういう仕組みで、そのあたりで品川区が調整をしたりどうのというのができるのかどうか、説明を求めました。","respondent":"本城国保医療年金課長","answer":"かなり割高な保険料になってしまいますが、ただ現実的には２３区の統一ルールの中で、その２分の１を保険料のもとにするという考え方です。連動して増える仕組みにはなってありますが、高額介護の分について一般会計繰入金がある分…","id":"exchange-158"},{"speaker":"須藤委員","kind":"意見","question":"１９.９１％ですよという高齢者の動態になってきていると、児童センター２５館、１６館という仕組みだけでいいのかねと。地域においてどういう形をしたりということを見ていかなければいけないんだろうと思うんですが、広報することと、それから今の２点との意見を述べました。","respondent":"原高齢者福祉課長、久保田行財政改革担当課長","answer":"そういった中で、我々も介護予防等々を含めて、給付費を少しでも、それの結果、保険料が安くなるような努力をしていきたいと考えています。あるいは保険料の通知の中に普及啓発としていますので、そういった表示の仕方を工夫しながら… 児童センターというものについても、さまざまな角度から検討していかなければならないのかなというところは考えているところです。そうした時期に合わせて…","id":"exchange-159"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、全体を見てきて、施設のあり方というのを考えていただきたい、こんなふうに思います。ありがとう、何かそういう絵をしてあげたいなと思うんですけれども、そういう仕組みは何かつくれないか尋ねました。","respondent":"桑村総務部長","answer":"今、寄附、あるいは無償のボランティアという形でご協力されているんだと思います。一定の検討をさせていただいて、そういう方のご好意、あるいは活動に報いるような方法を考えたいと思います。","id":"exchange-160"},{"speaker":"須藤委員","kind":"質問・要望","question":"どうのこうのといっても、そのように思いますので、何らかの形で検討してほしいと求めました。以上で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-161"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/794205?Template=document&Id=1344#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":117662,"voices":379}},{"id":"h23-20111011-4","meetingId":"h23-c-settlement","date":"2011年10月11日","dateIso":"2011-10-11","committee":"決算特別委員会","time":"午前１０時００分～午後５時２９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を181件整理しています。","topics":[{"id":"topic-01","title":"◯石田（秀）委員長 ただいまより決算特別委員会を開きます。 それでは、平成２２年度品川区一般会計歳入歳出決算","agenda":"◯石田（秀）委員長 ただいまより決算特別委員会を開きます。 それでは、平成２２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"１０月８日、行かれたことある理事者、いらっしゃいますでしょうかね。京浜急行、それから大井競馬場等の交通要所等、それから観光資源の連携を提案しました。","respondent":"米田商業・観光課長","answer":"昨年大河ドラマがございまして、龍馬像の新たな設置というようなこと、いわゆる観光資源としての売り込みというようなことで行ってきたものです。地元商店街の振興施策として龍馬と連携したオブジェの建設等を予定しておりまして…","id":"exchange-001"},{"speaker":"伊藤委員","kind":"提案","question":"随分前の委員会で提案したのは、近隣の皆様方の理解のもとに、やっぱりいろんな具体的なプランを行政は示していく必要があると私は思うんですよ。しかも砲台があるという、具体的な現場の答弁がちょっと寂しい気がしますので、改めてお答えをお願いいたしますとの意見を述べました。","respondent":"米田商業・観光課長","answer":"その中でも砲台跡という記述ができればよかったんですが、そこのところはちょっとできなかったということがあります。あるいは地元商店街等の意見も踏まえ、またよりよい方向性を図っていければというふうに考えてありますので、よろしくお願いいたします。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"一度高知県にお伺いした際に、地元の方々ですね、非常に坂本龍馬に命をかけているぐらいに観光施策をやっていたことを私は見てきました。もう一言、深い希望のあるお話をいただければと思うんですが、いかがか尋ねました。","respondent":"米田商業・観光課長","answer":"そういった意味では、１つの観光資源として今後何かしら施策に反映できればというようなことは考えてあります。今の段階でこの時期までにということは大変難しゅうありますが、常に頭の中に置いて今後の対策等を考えてまいりたいと思います。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"それから、１５０ページのマイガーデンに関連してでありますけれども、これはいろんなことを聞く中で、近く廃止になるということを聞きました。その理由が、東京都のほかの局が合法的に品川区に貸してくれたものについて、その経過が正しいのかどうかということの事実確認をまずお願いします。","respondent":"藤田水とみどりの課長","answer":"その辺の経緯の中で検討した結果、そこの部分については、マイガーデンではない、公園として使用するという形に変更したものです。今後、２７区画については、品川区の土地ですので、そのまま活用していく考えです。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"当たり前のことじゃないですか。あくまで行政の都合でそうなってしまったわけだから、やっぱりそのことについては一定の責任で対処すべきと思うんですが、いかがか尋ねました。","respondent":"藤田水とみどりの課長","answer":"例えば花海道をやっています勝島運河の区画もそういったような形で貸し出しができないかとか、そういったことも検討はしています。今後も有効な土地があれば活用に向けて検討を進めていきたいと考えています。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"となると、もちろん品川区の責任で探してほしいんだけれども、やっぱりそこに東京都を絡ませることはできないんですか。より一体的な方法を考えていくべきと思うんですが、そのことについてのもう１回の答弁をお願いいたします。","respondent":"藤田水とみどりの課長","answer":"東京都の道路用地、この辺の有効活用ということで行ってきてありますので、今後も東京都とはいろいろ話をしながら進めていきたいと考えております。その中で、無償で借りられるということであれば、区としても行っていきたいと考えています。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ぜひ品川区の観点だけではなくて、このマイガーデンに関連しては東京都も関連した話ですから、そのことを踏まえた上での対応をお願いをしておきます。がん検診については、いろんなところで要望を受けますけれども、いわゆるハイリスク検診というものを導入してくださいという話を随分いただきます。","respondent":"小川健康課長","answer":"このために、区といたしましても、受診者にとっては負担が少なくなるだろうという見解は持ってあります。こちらにつきましては、医師会とも勉強会を重ねながら意見交換を重ねているところです。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、啓蒙につなげていくべきと考えますが、いかがでしょうか。まとめて答弁をお願いいたします。","respondent":"小川健康課長","answer":"検査をして終わるものではなく、その後の啓発、ＰＲ等も必要だと考えています。ＰＲについては、歯科健診だけでなく、二十歳の唾液検査の新しい健診のご提案についてはもう少し研究をさせていただきたいと思います。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"これはやはり品川区での接種については、こういう事例も十分踏まえた上で慎重に対処すべきと考えますが、いかがでしょうか。答弁をお願いいたします。","respondent":"伊津野保健予防課長","answer":"ただ、あくまで１００％になりませんので、このワクチンだけでは子宮頸がんの予防には完璧ではありません。ワクチンの危険性につきましても、先ほど１例死亡例がありましたが、専門家の検討の会議の結果では特に因果関係はないという結論になっております。","id":"exchange-009"},{"speaker":"鶴委員","kind":"質問","question":"私のほうからは成果報告書の１４５ページ、母子健康診査費、それから１４６ページの母子保健指導事業費についてお尋ねをいたします。いわゆる妊娠週数別の届出内訳があれば、平成２２年度で結構ですので、説明を求めました。","respondent":"小川健康課長、矢野品川保健センター所長","answer":"母子手帳の交付の状況ですが、外国籍につきましては、申しわけございません、把握はしてございません。届出のタイミングですが、妊娠がおわかりになった時点で届出をしていただく、判明した時点でしていただくということになってありま… 妊娠届出状況ですが、母子保健事業報告という都の年報があります。総届出数３,６４８件中、３,４０７件で、かなりの方が１１週までに届け出ていただいているという状況です。","id":"exchange-010"},{"speaker":"鶴委員","kind":"確認","question":"確認です。ちなみに、外国籍の方に交付する母子健康手帳、現在何カ国語による手帳が用意されているのか、おわかりになりますか尋ねました。","respondent":"小川健康課長","answer":"一応８カ国語用意しています。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"８カ国語ですね。ちなみにその言語、わかれば教えていただけますか。","respondent":"小川健康課長","answer":"今ちょっと手元にございませんので、後でご報告します。申しわけございません。","id":"exchange-012"},{"speaker":"鶴委員","kind":"提案","question":"これは妊娠届出時ということですかね、それから棄児、監護等の５項目となっております。先ほどほとんどの方が１１週までというお話ありましたけれども、こうした妊娠週数別の把握を提案いたしますが、いかがか尋ねました。","respondent":"矢野品川保健センター所長","answer":"東京都の母子保健事業報告に載っておりますので、資料というのはあります。今後とも、広報あるいはホームページ等で速やかに妊娠届をしてくださいという周知には努めてまいりたいと思います。","id":"exchange-013"},{"speaker":"鶴委員","kind":"提案","question":"この参加者の声をお聞きすると、母子健康手帳に超音波検査でプリントアウトされたエコー写真、これを張る場所が欲しいという要望がございました。この見開きのマイベイビーのページを増やす形で検討はできないか、提案をいたしますが、いかがか尋ねました。","respondent":"矢野品川保健センター所長、小川健康課長","answer":"超音波の写真を張る部分については、今後の検討課題とさせていただきたいんですが、これには折々の写真を張りましょうという欄があります。よろしくお願いします。 先ほど答弁漏れがございました外国語の母子手帳の８カ国語ですが、英語、中国語、タイ語、スペイン語、インドネシア語、ポルトガル語、タガログ語、ハングル語の８カ国語です。","id":"exchange-014"},{"speaker":"鶴委員","kind":"質問","question":"副教材というか、副読本という言い方をするんでしょうかね、ご答弁いただいたもの。次に、妊婦・産婦歯科健診についてお尋ねをします。","respondent":"小川健康課長","answer":"ご指摘のように、歯科受診率につきましては、極端に受診者数が下がります。こちらとしましては、歯科健診の重要性を訴えるために、あらゆる場面で歯科健診のＰＲ等もさせていただいているところです。","id":"exchange-015"},{"speaker":"鶴委員","kind":"確認","question":"もう一度確認の意味で、または経産婦の方も、こうした受診率が向上するような工夫が必要かと考えます。今ちらっとさらっとご答弁いただきましたけれども、もうちょっと具体的な啓発のお考えをお聞きしたいなと思いますので、ご答弁をお願いします。","respondent":"矢野品川保健センター所長","answer":"１コマ、歯科医師会の医師にお願いしまして、歯科衛生士が指導しております。その数につきましては、１,２３９ということで上げてあります。","id":"exchange-016"},{"speaker":"鶴委員","kind":"質問・要望","question":"次に、母子保健指導事業費の健やか親子学習についてお尋ねをします。お尋ねしますが、平日開催が多い保健センターで２カ月に１回で各１２組の開催となっておりますが、この数字でよろしいか尋ねました。","respondent":"矢野品川保健センター所長","answer":"それでよろしいです。","id":"exchange-017"},{"speaker":"鶴委員","kind":"確認","question":"あくまで確認でした。ホームページから確認をさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"鶴委員","kind":"質問・要望","question":"答弁できないですね。なので、今後もこうした両親学級等へのパートナーの方の参加向上にもしっかりと啓発をしていただきたい、このようにお願いして質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"向委員","kind":"質問","question":"それから１４３ページの結核健康診断について、１４４ページの乳がん検診についてと、以上をお尋ねしたいと思います。ページ数が１４９と１５２ページで別々に分かれていて、それぞれカラス対策事業、この分けて決算に載っている理由を説明を求めました。","respondent":"野呂瀬環境課長、太田品川区清掃事務所長","answer":"カラス対策事業のことです。事項別明細書でいうと１４９ページ、こちらがカラス対策事業ということになっております。 １４９ページのカラスの部分というのは、カラスの巣を除去するとか、そういう一般的な対策を実施しています。１５２ページのカラス対策費というのは、ごみの収集を以前資源ステーションで…","id":"exchange-020"},{"speaker":"向委員","kind":"質問","question":"わかりました。カラスは大変賢い動物というのは皆さんよくご存じだと思いますが、このネットの貸し出しは有料ですか、無料か尋ねました。","respondent":"太田品川区清掃事務所長","answer":"無料で貸し出しをしております。そして、管理についても、皆さんでお願いをしています。","id":"exchange-021"},{"speaker":"向委員","kind":"質問","question":"では、続けてカラスに関してなんですが、品川区では大体家庭ごみの回収時間、回収に要する時間というのは大体朝何時から終わるのが何時までで、大体何時間ぐらいかかるんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"一般的に８時に事務所を出てまいります。大体終わりますのが２時半から３時半の間、４回、５回というふうに申し上げましたので、時間帯になると２時半から３時半ぐらいに大体終わるです。","id":"exchange-022"},{"speaker":"向委員","kind":"質問","question":"意外とさくさく終わるので、こうやって続けていくのも１つだと思うんですが、根本的に変えるというのもあるのかなと思ってちょっとお話ししました。このあたりの新しい対策を考えるというか、そういったそのあたりのお考えっていかがか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"これも平成１８年ぐらいですけれども、商店街でモデル実施しながら、現在リボンとかで販売をしています。夜間収集をしているというところを承知はしていますが、やはり何といっても費用対効果というものを考えると、現在のところ実施する考えはないです。","id":"exchange-023"},{"speaker":"向委員","kind":"質問","question":"１,０００万円ぐらい決算に上っていますけれども、これはリサイクルショップの運営費の大体どのぐらい割合を占めているんでしょうか。１,０００万円が運営費の大体半分以上これで占めているとか、どのあたり、どのくらいになるのかをお教えください。","respondent":"太田品川区清掃事務所長","answer":"区が直接設置をして実施をしていたところですけれども、区の条例を設置してやっていた、平成１８年度から補助をしているという形です。ただ、私どもとしての補助については、それぞれの目的をつけまして補助をさせていただいているです。","id":"exchange-024"},{"speaker":"向委員","kind":"質問","question":"いろんなところでご自身で経営されているリサイクルショップもかなり増えてきていますけれども、いつまでこの支援は続けていかれるご予定ですか。近いところでは大震災ありましたけれども、そういったところに寄附金に使うとか、そういったことというのは今も実際されているのか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"民間のノウハウを活用しながら民間で自主的にやっていただけるような組織がないかということで検討をしていたところ、環境情報活動センター。安定的な収入を図っていただくということを今目指しておりますので、さらに当面の間、補助をしていく必要があると考えているところです。","id":"exchange-025"},{"speaker":"向委員","kind":"質問","question":"では、次に結核検査のことなんですが、１４３ページ、区内でも毎年１００人ほど結核患者の方出ていらっしゃると思います。３０代とか４０代、このあたりの年齢設定とかについてお話をお伺いできればと思うんですが、お願いします。","respondent":"伊津野保健予防課長","answer":"４０歳から６４歳におきましては、平成１８年度で廃止しております。３０代、４０代についての結核も最近になってまた少し増えておりますが、結核検診としましては６５歳以上の対象者を実施しています。","id":"exchange-026"},{"speaker":"向委員","kind":"質問・要望","question":"要望なんですけれども、平成１８年に廃止になった若い方への検診も、ご検討ほしいと求めました。いろんな懸念もあるかと思うんですが、３４歳からに設定している理由だけちょっと教えていただけませんか。","respondent":"小川健康課長","answer":"乳がん検診ですが、あくまでも国のガイドラインとしましては４０歳以上ということになってあります。とはいえ、品川区ではもう少し早めということで、独自に３４歳以上ということで始めたものです。","id":"exchange-027"},{"speaker":"向委員","kind":"質問・要望","question":"１４６ページの母子栄養の支給ですかね、１４６ページの中ほどにあります母子栄養補給のところで、これは何の栄養を補給するためにされてきたのか。ことしはもう事業廃止になっていると伺っているんですけれども、決算では２４０円ですかね、あわせてご答弁お願いします。","respondent":"小川健康課長","answer":"母子栄養補給事業ですが、こちらの目的は、生活保護世帯および低所得世帯に対しての栄養摂取の援助という目的で始めたものです。平成２２年度につきましても、事務経費のみで、実際には支給は行われてございません。","id":"exchange-028"},{"speaker":"向委員","kind":"質問","question":"妊婦の方への支給というわけではなくて、乳児用の粉ミルクということであったんでしょうか。私がお尋ねしたいのが妊婦さん用なので、そのあたりお願いします。","respondent":"小川健康課長","answer":"乳児用粉ミルクとともに妊産婦用粉ミルクとあわせましての支給をさせていただいてきたところですが、一応平成２２年度で事業終了ということになりました。","id":"exchange-029"},{"speaker":"向委員","kind":"質問","question":"これは栄養というのは全面的な補助でしょうか。私が先ほどお尋ねしたカルシウムに特化してとか、何か鉄分とか、そのあたりを詳しくお答えをお願いします。","respondent":"矢野品川保健センター所長","answer":"この母子栄養食品の支給ですが、カルシウムに特化したものではございませんで、全体の栄養というところで低所得者層に対する補助ということで続けていたものです。","id":"exchange-030"},{"speaker":"向委員","kind":"質問・要望","question":"妊娠中毒症だったりとか、さまざまな経済的な理由で妊婦さんへの補助というのは引き続き別な形でも続けていってほしいと求めました。これは要望になりますが、以上で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"東京都や２３区の平均や自家風呂率、まず伺いたいのは、そこを伺いたいと思います。具体的に南品川一丁目から六丁目の高齢者にとって、東品川シルバーセンターに歩いて通える距離だと思うのか、伺いたいと思います。","respondent":"小川健康課長","answer":"まだまだ２３区内では平均レベルにあることは間違いございませんが、ご指摘の特定の大井地区等を中心に、区としても認識をしています。これについてどのようにしていくかですが、今後はやはり公衆浴場組合とともに考えていきたいと考えております。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"まず具体的にこの地域の方々のお風呂をどう確保していくのか、その具体策を今現在どう考えているのか、伺いたいと思います。２３区、ここをどう考えているのか、改めて伺います。","respondent":"小川健康課長","answer":"具体的な確保支援策ですが、こちらにつきましては、やはり区独自でというよりも、むしろ公衆浴場組合とともに考えていきたいと考えております。それに関しお互いに模索をしながら、区が支援できることがあればということで…","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこをどう考えているのか伺いたいと思います。こうした足を確保する、こうしたことを考えていく必要があると思うんですけれども、いかがか尋ねました。","respondent":"小川健康課長","answer":"繰り返しのご答弁になりますが、区独自の施策というよりも、今はやはり公衆浴場組合とともにいろいろな方策を考えていきたいということが今の区としてのスタンスです。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて支援を強化していく、そうした今日的な役割があると思うんですけれども、いかがでしょうか。とりわけ浴場組合の方が話していたのは、煙突が倒れるというのは致命的だと、そう危機感を話しておりましたが、いかがか尋ねました。","respondent":"小川健康課長","answer":"区としましても、できるだけ今の公衆浴場の数を維持していきたいというふうには考えてあります。こちらを抱き合わせで上手に使っていただいて、存続に向けて浴場については支援をしていきたいと考えています。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に伺いますけれども、東京都は補助対象４分の１で１施設７,５００万円、品川区は補助対象２０分の１で１施設１,０００万円。煙突も含めて耐震化支援を進めてほしいと思いますけれども、いかがか尋ねました。","respondent":"小川健康課長","answer":"それぞれ銭湯によっても個別にいろいろな状況を抱えていると考えられますので、先々見直すことまでを否定しているわけではございません。耐震改修、それから耐震診断についても都の制度がありますので、こちらについて区として改めてということは今は考えてございません。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"５月５日に、子どもの日には小学生以下の無料入浴でも１,０５８人の利用があったと伺いました。ぜひ品川区も支援してほしいということですけれども、存続や振興を強化してほしいと求めましたが、いかがか尋ねました。","respondent":"小川健康課長、米田商業・観光課長","answer":"こちらの契約につきましては、これからも公衆浴場組合とお話し合いを続けていく中でいろいろ考えてまいりたいと思います。友～湯銭湯スタンプラリーですが、都の補助制度があると聞いてありますので… 公衆浴場商業協同組合事業助成補助金というのがあります。そちらの中で、先ほどご指摘のありました、菖蒲湯および友～湯銭湯スタンプラリーにつきましては、一定金額の助成を行っているところです。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"その中で持ち出しが増えているという実情がありますので、ぜひ実態に即して支援を強化していただきたいと改めてお願いしたいと思います。ぜひここを強くお願いをしたいと思いますが、いかがか尋ねました。","respondent":"小川健康課長","answer":"区としましても、今の浴場の数を維持していきたいと考えています。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"初めに健康づくりについて伺いますけれども、その中で、認証制度の廃止ということも意見の中に出たというのを伺っているんですけれども。区がそのお手伝いをすることはいいんですけれども、その辺についていかがか尋ねました。","respondent":"小川健康課長","answer":"ご指摘のとおり、外部評価でも厳しいご指摘をいただいておりまして、現在は廃止を含めた形で検討を開始しています。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問・要望","question":"廃止ということで安心をしましたので、廃止してください。そういう考えでこれからの行政も進めていただきたいということを思いつつ、改めて区内の景気状況、特に商店街の景気動向についてお伺いします。","respondent":"米田商業・観光課長","answer":"先日、今年度第１四半期の景況調査が発表されました。特に商業者の景況ですが、向上の兆しは見られるが、相変わらず厳しい状況が続いているというようなことでの報告をいただいております。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問・要望","question":"小規模商店街の助成についての効果を教えていただきたいんですけど、前々回にやった山王商店街、やりましたよね。あの効果も含めて答弁していただけますか。","respondent":"米田商業・観光課長","answer":"貯蓄に回らず、近隣等の商店街にある一定の期間でお金が落ちるというようなことで経済効果が見込めると考えています。山王銀座商店街ということで、こちらは平成２１年度になりますが、実施をさせていただきました。","id":"exchange-041"},{"speaker":"藤原委員","kind":"質問","question":"課長、区の行政の仕事なのに、内容聞いているんじゃないじゃないですか。こういう施策をやってどういう効果が出たんですかって聞いているのに、３分も使って内容説明されてどうするんですか、１０分しかないのに。","respondent":"米田商業・観光課長、山田副区長","answer":"その中で、集客効果が見込めた等のご意見も踏まえまして、今後とも小規模商店街の支援、行ってまいりたいというようなことで考えてあります。それについて一定の集客等の効果があったというふうに考えてあります。 品川区から、区民の皆様方にとっては必要な商店街なんだというところを認識いたしまして、これを通じて役員の方が出てきて。それぞれ打ち合わせをしていく中で、いわゆる歯抜けになっていかないような部分も含めて生かされていると…","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問・要望","question":"３億円と来ているんですけれども、この効果がある施策に対していつも伺うと、緊急経済対策。伸ばすというのは、額ですから、５億円、５億円という要望をしますが、それについて、もう内容はいいですから、明確な答弁をほしいと求めました。","respondent":"米田商業・観光課長","answer":"この間の区内経済状況、あわせかんがみまして、額等も含めて今後検討してまいりたいと、このように考えてあります。","id":"exchange-043"},{"speaker":"阿久津委員","kind":"確認","question":"１４４ページ、３番目が１４９ページ、先ほどもありましたカラス対策事業についてお伺いいたします。確認したところ、毎号これは掲載されていますが、このほかに診療日程や医療機関の周知というのをどのように行われていらっしゃるんか尋ねました。","respondent":"小川健康課長","answer":"それから、あと、特にお子さんをお持ちの親御さんのお手元に届くようになっております小児救急医療のご案内というようなご案内冊子もあります。そういったところで、あらゆる手段を使ってＰＲをさせていただいているところです。","id":"exchange-044"},{"speaker":"阿久津委員","kind":"質問","question":"＃８０００番というダイアルが案内されていますが、この２つのダイアルについて、簡単に内容とその違いについて教えていただけますか尋ねました。","respondent":"小川健康課長","answer":"ともに東京都の事業です。＃７１１９が２４時間対応ということになっておりまして、＃８０００は、そういった場面にご相談いただけるような形になっているものです。","id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問・要望","question":"何人かからご要望があったんですけれども、あと、簡単な一言の説明が書いてあるようなマグネットシールつくってくれないかと。ぜひこういうのをつくっていただきたいというご要望があったんですが、要望も含めて、ご見解を伺いたいと思います。","respondent":"小川健康課長","answer":"先ほどの＃８０００ですが、失礼いたしました、国がやっておりますが、都で運営しているという内容です。今現在でも子育てガイドといって、そうしたマグネットシール等のご提案につきましては、今後の研究課題とします。","id":"exchange-046"},{"speaker":"阿久津委員","kind":"質問・要望","question":"目の前に置いてほしいと、そういうご要望でしたので、どうぞよろしくお願いします。１４４ページの猫の不妊・去勢手術についてお伺いをします。","respondent":"工藤生活衛生課長","answer":"猫の不妊・去勢手術費の助成の件につきましてのお尋ねです。飼い猫に関しては１９０頭、また飼い主のいない猫につきましては２００頭、合計３９０頭という形に予算書上なってあります。","id":"exchange-047"},{"speaker":"阿久津委員","kind":"質問","question":"うちの会派からもいろいろ質問しまして、平成２２年度に関しては、この予定頭数というのはあったんでしょうか。飼い猫と飼い主のいない猫との間での予算の流用というのはあったんか尋ねました。","respondent":"工藤生活衛生課長","answer":"平成２２年度の予定頭数ですけれども、平成２２年度は飼い猫に関しては１９０頭、飼い主のいない猫につきましては２００頭です。平成２２年度のどの時期に予定頭数に達したかということにつきましては、８月に予定頭数を達したということで、そちらを流用して対応したところです。","id":"exchange-048"},{"speaker":"阿久津委員","kind":"質問・要望","question":"質問させていただきたいのが、品川区には地域猫は多いのか、少ないかというデータがあるのか。一生懸命不幸な猫を増やさないとか、助成をもう少し頑張って増やしていただきたいという思いがあるんですが、その予定はあるんか尋ねました。","respondent":"工藤生活衛生課長","answer":"それに当てこみますと、品川区、１９万世帯ありますので、１万９,０００匹ぐらい飼われている、もしくは飼い主のいない猫がいるという状況です。平成２３年度にいわゆる頭数を倍にして対応しておりまして、そちらの状況を見まして、いろいろと研究していきたいと考えています。","id":"exchange-049"},{"speaker":"阿久津委員","kind":"質問","question":"私もいろいろお話を伺う中で、何とかしてほしいと、よく受けます。この７５０件の相談数というのと２３９件の撤去というのは、平成２２年度１年間の数字ということでいいんか尋ねました。","respondent":"野呂瀬環境課長","answer":"７５０件の相談というのは、平成２２年度１年間の数字です。そのうち２３９件、巣の撤去等を行ったです。","id":"exchange-050"},{"speaker":"阿久津委員","kind":"質問","question":"もしやっているのであれば、今までとどのように異なるのか、教えてください。こういうのは区報とかケーブルテレビなどで皆さんに周知をされているんか尋ねました。","respondent":"野呂瀬環境課長","answer":"区民の方への周知は、主にカラスというのは４月から６月に繁殖期ですので、４月の時点でホームページまたは広報しながわを通じてＰＲをしています。それと、その中でも、カラス対策についての一般的な相談というのをホームページに掲載しています。","id":"exchange-051"},{"speaker":"阿久津委員","kind":"質問・要望","question":"わざわざこの決算書に記載をしてあるということなので、総合窓口があるということで、ホームページ等、また区民の方にご周知をしていただきたい。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"沢田委員","kind":"質問・要望","question":"成果報告書の１４２ページ、それから１４７ページの不妊治療相談・助成事業、１５０ページの緑化活動支援事業についてお伺いいたします。歯科医師会３９６万円余、各団体の要望の積み上げを公的要素の強い事業に対して結果としてこういう額になっているのか、説明を求めました。","respondent":"小川健康課長","answer":"むしろ個々別々に、それぞれ公的事業を行っていただいておりますので、それぞれに対する助成を行っているものです。必ず毎年度計画を出していただきまして、それに基づきまして適正な金額と判断し、助成をしているものです。","id":"exchange-053"},{"speaker":"沢田委員","kind":"質問","question":"高齢者の方が増えていて、自分で注射を行う方が大変増えているということで、注射針の回収が大変だというお話をお伺いしました。品川区でもそういった清掃作業員の方が注射針が捨てられていてけがをしたということはあるのか尋ねました。","respondent":"太田品川区清掃事務所長、小川健康課長","answer":"委員ご指摘のとおり、実は東京都が２３区、全区的に回収事業を独自に実施をいたしました。それから、今後ですが、清掃事務所の管轄でいえば、そういう回収ボックスを用意するというような考えは特にございません。 薬剤師会から区の支援の要請がございまして、こちらの助成金を平成２０年、平成２１年とそれぞれ１０万円ずつ上乗せをしたという経緯があります。現在はそれぞれの薬剤師会、品川…","id":"exchange-054"},{"speaker":"沢田委員","kind":"質問","question":"特に東京都のほうから廃止された初期事業ということで、その後は各区でそれなりの対応をとってくれというお話なんか尋ねました。","respondent":"小川健康課長","answer":"特に東京都からの引き継ぎのようなものはなかったんですけれども、区の独自の判断として、助成金という形で上乗せをさせていただいたというものです。","id":"exchange-055"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういった事業があるということだったのでお伺いさせていただきました。今後の見通しについてお伺いさせてほしいと求めました。","respondent":"小川健康課長","answer":"不妊治療の医療費の助成ですが、区独自に一般不妊治療の部分での助成をさせていただいているところです。思いのほか伸びている状況ではありますが、こちらにつきましてはしっかりとやっていきたいと考えています。","id":"exchange-056"},{"speaker":"沢田委員","kind":"質問","question":"高額であるですけれども、どうしても共働きの世帯が多い東京都で夫婦合算で７３０万円以下という所得は低過ぎるんじゃないかなとも思います。今後の特定不妊治療に対する区としての、厳しいかもしれないですけれども、助成等は考えられるんか尋ねました。","respondent":"小川健康課長","answer":"あわせまして、区独自で特定不妊治療というのは考えてございません。一般につきましても、推移も見はからって考えていきます。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"お時間がございましたら、１５５ページのしながわの一番店発見プロジェクトについてお尋ねしていきたいと思います。資源持ち去り防止対策費ですが、どのような対策か尋ねました。","respondent":"太田品川区清掃事務所長","answer":"それから、平成２１年度は１名非常勤職員を採用して実施をしてまいりましたけれども、平成２２年度３名に体制を強化した。その２名分の経費約７００万円弱が増えたです。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"バイクでは約３倍と指導件数が増えておりますけれども、その点をどのようにお考えかということと、それをどのようにお考えかとお伺いしたいです。","respondent":"太田品川区清掃事務所長","answer":"それから、パトロール隊の実施の仕方もいろいろ工夫を重ねたところ、今年度は月約４０件ぐらいの指導件数に落ちついてきている。やはり場所、住所等がわかったときの後の仕返しが怖いというようなこともありまして、現時点ではやはり難しいのではないかと考えております。","id":"exchange-059"},{"speaker":"吉田委員","kind":"意見","question":"では、続きまして、すくすく赤ちゃん訪問事業についてお尋ねしていきます。どのような事業かということと何を目的にしていらっしゃるのか、お教えくださいとの意見を述べました。","respondent":"矢野品川保健センター所長","answer":"すくすく赤ちゃん訪問事業ですが、これは平成１９年度より従来この保健所で行ってまいりました新生児訪問指導に加えて、訪問しております。目的ですが、要保護児童を早期に発見する、あるいは育児不安を解消して育児の孤立化を解消するです。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問","question":"全戸訪問ということですけれども、何％ぐらいできているかということと、虐待防止なんかのためでもあるんじゃないかなと思いますけれども、その辺の見解をお願いします。","respondent":"矢野品川保健センター所長","answer":"それが始まる前の平成１８年度は４７％ぐらいでしたが、平成１９年度からは７０％以上、出生数に対する訪問率は７０％以上を維持しております。虐待防止のことに関しましては、区のこども家庭あんしんねっと協議会に心配な事例は上げて協力して対応しております。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"全戸訪問１００％にするのはなかなか難しいと思われますけれども、他区では突然訪問ということ、突撃訪問ですか、行っている区もあるそうですけれども、そのことをどのように思われるかということと、虐待の疑いが見られた場合の、そういうことが事例があったかということもお伺いしたいです。","respondent":"矢野品川保健センター所長","answer":"子育て支援課や戸籍住民課にもすくすく赤ちゃん訪問の周知のチラシなども置かせていただいて、これの把握率を高めているところです。乳児健診が９６％ぐらいの受診率なので、そこで把握するようにはしておりますが、今後とも訪問率を上げる方策を検討していこうと考えております。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"１人で悩ませないためにも、それを目指して頑張っていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"高橋委員","kind":"質問","question":"１４６ページの健康センターについて、それから１５３ページの観光アクションプラン推進事業についてお尋ねします。平成２０年度までと平成２１年度までとで大きく変わったんですが、運営主体の歳出歳入の利益というんでしょうか、あと区への還元。","respondent":"小川健康課長","answer":"そういった関係で、平成２１年度に関しても還元金をいただきました。平成２２年度に関しても、さらに利用料金の収入のアップがありましたので、還元金が増えたというようなシステムになってあります。","id":"exchange-064"},{"speaker":"高橋委員","kind":"質問","question":"で、５,６００万円支出が減っているという形になるわけですね。これは大体１,５００万円を超えて１,０００万円ぐらいですので、２５％ぐらいですか、それは毎年毎年変動するものなんか尋ねました。","respondent":"小川健康課長","answer":"還元金のパーセンテージにつきましては、平成２２年度は２０％、平成２１年度も２０％でありました。年度ごとに協議をして、パーセンテージを決めていくというものです。","id":"exchange-065"},{"speaker":"高橋委員","kind":"質問","question":"ここの指定管理者である住友不動産エスフォルタでしょうか、ここはほかの自治体の委託も幾つかされているんでしょうか。そしてその使用料金の形態は品川区の委託と同じような形になっているんか尋ねました。","respondent":"小川健康課長","answer":"こちらの住友不動産エスフォルタ・ＮＴＴファシリティーズ共同事業体ですが、他の自治体でも一部やっているということは伺っておりますが、具体的なやり方についてはこちらのほうは把握してはございません。","id":"exchange-066"},{"speaker":"高橋委員","kind":"質問","question":"ほかの自治体ではもしかしたら市以外は高くなっていて、市外とか区外の方が高くなっていて、市の方が安くなっている可能性もあるわけですよね。そういうことの情報を得ないでおいて、品川区は住友不動産エスフォルタと指定管理者の契約を結んだんか尋ねました。","respondent":"小川健康課長","answer":"歳入のときにもご答弁申し上げましたとおり、指定管理者制度を導入する前の委託の方法でやっていたときからのワンコインという考え方がございまして、それに基づいて引き続きお気軽にワンコインということでやっているものです。","id":"exchange-067"},{"speaker":"高橋委員","kind":"質問","question":"お気軽に５００円なり４００円で使っていただいて、区外の方が使用する際には何らかのプラスアルファがあってしかるべきだと思います。ですから、５００円ということですかからどうかわかりませんが、それぞれの利用の人数の違いというのはおわかりになるか尋ねました。","respondent":"小川健康課長","answer":"品川健康センターでは５００円、荏原では４００円ということでございまして、延べ利用数でいきますと、品川は年間６万５,１５０名、荏原では年間延べ２万４,６１８名の利用をいただいているところです。","id":"exchange-068"},{"speaker":"高橋委員","kind":"質問","question":"内訳をお聞きしたんですが、名前や住所、そこで調べてほしいと思います。それなのになぜこういう金額の差があるのかということなんですが、ホールは書いてあるんですが、それとの関係はどのようになっているんか尋ねました。","respondent":"小川健康課長","answer":"ホール、会議室等につきましては、一般貸し出し施設ということで、ご指摘のとおり、区民と区民外の利用の料金の差をつけてあります。受付窓口等で区民か区民外かということをそれぞれ選別するということについてもなかなか難しい課題があろうかなというふうには考えてあります。","id":"exchange-069"},{"speaker":"金野委員","kind":"質問","question":"国立感染症研究所感染症情報センターですか、このまとめによりますと、現状これはどのような状況で品川区は認識をしておりますでしょうか。品川区で現にこのＲＳウイルスの発生は、発症はあるのでしょうか、現状を説明を求めました。","respondent":"伊津野保健予防課長","answer":"国の報告ならびに都の報告では、前年に比べましてかなり早い立ち上がりになっております。ただ、区内におきましては、それほど流行という感じでは今のところ至っていない段階であります。","id":"exchange-070"},{"speaker":"金野委員","kind":"質問","question":"それほどということは、ごめんなさい、細かくて恐縮なんですが、数名発症しているということですね。流行はないけれども、多少発症があるということか尋ねました。","respondent":"伊津野保健予防課長","answer":"直近のデータで、区内、小児科定点８カ所ありますが、その中で３件の報告があります。","id":"exchange-071"},{"speaker":"金野委員","kind":"質問","question":"品川区でも３件と。どのように本区としては対応していこうと、今の時点でお考えがありましたら、説明を求めました。","respondent":"伊津野保健予防課長","answer":"特効薬についても特にありませんので、１つには、症状が出た場合に早めにかかって対処してもらう。広報に努めて、そういうところで、特に６カ月未満の乳幼児にかからないような方法を考えていきたいと思います。","id":"exchange-072"},{"speaker":"金野委員","kind":"質問","question":"今の段階ではそれが主だとは思いますが、ぜひこの対応をよろしくお願いしたいと思います。何か報道によりますと、中学生の間で流行し始めているということですが、こちらのことに関してはいかがか尋ねました。","respondent":"伊津野保健予防課長","answer":"特に昔はオリンピックが開催のときの４年に１回流行すると言われていましたが、発生が増えている状況が確認されております。直近のここ３週ほどで前年に比べてもかなり大きな流行となっておりますので、品川区としましても今後の流行を見守っていきたいと思います。","id":"exchange-073"},{"speaker":"金野委員","kind":"質問・要望","question":"その上で、医師、お医者さんのところに的確に診断に当たる、早期発見、早期治療というようなことにつながるように配慮していただきたい。お話をされているのか、ぜひその点もお母様方にそうした情報も提供しながら、このウイルス感染症に対処していただくよう。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１９８１年から死因の第１位ががんということで、これらが出されてから具体的にがん対策の取り組みというのはどんなことが行われてきたんでしょうか。その中身についてと、それからまた現状での課題についてお聞かせほしいと求めました。","respondent":"小川健康課長","answer":"区としてそれに基づいて、例えば国が科学的に推奨するがん検診に関しましては確実に実施をしているです。その結果、平成２２年度におきましては、がんの種別ごとに差はありますが、全体的に受診率が向上したという実績があります。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それをどう具体化していくかという点で、がん予防の対策の計画をつくるべきではないかなと思うんですが、その点に関してはいかがでしょうか。がん検診の現状がどうなっているかということで、前立腺がん、この６項目についての検診の受診率のパーセンテージも教えてほしいと求めました。","respondent":"小川健康課長","answer":"国が定める５０％という数値目標ですが、区として具体的に数字を定めておるものではございませんが、少しでもそれに向けるべく努力をしているです。２５.６％、肺がんについては５.８％、大腸がんについては２２％という状況です。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それに対してどうやって近づけていくかというところが求められていると思うんですが、お聞かせほしいと求めました。そのところで、それもぜひ健診と同じように医療機関でも受けられるようにということでぜひしていただきたいと思うんですが、いかがか尋ねました。","respondent":"小川健康課長","answer":"このような機会を利用してがん検診の受診率を伸ばすということを区としては考えてあります。こちらについては、医師会と今後話し合う中で、いろいろさまざまな方策を考えてみたいと思っておるところです。","id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５.８％という、本来であればもっともっと高めることができる検診ではないかと思いますので、ぜひ前向きにご検討よろしくお願いいたします。ぜひともこれは５００円を無料にということで、ご検討いただきたいと思うんですが、いかがか尋ねました。","respondent":"小川健康課長","answer":"特に、国保の同時受診としては確かに有効ですが、無料だからといって必ずしも受診率が上がるということは必ずしも区としては考えてございません。受ける方は、どんなに高くても必要に応じて受けるということもありますので…","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要望しておきます。高校生のお母さんからぜひ高校生も対象にして助成をしてほしいという要望をいただきまして、高校３年生から１９歳まで、いかがか尋ねました。","respondent":"伊津野保健予防課長","answer":"品川区では、昨年は中１から中３、さらに二十歳の年齢を押さえております。この二十歳の年齢を押さえることによって、現在高校生の方も二十歳になったときには受けられるという体制でやっていきたいと考えています。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは感染をする前に予防接種をするということに効果があると思いますので、そういう点で言えば、高校生のところが本当に必要な年齢だと思いますので、ぜひとも今後検討との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"大倉委員","kind":"質問","question":"初めに１４４ページ、こころの健康づくり事業の自殺予防講演会に関連して自殺予防についてお伺いしたいと思います。死亡原因の８位を占めるほどだということをお伺いしておりますが、どういうような告知方法で開催されたのか、お知らせください。","respondent":"福島荏原保健センター所長","answer":"そして、この前の９月１７日には鬱病対策の専門家である山口先生をお迎えをして講演会を開きました。そこで、１１２名の区民の方が参加していただいたということです。","id":"exchange-081"},{"speaker":"大倉委員","kind":"質問・要望","question":"９月１日から始まっていると伺っております。これも実績数がわかれば教えていただきたいと思うんですが、若い人たち、その実績を教えてほしいと求めました。","respondent":"福島荏原保健センター所長","answer":"ことしの９月１日から、いわゆる我々はこころの体温計と言っているんですが、それを始めました。９月の１カ月間で１万７,２２６件のアクセスがあったという報告を受けております。","id":"exchange-082"},{"speaker":"大倉委員","kind":"質問・要望","question":"大変に多いアクセス数だと思うんですが、今後こうしたストレスチェックなどを広めていくに当たってどのようにしていく必要があるのか、考えがあれば教えてほしいと求めました。","respondent":"福島荏原保健センター所長","answer":"４０代、５０代という若い人の自殺の件数が多いと、ほかの地域よりも。そういう働き盛りの人々との連携、いわゆる産業部門との連携等が必要かと思って、庁外の連絡会等が必要かと考えております。","id":"exchange-083"},{"speaker":"大倉委員","kind":"質問・要望","question":"県もあるということにお伺いしておりますが、今後もぜひ自殺予防に向けてしっかり取り組んでほしいと求めましたが、そのところを少しお話しほしいと求めました。","respondent":"福島荏原保健センター所長","answer":"既に７月１５日には庁内の職員を対象にして実施してまいりました。今後もさらに充実を目指していきたいと考えています。","id":"exchange-084"},{"speaker":"大倉委員","kind":"質問","question":"最後に、自殺予防で、国では２０％削減目標が、平成２８年までで現在の２０％削減するという目標があると伺っておりますが、品川区でもそうした目標があるのか、お聞かせいただき、もう一度同じ質問になってしまいますが、それに向けてどういった取り組みをしていくのかを説明を求めました。","respondent":"福島荏原保健センター所長","answer":"品川区の目標としましては、平成３０年度までには１９％以下に、死亡率を１９％以下に下げるということをとりあえずの目標としております。それから、そういう鬱とか自殺をしようとなさっている方へのいわゆる支援というものが、周りの人の支援等が必要と考えて。","id":"exchange-085"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ、最初の目標は１９％と伺いましたが、ゼロを目指してこれからも頑張っていっていただきたいなと思います。ちょっと確認でそこを教えていただきたいのと、水泳教室１１１人とありますが、そこの辺を説明を求めました。","respondent":"小川健康課長","answer":"そちらから事業の内容に応じて、例えば医療費等ですとか、公害健康被害予防事業等、１０分の１０の補助が出ているものです。こちらは、主にお子さんが中心に対象となっていますが、ぜん息をお持ちのお子さん、あるいはご家族の方を対象にした事業です。","id":"exchange-086"},{"speaker":"大倉委員","kind":"質問・要望","question":"水泳教室なんですが、延べ１１１人ということですが、これはどういった告知をしているのか。箇所数、どこの水泳教室に通って、これを利用できるのかというのがわかれば教えてほしいと求めました。","respondent":"小川健康課長","answer":"水泳教室の場所は、荏原文化センターで、回数は全部で計６回で、参加者数は２７名で、延べ１１１人という状況です。ＰＲの仕方としましては、広報しながわを中心にＰＲをしておりまして、毎年多くの方に参加をしていただいているところです。","id":"exchange-087"},{"speaker":"大倉委員","kind":"意見","question":"ちょっとぜん息でやっぱり体力がないのと、やっぱり親御さんがついていかなきゃいけないという部分ではちょっと通いにくいのかなと。大井、そうしたところを利用しながらこうした予防政策をしていくお考えはあるのかな、１つ説明を求めました。","respondent":"小川健康課長","answer":"この水泳教室は、機能訓練の一環ですが、また、相談事業の一環としてぜん息健康教室というものがあります。対象者については年齢が微妙に差がありますが、そういった意味では地域的にはバランスがとれていると考えておるところです。","id":"exchange-088"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は成果報告書１４６ページの食育推進事業、１４９ページのマイバッグ運動推進、この２点で伺います。それとあとケーブルテレビなどが有効な手段だと思われますが、どう活用されているのかをまず１点伺います。","respondent":"小川健康課長","answer":"実際に１回の委託料、会場費込みで６万４,７２０円の委託料を支払っているところですが、大体８万円弱ぐらいはかかるのではないかと考えています。そういった面で、委託の中でかなり栄養士会に頑張っていただいているというふうに認識しています。","id":"exchange-089"},{"speaker":"渡辺委員","kind":"質問・要望","question":"食育のまさしく趣旨、目的が日常の中で生かされている視点を感じたものですから、伺ってみました。やはり区民の方が行政発信の情報というのは非常に求められていると思いますが、あるいは今後の展開、総論で伺えればと思います。","respondent":"小川健康課長","answer":"当然区が主催ということであれば、区民の方にとっても信用度が増しますし、その辺で特に料理教室なども人気が高いというふうに考えておるところです。毎年同じように綿々とやるということではなく、いろいろ工夫を重ねつつ…","id":"exchange-090"},{"speaker":"渡辺委員","kind":"確認","question":"この委員会等でも、各委員会でもいろいろな視点から取り上げられていると思いますが、もう一度ちょっと総論で伺いたいと思います。これをもう一度確認したいのと、対象はどうなのか、ここをお知らせください。","respondent":"野呂瀬環境課長","answer":"ごみの減量、資源の節約、ひいてはＣＯ２の削減にもつなげるということで取り組んできたものです。対象ですが、これは広く一般区民を対象として、今現在は区の商店街連合会で運営していただいている事業です。","id":"exchange-091"},{"speaker":"渡辺委員","kind":"質問","question":"もう平成１４年からですから、一定期間されてきて、行動が伴っているというのが１つポイントだと思います。ここまでの目的達成に対する評価、そして今後はどういうふうに取り組んでいくのか、伺えればと思います。","respondent":"野呂瀬環境課長","answer":"レジ袋削減運動もその後高まってまいりまして、平成１４年から約１０年たったところですけれども、一定の見直しを図るです。２年前まではマイはし運動とか、さまざまな取り組みを通じて、環境啓発のためにさまざまな取り組みをこの中でやってきたです。","id":"exchange-092"},{"speaker":"渡辺委員","kind":"確認","question":"その確認と、あともう１点、ごく最近だったと思います。ですから、いろんな工夫があるかと思いますので、その辺の展開のあり方と空き缶のところとはしのところを伺えればと思います。","respondent":"野呂瀬環境課長","answer":"やはり区民と一緒になって環境に対する啓発というものはこれも必要ですので、行政評価を受けながら取り組んでまいりたいと思っているところです。マイはしについては、間伐材を利用した木材製品のＰＲ等は、これから今後も引き続きしていきたいと考えているところです。","id":"exchange-093"},{"speaker":"浅野委員","kind":"質問","question":"先ほど他の委員から平成２２年度の各がん検診の受診率は伺ったので、ここでは質問はしませんが、進めていかなければならないと思います。これはもう皆さんご存じのことかと思いますが、区はそのような早期発見、早期治療がいいと、そのように考えておられるのか、お伺いします。","respondent":"小川健康課長","answer":"基本的には国の指針に基づいた検診を、繰り返しになりますが、しっかりとやっていくです。本当にとても重要なことだと考えておりまして、だからこそがん検診についてもしっかりとやっていくということで取り組んでいる次第です。","id":"exchange-094"},{"speaker":"浅野委員","kind":"質問","question":"両方の検査をやるべきだというような質問に対しましても、厚生労働省のほうから積極的に取り組むという答弁があったところであります。ぜひとも区民の命を守る、この取り組みをしていってほしいと求めましたが、いかがか尋ねました。","respondent":"小川健康課長","answer":"特に無料クーポン券ということで今年度から事業を進めたところですが、今年度につきましては、無料クーポン券の配布というものには踏み切らなかったです。","id":"exchange-095"},{"speaker":"浅野委員","kind":"質問・要望","question":"地球温暖化防止対策実行計画第２次にも対応していて、それともリアルタイムに、また自動的に集約できるような施設なのか。価格としては１,６８０万円かかっていますので、相当立派なものかと思いますので、どのような特筆すべき機能を持っているのか説明を求めました。","respondent":"野呂瀬環境課長","answer":"月ごとに把握しておるところです。約２６０施設ぐらいありますけれども、その管理をするということで、経費がちょっと高くなったです。","id":"exchange-096"},{"speaker":"浅野委員","kind":"質問・要望","question":"１,６８０万円、こちらのほうには何か対応するような内容が入っているのかどうかということを１つお伺いしたいのと、平成２２年度の排出量の実績。もっと早く結果は出せるのではないかなと思いますが、今年度はどうかということと来年度以降の大体の実績の提出時期について説明を求めました。","respondent":"野呂瀬環境課長","answer":"できるだけ早い時期に集計して、発表していきたいとは考えてあります。これは毎年１回ずつ、経済産業省とか環境省、これについてはそれぞれの提出時期に合ったような形で提出していくと考えております。","id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"１２.４％に逆にこれは削減となっているはずなんですが、たしか平成２０年度の実績の報告の際は、この違いを教えてください。電力使用量、電力排出係数の件ですけれども、このような算出方法になっている件についても教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"区では、排出権取引などの複雑に加味した数値よりも実際に排出されるＣＯ２の量で表現するほうが明確で区民の方にわかりやすいと考え。より区民の皆様にわかりやすいような方法で今後も周知していきたいと考えておるところですので、ご理解よろしくお願いいたします。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"それから、今あるさまざまな事業の中でのリンクするものがあるのかどうか。全くなく、新規というふうな考え方でやっていくのかについてお聞きします。","respondent":"小川健康課長、福島ものづくり・経営支援課長","answer":"２つ目に、委員ご指摘の区民健診、それから歯科健診等、健診等をきちっと受けていただくということが柱立てにあります。要介護にならないための例えばふれあい健康塾ですとか… 予算はございませんけれども、来年度につきましては、経済産業費には入るかと思いますけれども、どちらに入れるか、今後検討していきたいと思います。区内の産業、あるいは企業の振興に十分寄与すると思いますので…","id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"この２つをどういうふうにリンクをされているんですかということなんです。でいうならば、この業務内容というのはどの辺までカバーしたものが品川区で考えておられるのか、お聞きしたいと思います。","respondent":"榎本高齢者医療担当課長、福島ものづくり・経営支援課長","answer":"約２割ほどの方が応募して、行いたいということで手を挙げられまして、その保健指導というものを行っております。一定程度の効果を上げているものです。 それが主ですし、また、ハローワーク職業相談員によるきめ細かな職業相談、職業紹介の実施、それが中心になります。４階に東京商工会議所品川支部等もありますので、そういった経済関係団体と連携した企業支援…","id":"exchange-100"},{"speaker":"西本委員","kind":"提案","question":"してほしいというふうな意見ですが、それに関してお聞きします。そういう特別な相談員というものを設置するというお考えを今後持っていただきたいという提案なんですけれどもとの意見を述べました。","respondent":"榎本高齢者医療担当課長、福島ものづくり・経営支援課長","answer":"委員から各種団体等との連携もしくはご紹介等ができているかというご質問だったと思います。今後は、医師会とも連携して、より一層区民の団体の方々と協力し合って事業を進めてまいりたいと考えています。 求職者の利便性を図る、そういうところから始めていきたいと考えていますので、ご理解をお願いいたします。","id":"exchange-101"},{"speaker":"南委員","kind":"質問","question":"お話も私どもも伺っておりまして、それから０.１５、こういう状況で私も非常に深刻にこの問題を受けとめているところです。私はもっと測定箇所を増やすべきだ、どういうふうに品川区としては考えておられるのか、まず伺いたいと思います。","respondent":"野呂瀬環境課長","answer":"やはり区内のこの２２.７km2の中で、測定箇所を今定点測定で、品川保健センターと荏原保健センターの２カ所で定点観測を行っているところです。どちらも空間線量基準は下回っておりまして、したがいまして、測定箇所を増やすようなことは今のところ考えてございません。","id":"exchange-102"},{"speaker":"南委員","kind":"質問","question":"その点をまずちょっと見解を伺いたいと思います。こういう原則に立たなきゃいけないと思っているんですけれども、そこについてもどういうふうに考えるか、伺います。","respondent":"野呂瀬環境課長","answer":"そうすると、年間１ミリシーベルトに対して今区内の放射線量は大体０.３ミリシーベルトというぐらいで、大体３割ぐらいの数値が出ているです。したがいまして、安心な数値でないかというふうに考えているところです。","id":"exchange-103"},{"speaker":"南委員","kind":"質問","question":"ですから、閾値がない。こういうチェルノブイリの事故の実態をどのように検証しておられるんか尋ねました。","respondent":"野呂瀬環境課長","answer":"ヨウ素１３１というものが甲状腺に広がるということで、初期対応ということが非常に重要であるです。ただ、それでも１ミリシーベルトを超えたとしても、それはがんになる可能性が否定できないということで、１ミリシーベルトを定めているです。","id":"exchange-104"},{"speaker":"南委員","kind":"質問","question":"こういう安心感を与えるのが行政の仕事じゃないんですか。滑り台の下だとか、そういうところも含めてしっかりやるべきだと思っていますけれども、それについていかがか尋ねました。","respondent":"岩田都市環境事業部長","answer":"それを精密に現在２カ所において継続的に調査をしている。一番大事なのは、この数値に大きな変化があったときにきちっと対応していくというのは行政として大切なことだということで今やっていることですので。","id":"exchange-105"},{"speaker":"南委員","kind":"質問・要望","question":"昔からのどうのこうのって今長々と説明していただきましたけども、実際にはかって大丈夫なんだと、そこをきちんと検証して出すべきだと思うんです。ぜひやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-106"},{"speaker":"山内委員","kind":"質問・要望","question":"どういうものなのかといったことをしっかりと区民のそういった家族にしていただきたいという思いがいたしています。やはりこれから１２月、１月が最も感染するであろうと言われているこのウイルスなので、いかがでしょう。","respondent":"伊津野保健予防課長","answer":"そういう努力もありまして、最近になってＲＳウイルスの認知度が徐々に高まってきたところであります。特にことしはＲＳウイルスの立ち上がりが高いという情報もありますので、今後もＲＳウイルスについては周知を徹底していきたいと思います。","id":"exchange-107"},{"speaker":"山内委員","kind":"質問・要望","question":"何というんですかね、もしできるのであれば、やっぱりそういったことでしていただければなと思います。ですから、もう一度なんですが、区としてどういった周知ができるのかということをお答えほしいと求めました。","respondent":"伊津野保健予防課長","answer":"ＲＳウイルスというものが髄膜炎の次に小児の感染症としては怖いものだというご意見もありますので、今後も周知に努めていきたいと思います。特に区として行っている事業としましては、乳幼児健診も行っておりますので、その際のＰＲというものを考えていきたいと思います。","id":"exchange-108"},{"speaker":"山内委員","kind":"質問","question":"伺いましたところ、その相談件数というんですか、これが年々増えているのか。それで、今後はどんな感じで推移していくのか、そのあたりをお伺いします。","respondent":"福島ものづくり・経営支援課長","answer":"こちらにあります海外進出推進事業のうちの国際化対応相談員謝礼等ですけれども、こういう国際対応相談員を雇っているというものがあります。支援講座などでは、タイに進出したいという企業が集まってまいりますので、そのような効果も上がっているというふうに考えてあります。","id":"exchange-109"},{"speaker":"山内委員","kind":"質問・要望","question":"これは１社がそこに、その決算のあらましというか、そういったことでよろしいのでしょうか。それから、その１社といったものが、これがどのような形で契約をされているのかといったことを説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"１カ月借りた企業と３カ月借りた企業がございました。そういう企業もございましたので、そこを足がかりにして現地視察をし、工場建設予定地を探しているというようなことを聞いてあります。","id":"exchange-110"},{"speaker":"山内委員","kind":"質問・要望","question":"そういったことをどう払拭をしていいのか、私にはちょっとわからないんですよね。だから、その辺のアドバイスがあったら教えていただきたいんですけど。","respondent":"福島ものづくり・経営支援課長","answer":"そこが行われることによりまして、一企業が大きくなっていく、形態が大きくなっていくんだろうというふうに考えてあります。そうしたものの総体としまして、品川区の地域産業が貢献できる、地域の育成に貢献できるというふうに考えてあります。","id":"exchange-111"},{"speaker":"山内委員","kind":"質問","question":"まあ、頭のかたいと言ったらいいんですかね、そういった方にはなかなかどうしても理解をしていただけない。週に１回、１社とか２社とか、最後にそこだけ説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"今回もタイに進出する企業６社がメタリックスで展示会を開きます。あるいはタイに工場を持っていって、そこで事業拡大が行われただとか、そういった事例を１つでも増やしていきたいと考えています。","id":"exchange-112"},{"speaker":"山元委員","kind":"質問・要望","question":"予防費の中の、１４３ページの子宮頸がんワクチン、同じく次のページの１４４ページの各種がん検診についてお伺いをさせてほしいと求めました。それに対して品川区はどのように対処して、またそういう受診する方に対してどのようなお知らせをしたのかも教えてほしいと求めました。","respondent":"伊津野保健予防課長","answer":"それを受けまして、３月８日に初回接種の差し控えと助成期間を６カ月延長するという通知を対象者に送付しております。８月になりましたら、大分在庫の状況もよくなりまして、接種者も増えている状況となっております。","id":"exchange-113"},{"speaker":"山元委員","kind":"質問・要望","question":"実はこれはご存じのように、３回やらなければ効果がないわけですよね。どういうふうにしていこうかと思っていらっしゃるか、教えてほしいと求めました。","respondent":"伊津野保健予防課長","answer":"この子宮頸がんについての事業ですが、これは国が基金をつくりまして、その半額補助という形でやっているものであります。実施主体は区でありますので、その自治体で同じような事業をやっていると思いますので、そちらで助成を受けるという形になると思います。","id":"exchange-114"},{"speaker":"山元委員","kind":"質問・要望","question":"１回８,０００円助成、これは要望ではありますけれども、これは要望として考えてほしいと求めました。これはどういうことなのかなということと、指触診検診ですかね、そのところにも７１歳以上の区民助成と書いてあります。","respondent":"小川健康課長","answer":"乳がん検診ですが、この平成２３年４月から一部検診内容が変更になりました。４０歳以上につきましては、年齢制限なしにマンモグラフィ検診を受けられるというような内容になってあります。","id":"exchange-115"},{"speaker":"山元委員","kind":"質問・要望","question":"先ほどパーセンテージ、がん検診のパーセンテージをお聞きしました。いろんなお知らせですね、それはどなたたちが考えて送られているのか、その辺をちょっとお聞きさせてほしいと求めました。","respondent":"小川健康課長","answer":"ホームページ等がわかりづらいというご指摘につきましては、わかりやすい周知方法を今後も努めてまいりたいと考えています。これはだれが考えるかということですが、基本的には職員が工夫をして考えているところです。","id":"exchange-116"},{"speaker":"山元委員","kind":"質問・要望","question":"もう１点、検診車ですが、例えば駅前にマンモグラフィの検診車ができればいいと思いますが、いかがでしょうか。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-117"},{"speaker":"木村委員","kind":"質問","question":"１４８ページの温暖化対策事業、そして、時間がございましたら、１５０ページの街角花壇維持管理から質問いたします。お願いします。","respondent":"野呂瀬環境課長","answer":"省エネルギー設備助成についてですが、これは家庭における温暖化対策ということで、平成２２年度から区民が個人の住宅に省エネルギー機器を導入する際の費用の一部を助成するものです。","id":"exchange-118"},{"speaker":"木村委員","kind":"質問","question":"例えばＣＯ２冷媒ヒートポンプ、それからエネファームという、合計４点の決算金額が８２６万円になっています。当初は、初めからこの８２６万円だったか尋ねました。","respondent":"野呂瀬環境課長","answer":"当初の予算額は６９０万円です。","id":"exchange-119"},{"speaker":"木村委員","kind":"意見","question":"６９０万円ということで差し引きしますと、１３６万円ほどが足りなくなったと思いますけれども、これはどこから補てんをしましたか。そして、平成２３年度の予算が一気に１,３８０万円になりましたが、増えた理由とか、何が増えたのか、それも２つお答えくださいとの意見を述べました。","respondent":"野呂瀬環境課長","answer":"不足額の補てんについてですが、当初事業計画では定数を超えた場合は抽選という予定でございました。省エネ型ライフスタイルの促進と平成２２年度の申し込み状況を踏まえまして、エネファーム等高額な機器の件数を増やしたものです。","id":"exchange-120"},{"speaker":"木村委員","kind":"意見","question":"３月１１日の大震災以降、大変ご迷惑をおかけして、この猛暑を何とか乗り切ることができました。しかし、太陽ソーラーシステムのような自然エネルギー助成に重点を置くべきと考えますが、本区のお考えを説明を求めました。","respondent":"野呂瀬環境課長","answer":"区ではこれまで地球温暖化対策推進計画に基づきまして、太陽光発電システム等の導入促進に取り組んでまいりました。今後もますます自然エネルギーの重要性が増すと思われますので、引き続き充実を図ってまいりたい、このように考えているところです。","id":"exchange-121"},{"speaker":"木村委員","kind":"質問","question":"そして、太陽光発電システムは今後どのような伸びをするとお考えですか。そして、本区として自然エネルギー、特に太陽エネルギーに対して今後どのように取り組むおつもりなのか尋ねました。","respondent":"野呂瀬環境課長","answer":"今後の伸びとしましては、１期分と同様、同程度のお申し込みがあると考えているところです。区の取り組みとしましては、今後も太陽エネルギーの活用について普及啓発に努めてまいりたい、このように考えているところです。","id":"exchange-122"},{"speaker":"木村委員","kind":"質問・要望","question":"街角というと、まちの片隅を何となく想像してしまいますけれども、実際はどのような場所に設置されている花壇なんでしょうか。それと、何となく小さくかわいらしい花壇のようですけれども、大きさはどのぐらいか尋ねました。","respondent":"藤田水とみどりの課長","answer":"平成元年のころからこの街角花壇の設置をしておりますけれども、まちのちょっとした片隅にでもお花があるといいよねということで植え始めた事業です。それから大きさ的にも、大きいものは１０平米ほどありますけれども、小さいものについては１平米、２平米程度のものもあります。","id":"exchange-123"},{"speaker":"木村委員","kind":"質問","question":"そしてまた、その場所代というのか、そういう地代といいますか、それは払っているでしょうか。そしてこの事業の目標というか、コンセプトというものは何でしょうか、お答えください。","respondent":"藤田水とみどりの課長","answer":"年間約４回のお花の植えかえをしまして、水やりをやったり、あるいは雑草とりをして行っているものです。緑被率１０.９％と非常に低かったということもございまして、まちの少しの空間にもお花を植えていこうということでそもそも始めた事業です。","id":"exchange-124"},{"speaker":"木村委員","kind":"意見","question":"大体平均が３平米ということで、これからもっとこれを増やす計画はありますか。そして、これからも区の事業としてやっていくのでしょうけれども、将来的にはこの花壇をどのようにしたらいいか、したいか、お答えくださいとの意見を述べました。","respondent":"藤田水とみどりの課長","answer":"そういったような形で花植えをこれからも続けていきたいと考えています。街角花壇につきましても、この後ボランティアの人たちによる管理に移行していきたいと考えています。","id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"私は成果報告書１５４ページ、中小企業対策費の中で、またその融資あっせんと、それから海外進出推進費についてお聞きしたいと思います。実際救済効果として、これは明確にあらわれているんでしょうか、説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"少なかったというのは、対前年比少なくなっていたという、２３区の中の報道でございました。それ以外にもさまざまな形でお金が回っているということで、経済波及効果は大きかったのではないかと考えています。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"確かに品川区としてしっかり支援しているというのはわかるんですが、このことに対してきちっと把握しているんでしょうか。何か別の、その辺についてどのように考えておられるか、説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"品川区でもそういった支援もしていますし、期間が延びたときにそれに対する利子補給ですとか、そういう形も行っています。さらに今後の経済状況をよく見ながら、来年度予算どうするか、よく検討していきたいと考えています。","id":"exchange-127"},{"speaker":"須貝委員","kind":"意見","question":"大手も堂々と、これから日本でやっている、世界全体でやっている４割から５割は海外で生産していかなきゃいけない。難しいかもしれないけど、何かやっていかなきゃいけないかと思うんですが、その辺に対してもう一度だけ何か対策は考えておられますかとの意見を述べました。","respondent":"福島ものづくり・経営支援課長","answer":"区内産業のネットワーク化を図るということで、商談会を中心とした支援を行いまして、実際にその商談会で成立した取引に対して区として支援をする。そういった事業も立ち上げまして、そこにつきましては好評なうち第１回目が終わりましたので…","id":"exchange-128"},{"speaker":"須貝委員","kind":"意見","question":"これは新聞でも出ていますが、ソニーでもキヤノンでも、対ユーロ、１円円高になれば数十億円の赤字を生んでしまう。そうしたら、タイだけでやっているということも、私はおかしいかなと思うんですが、その辺についてちょっとご見解を説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"対ユーロの問題等さまざまありますけれども、確かに難しい問題で、ここで一自治体で何か解決できるというようなことではないかと思います。そこについて、実際にすぐに支援するのかといいますと、確かに貴重な税金でもありますので、よく検討してからということで考えてあります。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問・要望","question":"その中で、その人たちと対面で、私は、しっかり聞いて、政策を考えてほしいと求めました。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-130"},{"speaker":"大西委員","kind":"質問","question":"私からは成果報告書の１４４ページ、各種がん検診、それとその下の狂犬病予防および動物の愛護、これについて２点ほど伺っていきます。日本では実際にこういう事故というんですか、そういう狂犬病でのものはあるのか、どうなのかというのをちょっとお尋ねします。","respondent":"小川健康課長、工藤生活衛生課長","answer":"平成２２年度の品川区におきますがん発見率ですが、一番高い発見率で前立腺がんの０.７２％、次に高いのが胃がんの０.２６％です。 狂犬病につきましての日本についての発生等のお尋ねですけれども、日本ではいわゆる昭和３２年以来国内では狂犬病の発生はございません。ただ、海外で発生しているという事例と、あと海外で感染されまして、日本に来て判明したと…","id":"exchange-131"},{"speaker":"大西委員","kind":"質問","question":"それと、その辺のところの年齢によって何か大きな変化があるのか、ないのかということをちょっと教えてもらいたい。それと、狂犬病がほとんど発生しないのに狂犬病のことをずっとお金をとりながらやっていくということについてはどんな考え方をお持ちか尋ねました。","respondent":"小川健康課長、工藤生活衛生課長","answer":"６０歳以上、７０歳以上等が多かったりというような、満遍なく発見をされているような状況です。ただ、がんの種類、がんの検診の種類によってです。 この狂犬病、もし発症すれば、１００％の率で死亡するということで、治療方法はございません。このような危険なものであるため、いわゆる法律の中で接種が義務づけられているです。","id":"exchange-132"},{"speaker":"大西委員","kind":"質問","question":"そうすると、ちょっとその法律自体がおかしいんじゃないかという発想も１つあるんじゃないかなと思うんですけど。ここに咬傷犬被害件数というのが１５件ほどありますけれども、これは具体的にはどういう状態で、ちょっと具体的に教えていただけますか。","respondent":"工藤生活衛生課長","answer":"そうはいいましても、法律の中でやはりしっかりと対応をとらなければいけないというふうに、そういった考えで注射の義務化がされているところです。そこで公園に来た方にかみついたと、このような状況があります。","id":"exchange-133"},{"speaker":"大西委員","kind":"質問","question":"ということは、かんだのはほとんど道端でかんだとか、そういうことじゃなしに、ドッグランか何かでそういう事件が発生しているということでいいんか尋ねました。","respondent":"工藤生活衛生課長","answer":"発生につきましては、ドッグランという報告はございませんで、いずれも公園、もしくは通常の道路の中での報告というふうになってあります。","id":"exchange-134"},{"speaker":"大西委員","kind":"質問","question":"そうすると、道路というのは、それは普通リードつけていると思うんですね。どこかに責任問題が、場所において管理している側の責任もあろうかと思うんですけれども、その辺のところはどうか尋ねました。","respondent":"稲田道路公園課長","answer":"そういう看板なしで規制はしてない、規制というか、ご協力はお願いしてないような部分もあります。かみつかれた人とかみついた犬の持ち主というんですか、基本的には当事者同士の問題ということで考えております。","id":"exchange-135"},{"speaker":"大西委員","kind":"質問","question":"私が懸念するのは、区の管理している公園の中で、もしそういう表示がはっきりされてない状況の中でそういう事故が起こった場合に、区のほうに責任がかかるんじゃないかということを懸念しますが、その点はどうか尋ねました。","respondent":"稲田道路公園課長","answer":"私ども、基本的に公園は自由に使えるですので、区に責任があるというふうには考えておりません。","id":"exchange-136"},{"speaker":"本多委員","kind":"質問","question":"その次が１４５ページの環境衛生費の公衆便所費と、次の１５３ページ産業経済費の中で、そのかかわりについて質問していきます。その一部事務組合から２３区への追加分というんでしょうか、平成２３年度で見ても、説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"それから、経費ですが、足立清掃工場で約２億８,０００万円、それから光が丘で５５０万円、その他の工場で５０万円ほどの清掃費がかかったです。既存の平成２２年度の清掃一組の清掃焼却施設管理費という項目の中で…","id":"exchange-137"},{"speaker":"本多委員","kind":"質問","question":"不足になれば、それともやはり一部事務組合が自助としてやるべきだというふうに区から言うのか、その辺のところを教えてください。その状況と会議の状況と調査がどのように進んだのか説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"それから、調査につきましては、昨年の７月末から動き出しまして、８月、９月で調査を実施をいたしました。７月の千歳工場、炉が停止してから１週間以内に不適正防止検討委員会を開催をし、啓発をやったです。","id":"exchange-138"},{"speaker":"本多委員","kind":"質問","question":"再発防止をいろいろと試みても再発が起きている状況ですので、さらにこの原因を追及する方法がないものか、お尋ねしたいと思うんです。例えばごみを出す側の、まあ、特定はできなくても、絞り込みというのができていけないものなんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"先ほど申し上げました調査を実施したところなんですけれども、結果的には原因が究明できなかったです。都、それから特別区、清掃一組が連携をしながら対応していくことが求められていると考えているところです。","id":"exchange-139"},{"speaker":"本多委員","kind":"質問・要望","question":"ちょっとドイツの事例を１つ挙げしますと、電化製品、出すほうの受け皿もいろいろ考えてほしいと求めました。それとも、やはり若年層というところに視点を当てていただきたいなと思うんですが、その年齢層階級別みたいな着眼点について説明を求めました。","respondent":"矢野品川保健センター所長","answer":"私からは健康学習で若年層の部分の対応についてお答えします。特に品川区では児童センターと保健センターでかなり連携をして健康学習をしたり、区内にある大学等の学園祭等に健康学習で出張したりしております。","id":"exchange-140"},{"speaker":"本多委員","kind":"質問・要望","question":"これはかなり前ですか、そういったところをもう少しこの健康づくりというところで充実をしていただきたいなと思うんですが、その辺について説明を求めました。","respondent":"小川健康課長","answer":"その上部の計画でもあります長期基本計画でも区民の健康づくりの大切さについては十分認識しているものです。健康センターという立派な施設もあることから、そのような年齢層の方も十分利用されていただいているというふうに認識しています。","id":"exchange-141"},{"speaker":"本多委員","kind":"質問","question":"ほかの質問に移ります。コンビニエンスストアというのが区内に約２００ぐらいあると思うんですが、提携ができないか、ちょっとお答えほしいと求めました。","respondent":"稲田道路公園課長","answer":"現在公衆便所３８カ所、公園便所、児童遊園便所が１２３カ所、全部で１６１カ所ありますが、今後そういうコンビニ等、要望もございまして、検討に入りたいというふうには考えております。","id":"exchange-142"},{"speaker":"武内委員","kind":"質問","question":"平成２１年度は３６９件、また平成２２年度は成果報告書にあるように４７７件と、使い勝手がよくなっているです。１点、おととし伺ったときには９９件というお答えいただいたんですが、その後現状でどれくらいになっているか説明を求めました。","respondent":"小川健康課長","answer":"平成２１年度で妊娠に至った数が９２件、平成２２年度では９９件です。","id":"exchange-143"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、累計で平成２２年度現在で９９件ということなんでしょうか。平成２１年の１０月６日の決算特別委員会で伺ったときに９９件というふうに伺ったんですけれども、そうすると、こういうことなんでしょうかね。","respondent":"小川健康課長","answer":"平成２０年度が純粋に９７件でございました。累計をいたしまして合計で平成２２年度末で２８８件の妊娠に至ったです。","id":"exchange-144"},{"speaker":"武内委員","kind":"提案","question":"おととしの平成２１年の決算特別委員会のときにも提案させていただいたんですけど、事務事業概要にも、妊娠に至った方の。そういう件数を載せていただいたらどうかなというご提案して、また改めてそういう形はどうかなと思うんですけど、いかがか尋ねました。","respondent":"小川健康課長","answer":"平成２２年度でいいますと９９件が妊娠に至ったと言えるものではなく、申請時において不明の方もまだいらっしゃいます。このようなことから載せなかったです。","id":"exchange-145"},{"speaker":"武内委員","kind":"質問・要望","question":"要望しておきます。これについての区の認識、もしくは見解を教えてほしいと求めました。","respondent":"矢野品川保健センター所長","answer":"啓発に努めてまいりたいと考え、不育症の研究班のサイトにリンクできるように設定しまして、正しい知識が周知できるように努めております。個別の相談には丁寧にきめ細かく対応を心がけていきたいと考えております。","id":"exchange-146"},{"speaker":"武内委員","kind":"質問・要望","question":"２月の定例会のときに、相談体制ということでお聞きをしたときに、多分。もう１回、しっかりと取り組んでほしいと求めましたけど、いかがか尋ねました。","respondent":"矢野品川保健センター所長","answer":"今年度も女性の健康週間で取り上げする予定ですが、不育症については、もう少しそこに行き着く、アクセスがしやすいように検討してまいりたいと思います。","id":"exchange-147"},{"speaker":"武内委員","kind":"質問・要望","question":"それで、この間の定例会のときにそれとあわせまして助成制度創設を求めました。まだまだ低いわけですけれども、そうしたことも今後検討していただきたいと思うんですけど、その辺のご見解を説明を求めました。","respondent":"矢野品川保健センター所長","answer":"助成につきましては、不育症の原因がさまざまですし、検査や治療方法について今後の進展を注視しながら、また国の施策の動向を踏まえながら検討してまいりたいと考えております。","id":"exchange-148"},{"speaker":"武内委員","kind":"質問・要望","question":"２年ぐらい前から求めていますけれども、２３区どこよりも先駆けて、これをぜひ検討していただきたいと要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-149"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は成果報告書の１４２ページの保健衛生総務費と、それからその次の予防費、それと１４５ページの保健指導費についてお伺いしたいと思います。この実績に対してまず区の評価を説明を求めました。","respondent":"小川健康課長","answer":"こちらの休日・応急診療につきましては、休日ですとか、夜間の区民の方の医療の不安を払拭させるということを目的に行っておるものです。休日や土日夜間等の対応をさせていただいているところでございまして、やはり医療不安に対してはそれなりの効果があると考えているところで…","id":"exchange-150"},{"speaker":"鈴木（博）委員","kind":"提案","question":"先ほど阿久津委員のほうから電話相談なんかをうまく使ったらどうかというご提案もあったんですが、前回お聞きした保育園やチャイルドステーション。このような啓発活動を非常に強化することが非常に軽症の患者の受診の抑制になるのではないかと思うんですが、いかがか尋ねました。","respondent":"矢野品川保健センター所長","answer":"出張健康学習という形で、乳児期前期母親学級の後の自主グループなどで医療機関のかかり方などのお話をしております。今後そのようなパンフレット等の作成も検討してまいりたいとは思っております。","id":"exchange-151"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そして次に、１４２ページ、同じページの成果報告書の予防接種費についてお尋ねいたします。これは無料で接種できるので、基本的には勧奨だけということで、このうちの麻疹については後ほど改めてお伺いしたいと思います。","respondent":"伊津野保健予防課長","answer":"２月から４月生まれのお子さん、８１６名に４月から７月にかけましてお知らせを発送しまして、そのうち４３７名の方が接種されております。今後また接種者も増えることとは思いますが、暫定的な受診率としましては５３.５％となっております。","id":"exchange-152"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"したがって、今後一層の啓発が必要だと考えられますので、これは要望ですが、さらに一層の取り組みをよろしくお願いいたします。それから十分な保障のもとで行える定期接種化の実現のためにさらに強い働きかけが必要だと思いますが、区のご見解をお伺いしたいと思います。","respondent":"伊津野保健予防課長","answer":"現在、ヒブ、小児肺炎球菌、子宮頸がんワクチンにつきましては、緊急促進事業において、国からの２分の１の補助を受けて実施しているものであります。国の検討会でも定期化に向けまして進めているところでありますので…","id":"exchange-153"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"より一層、これは要望なんですが、区からのご検討をお願いしたいと思います。２つのちょっと性格が違うワクチンが出るわで、ガーダシルのその使い分けに関しては、区の見解をちょっとお伺いしたいと思うんです。","respondent":"伊津野保健予防課長","answer":"ただ、子宮頸がんになると言われていますハイリスクの１５のタイプにつきまして効くものは、そのうちの１６、１８で、全く同じであります。１１のタイプにそれが追加になっておりますので、全く同じと考えておりますので、区の見解としてはそういうふうに思っております。","id":"exchange-154"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ところが、実際子どもの死亡の原因の第１位は不慮の事故なんですよね。随分来ますので、非常に事故対策というのは大切なことだと思いますので、要望としてこれもぜひ非常に取り組みを強化してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは１４４ページの成人歯科健診と１５４ページの中小企業活性化・住宅リフォーム助成事業についてお聞きしたいと思います。平成２１年、平成２２年と受診者数が広がっていない、区のほうで広げていく対策などはおとりか尋ねました。","respondent":"小川健康課長","answer":"歯科医師会とも相談しつつ、今年度成人歯科健診の案内のご通知を少し見やすく工夫をいたしました。受診者の対象者には直接通知が行くようなシステムになってありますので、そちらのまた成果を来年度見てみたいと考えているところです。","id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問","question":"ので、この健診のお知らせが歯科にかかるきっかけになっているんだなというのは少なからずも実感してきました。乳幼児や妊産婦、また高齢者あたりが中心に行われている指導状況なのかなと思うんですけれども、そこら辺はどうか尋ねました。","respondent":"矢野品川保健センター所長","answer":"最近は高齢化に伴って、咀嚼嚥下の機能を向上したり、維持したいということで健康教育のご要望もあります。健康づくり推進委員の講演会などでは、高齢者だけじゃなくて、そういう部分でも健康教育を実施しております。","id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、やはり前にもほかの委員から質問ありましたけれども、２０代、３０代から健診、そしてきっかけをつくっていく。２０代、３０代、ここはいかがか尋ねました。","respondent":"小川健康課長","answer":"成人歯科健康診査につきましては、ご指摘の歯周病予防のための対策が特に必要な年代に絞って事業を実施させていただいているところです。ＰＲ、啓発等をしていますので、健診そのものについての拡大は今のところは考えてございません。","id":"exchange-158"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ歯周疾患、ぜひ早い段階から発見できるような対策、検討していただきたいなと要望したいと思います。一般質問でも取り上げられてきたことですけれども、助成額、総事業費を教えてほしいと求めました。","respondent":"柏原住宅担当課長","answer":"今年度から実施しております住宅改善工事助成事業の実績です。それから、対象の工事金額につきましては２,５００万円ほどです。","id":"exchange-159"},{"speaker":"石田（ち）委員","kind":"質問","question":"申請件数のところで、エコのところのＬＥＤ設置工事は、２３件の中で何件か尋ねました。","respondent":"柏原住宅担当課長","answer":"ＬＥＤの工事助成につきましては、現在までのところ、個人住宅、マンション管理組合等々含めまして、９件です。","id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問","question":"申請件数が１０８件と、３６.２倍もの効果があったと、同じ内容だというふうに受けとめてよろしいんか尋ねました。","respondent":"柏原住宅担当課長","answer":"今年度の住宅改善工事助成につきましては、区内業者の振興というところで、まず１つの区内事業者の活性化というところは同じ目的を持ってあります。バリアフリー化等々による住環境の整備、こういった目的を持っていまして、大きな２つの柱で始めたというものです。","id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういうもとでも、なぜ対象を狭めたのか。これ、なぜ狭めてしまったのか、説明を求めました。","respondent":"柏原住宅担当課長","answer":"環境対策、こちらの住宅改善工事助成事業に入れておりますので、単純に狭めたというところではちょっと比較はできないのかなと思ってあります。あくまで中小企業の活性化と住環境の整備ということで行ってあります。","id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、なぜ狭まってしまったのか。どうして一般リフォームにまで伸ばせないのかということを説明を求めました。","respondent":"柏原住宅担当課長","answer":"我々としては、狭めたという認識は持ってございませんで、必要な部分に対して必要な助成をやっていこうという考えに立ってあります。周知等々もこれからもっとやっていかなくちゃいけないという部分は考えてありますので、そちらも充実させたいと思ってあります。","id":"exchange-163"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区のほうの見解とやはり現場の声は全く違うものになっているんですね。ですので、やはり見直しと復活を進めていっていただきたいと強く要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-164"},{"speaker":"井上委員","kind":"質問","question":"１５０ページ、１５２ページ、廃棄物対策費についてお伺いをいたします。１点目に健康センター事業費のことについて、決算書ではなぜこういったものを示さないのか、お考えを伺います。","respondent":"小川健康課長","answer":"先ほどの利用料金収入見込というのは、先ほどもご答弁した１億５,４５０万円ちょっとの金額のことだと考えていますが、予算書の段階では利用料収入を見込んでマイナスというような形で予算書の記載をさせていただいたところだと思いますけれども。","id":"exchange-165"},{"speaker":"井上委員","kind":"質問・要望","question":"そういった表記も検討してほしいと求めましたが、そういった考えがあるのか、お伺いをいたします。その理由を説明を求めました。","respondent":"榎本企画財政課長、小川健康課長","answer":"今の利用料金の収入の関係ですけれども、指定管理者の施設全体に関わることなので、その辺、どういうふうに一番表記したらいいかということを検討していきたいと思います。 こちらの中身につきましては、当初の予算では指定管理者への運営委託という位置づけで、冷温水設備等の老朽取りかえというものを考えてございました。こちらの運営の委託ではなく、決算の中では事業委託等の中に組み込まれたということ…","id":"exchange-166"},{"speaker":"井上委員","kind":"質問・要望","question":"予算書、決算書を見てわかるような、そういったところを工夫をしていただきたいとお願いをしていきたいと思います。一体品川区で幾つ持ち合わせているのか、そういう視点で数えたことがあるのか、把握をされているようでしたらお答えください。","respondent":"小川健康課長、久保田行財政改革担当課長","answer":"私の部分ではあくまでも健康課、保健センター関係ということで、数のとり方につきましては、私のほうで把握しているのは１０個程度というふうに考えてあります。 介護予防というところで、高齢者のところでも、広い意味では健康づくりに結びつくといったところはあります。私どもでも数を数えて把握はしてございませんけども…","id":"exchange-167"},{"speaker":"井上委員","kind":"質問","question":"この計画はもう８年がたちます。計画年度は１０年間を基本計画とし、あるいは区民の健康意識等、改定に向けたスケジュールをお伺いいたします。","respondent":"小川健康課長","answer":"ご指摘の区民健康づくりプラン品川ですが、こちらをつくるに当たって、多額の経費を用いたかなり完成度の高い計画だと認識しています。今のところ、特に改定するという予定はございません。","id":"exchange-168"},{"speaker":"井上委員","kind":"質問","question":"２０００年に介護保険がスタートして、３年後につくられまして、介護予防の考え方というのも随分変わってきました。社会情勢に合っているのかということを踏まえて、やはり見直しをすることが適正ではないかと思いますが、もう一度見解を伺います。","respondent":"小川健康課長","answer":"基本的な計画の体系については現行のままで特に問題はないと思ってありますが、個別の施策につきましては、やはりいろいろな部分で部をまたがっての調整ですとか、そういったことについては取り組んでまいりたいと考えています。","id":"exchange-169"},{"speaker":"井上委員","kind":"質問・要望","question":"これはどういった要因なのかということと、２０１１年の予算では、２０１０年度よりも２００万円ほどの増額がされています。どんなところに力を入れようとした予算編成だったのか、お伺いいたします。","respondent":"福島荏原保健センター所長","answer":"この健康づくりの事業の大半を占めているのが一般賃金、医師、心理相談員への賃金費用としているのが一番多いと思われます。来年度の予算に対して増えているのは、さらに講演会等の講師の問題とか、それから、いろいろな物品を配る、その費用とかが入っていると思われます。","id":"exchange-170"},{"speaker":"井上委員","kind":"質問","question":"件数なのでこれは延べであろうというふうに推測をしますが、その中でどういった相談が多いのか、差し支えのない範囲でお伺いしたい。相談を受ける方の資格と人数、１人当たりの相談時間がどのくらいあるのか、お伺いします。","respondent":"福島荏原保健センター所長","answer":"こういう児童心理学、やっぱり家族による相談、それで必要に応じたらまた本人に会いに行けるようにできるかと思っています。１人当たりの相談の時間としては、いろいろ多々あるので、一概には言えない状況だと思われます。","id":"exchange-171"},{"speaker":"井上委員","kind":"質問","question":"多くの家族が本人や学校教育の中で精神疾患について学ぶ機会があったら、病気になったときの初期対応がもっと違ったと答えた方が９割に上っていると。そういったことを踏まえると、思春期の心の相談事業の充実と学校教育の精神疾患についての正しく学ぶ機会が必要と思いますが、区の認識を伺います。","respondent":"福島荏原保健センター所長、冠木指導課長","answer":"医療行為負担の件数が品川区だけでは３,３９７件と、人口の約１％ということですので、それはまた教育委員会等との話になるかと思います。それから家族勉強会等を通じて、広く皆さんに周知していきたいと考えておりますし… 学校におきましても、保健の時間であるとか、市民課の時間で心の健康について学習しています。","id":"exchange-172"},{"speaker":"若林委員","kind":"質問・要望","question":"それから続いて１５５ページのプレミアム付区内共通商品券、どうでしょう、大型店舗にもこの商品券を使えるように発行していただけないでしょうか。３年で終わるわけですから、その後のフォローというのはどういうふうにされているのか、この点についてお聞きしたいと思います。","respondent":"野呂瀬環境課長、稲田道路公園課長","answer":"今、サンプリングをして、週１回調査をしています。参考までに、今現在危険な数値等は出ておりません。 ふれあい作業所が公園の清掃をやられる中で、落ち葉を集めて、腐葉土化して、販売をしているというのは聞いてあります。その辺の数値等の検証等はふれあいでやっていただいて、安全かどうか、販売するという責任において……。","id":"exchange-173"},{"speaker":"若林委員","kind":"質問","question":"３億円、各商店の中ではこの５００円券が各個店に行っているわけですけれども、こういう統計というのはどういうふうにされているんでしょうか。これからどういうふうに発展していくのかと、そういうことはできるんじゃないかと思うんですが、いかがか尋ねました。","respondent":"米田商業・観光課長","answer":"いわゆる仕組みということでは、共通商品券、プレミアムを発行したときに、大変お客様がいらしていたというようなことでの評価をいただいてあります。それから、大型店の関係につきましては、また別の関係でのコラボレーションができるのではないかと…","id":"exchange-174"},{"speaker":"須藤委員","kind":"質問","question":"１４６ページ、健体康心と言っている私からも１つお願いがあるんですけれども、この最終的な区民への考え方というのはどういうことでしょうか。先ほど来言っているお子さんから、いろんな方面からという考え方になろうと思うんだけども、いかがか尋ねました。","respondent":"小川健康課長","answer":"寝たきりや認知症にならない状態で自立できる期間、いわゆる健康寿命の延伸を図っていくことが大きな課題であると考えておりまして、その願いのもとに健康づくりの推進をさまざま行っているところです。","id":"exchange-175"},{"speaker":"須藤委員","kind":"質問","question":"いわゆる死亡の３大原因というのはがんである、あるいは脳血管であるとかという、そのことに対してはどういうふうにお考えでしょうか。そのことに対してというのは、心の持ち方ということに対してはどういうふうに思っているのか、説明を求めました。","respondent":"福島荏原保健センター所長","answer":"心の健康も、これはもうＷＨＯの規約にありますように、心身ともに健康であるということが必要だと考えています。いろいろなことをやっていることはやっていますので、心もおろそかにしているというわけで決してないということだと思います。","id":"exchange-176"},{"speaker":"須藤委員","kind":"質問","question":"心疾患が１７.３％で、２３区平均が１５.６％ですから、１.７ポイント高い。天寿を全うしたという、平成２３年３月の統計では出てきているんだけども、このことについてはどういうふうにお考えか尋ねました。","respondent":"小川健康課長","answer":"そうした数字につきましては区としても課題があると考えています。そうした信念のもとに事業展開をしているという次第です。","id":"exchange-177"},{"speaker":"須藤委員","kind":"質問・要望","question":"かかりつけ医の定着促進というのは、応対件数８２６件というような数字があるんだけど、今進捗状況はどうなんだろう。このあたりの応対件数８２６件というものはどういうことなのかというのと同時に、その進捗状況がどうなのか、説明を求めました。","respondent":"伊津野保健予防課長、小川健康課長","answer":"難病の数ですが、平成２０年、２１年、２２年にかけまして、総数としましては２,６２２、２,６７６、２,９３２と、徐々に増加している傾向にあります。 区としましても、日ごろより気軽に足を運び、相談していただけるお医者さんを近所に持っていただくことは重要だと考えています。この件数につきましては、微減傾向にはありますが、引き続き医師会等と協力し…","id":"exchange-178"},{"speaker":"須藤委員","kind":"質問・要望","question":"その辺の組み合わせというのをどういうふうにしていくかというのを考えていかなきゃいけないと思うので、区民の健康を見てほしいと求めました。そのあたりを小規模商店街だけでなくて、やはり全体の商店街の振興というものについてどういうふうにお考えになっているか、説明を求めました。","respondent":"米田商業・観光課長","answer":"息子さん、娘さん等もいらっしゃるかもしれませんが、外部から入ってくる。あるいは、そういうような仕組みをつくっていくことが重要だろうと考えています。","id":"exchange-179"},{"speaker":"須藤委員","kind":"質問・要望","question":"その商店の人たちが頑張ろうと思っても、そのあたりの支援の仕方というのを考えていただきたいと思うんですが、その辺はいかがでしょうか。知恵を出して、共通商品券のあり方というものをやっていただいていると思うんですけども、そのあたりについても説明を求めました。","respondent":"米田商業・観光課長","answer":"時代は変わってまいりますので、また今後そのためにどのような方策が求められるかということについては、常々検討してまいりたいと思ってあります。そういった方々をまたいかにご支援できるかというようなことについて、今後の方策、検討してまいりたいと考えています。","id":"exchange-180"},{"speaker":"須藤委員","kind":"質問・要望","question":"いろんな事業を立ち上げたり、あるいはまた地方の商業というか、いろんな産業が品川区の商店街と連携をしてというような話もいろいろ聞いています。そういった意味で、お互いが伸びていくような仕組みを上手にこれからもしていっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-181"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/794205?Template=document&Id=1346#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":117034,"voices":414}}]);
